"use client";

import { useAdminCatalogRequests } from "@/hooks/useAdminCatalogRequests";
import { type CatalogRequestItem } from "@/lib/api/catalogRequests";
import { ClipboardList, CheckCircle, XCircle, Clock, AlertCircle, ExternalLink, Checkbox } from "@esparex/ui";
import { CatalogPageTemplate } from "@/components/catalog/CatalogPageTemplate";
import { useState, useEffect } from "react";
import { CatalogModal } from "@/components/catalog/CatalogModal";
import {
    CatalogActionsRow,
    CatalogActionIconButton,
    CatalogEntityCell,
    CatalogSelectFilter,
    CatalogRejectSuggestionForm,
    CatalogSearchInput,
} from "@/components/catalog/primitives";
import { useCatalogQueryStateSync } from "@/hooks/useCatalogQueryStateSync";
import { normalizeSearchParamValue, parsePositiveIntParam } from "@/lib/urlSearchParams";
import { useSearchParams } from "next/navigation";
import { getBrands } from "@/lib/api/brands";
import { getModels } from "@/lib/api/models";
import { parseAdminResponse } from "@/lib/api/parseAdminResponse";
import { showAdminPopup } from "@/lib/popup/popupEvents";
import { CatalogBulkRejectModal, CatalogBulkDuplicateModal } from "@/components/catalog/CatalogBulkModals";

const REQUEST_STATUS_VALUES = new Set(["all", "pending", "approved", "rejected", "duplicate", "resolved"]);

const normalizeRequestStatusParam = (value: string | null) =>
    value && REQUEST_STATUS_VALUES.has(value) ? value : "all";

export default function CatalogRequestsTab() {
    const searchParams = useSearchParams();
    const initialSearch = normalizeSearchParamValue(searchParams.get("q") ?? searchParams.get("search"));
    const initialStatus = normalizeRequestStatusParam(searchParams.get("status"));
    const initialPage = parsePositiveIntParam(searchParams.get("page"), 1);

    const [searchInput, setSearchInput] = useState(initialSearch);

    const {
        requests,
        loading,
        error,
        handleApprove,
        handleReject,
        handleBulkReject,
        handleBulkMarkDuplicate,
        pagination,
    } = useAdminCatalogRequests({
        initialFilters: {
            search: initialSearch,
            status: initialStatus,
        },
        initialPagination: {
            page: initialPage,
            limit: 20,
        },
    });

    const { replaceQueryState } = useCatalogQueryStateSync({
        searchInput,
        initialSearch,
        loading,
        initialPage,
        totalPages: pagination.totalPages,
    });

    const [rejectingRequest, setRejectingRequest] = useState<CatalogRequestItem | null>(null);
    const [rejectionReason, setRejectionReason] = useState("");
    const [isRejecting, setIsRejecting] = useState(false);

    // Bulk selection state
    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    // Bulk Reject state
    const [bulkRejectOpen, setBulkRejectOpen] = useState(false);
    const [bulkRejectionReason, setBulkRejectionReason] = useState("");
    const [isBulkRejecting, setIsBulkRejecting] = useState(false);

    // Bulk Duplicate state
    const [bulkDuplicateOpen, setBulkDuplicateOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [searchResults, setSearchResults] = useState<Array<{ id: string; name: string }>>([]);
    const [searching, setSearching] = useState(false);
    const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
    const [isBulkDuplicating, setIsBulkDuplicating] = useState(false);

    // Determine request type of selection to guide the duplicate catalog search
    const firstSelectedId = selectedIds[0];
    const firstSelectedRequest = requests.find((r) => r.id === firstSelectedId);
    const requestType = firstSelectedRequest?.requestType || "brand";

    useEffect(() => {
        if (searchQuery.length < 2) {
            setSearchResults([]);
            return;
        }
        const performSearch = async () => {
            setSearching(true);
            try {
                if (requestType === "brand") {
                    const res = await getBrands({ search: searchQuery });
                    const parsed = parseAdminResponse<any>(res);
                    setSearchResults(parsed.items.map((item) => ({ id: item.id, name: item.name })));
                } else {
                    const res = await getModels({ search: searchQuery });
                    const parsed = parseAdminResponse<any>(res);
                    setSearchResults(parsed.items.map((item) => ({ id: item.id, name: item.name })));
                }
            } catch (e) {
                showAdminPopup({
                    type: "error",
                    title: "Search Failed",
                    message: e instanceof Error ? e.message : "Unable to complete catalog search.",
                });
            } finally {
                setSearching(false);
            }
        };
        const timer = setTimeout(performSearch, 300);
        return () => clearTimeout(timer);
    }, [searchQuery, requestType]);

    const allSelected = requests.length > 0 && requests.every((item) => selectedIds.includes(item.id));
    const headerCheckedState = allSelected ? true : selectedIds.length > 0 ? "indeterminate" : false;

    const onToggleSelectAll = (checked: boolean) => {
        if (checked) {
            setSelectedIds(requests.map((item) => item.id));
        } else {
            setSelectedIds([]);
        }
    };

    const onToggleSelect = (id: string, checked: boolean) => {
        if (checked) {
            setSelectedIds((prev) => [...prev, id]);
        } else {
            setSelectedIds((prev) => prev.filter((x) => x !== id));
        }
    };

    const openBulkReject = () => {
        setBulkRejectionReason("");
        setBulkRejectOpen(true);
    };

    const openBulkDuplicate = () => {
        setSearchQuery("");
        setSearchResults([]);
        setSelectedTargetId(null);
        setBulkDuplicateOpen(true);
    };

    const confirmReject = async () => {
        if (!rejectingRequest || !rejectionReason.trim()) return;
        setIsRejecting(true);
        await handleReject(rejectingRequest.id, rejectionReason.trim());
        setIsRejecting(false);
        setRejectingRequest(null);
        setRejectionReason("");
    };

    const confirmBulkReject = async () => {
        if (selectedIds.length === 0 || !bulkRejectionReason.trim()) return;
        setIsBulkRejecting(true);
        try {
            await handleBulkReject(selectedIds, bulkRejectionReason.trim());
            setSelectedIds([]);
            setBulkRejectOpen(false);
        } catch (e) {
            showAdminPopup({
                type: "error",
                title: "Bulk Reject Failed",
                message: e instanceof Error ? e.message : "Unable to reject selected requests.",
            });
        } finally {
            setIsBulkRejecting(false);
        }
    };

    const confirmBulkDuplicate = async () => {
        if (selectedIds.length === 0 || !selectedTargetId) return;
        setIsBulkDuplicating(true);
        try {
            await handleBulkMarkDuplicate(selectedIds, selectedTargetId);
            setSelectedIds([]);
            setBulkDuplicateOpen(false);
        } catch (e) {
            showAdminPopup({
                type: "error",
                title: "Mark Duplicate Failed",
                message: e instanceof Error ? e.message : "Unable to mark selected requests as duplicate.",
            });
        } finally {
            setIsBulkDuplicating(false);
        }
    };

    const bulkActions = (
        <div className="flex items-center gap-2">
            <button
                type="button"
                onClick={openBulkReject}
                className="rounded-lg bg-amber-600 px-3 py-2 text-xs font-semibold text-white hover:bg-amber-700 transition-all shadow-sm"
            >
                Quick Reject
            </button>
            <button
                type="button"
                onClick={openBulkDuplicate}
                className="rounded-lg bg-primary px-3 py-2 text-xs font-semibold text-white hover:bg-primary/95 transition-all shadow-sm"
            >
                Quick Duplicate
            </button>
        </div>
    );

    return (
        <>
            <CatalogPageTemplate<CatalogRequestItem, Record<string, never>>
                isNested={true}
                title="Catalog Requests"
                description="Manage user-submitted requests for new brands, models, or categories. Reviewing and approving these maintains the SSOT integrity."
                createLabel="" // No manual creation of requests in admin
                csvFileName="catalog-requests.csv"
                items={requests}
                loading={loading}
                error={error}
                pagination={pagination}
                selectedCount={selectedIds.length}
                bulkActions={selectedIds.length > 0 ? bulkActions : undefined}
                setPage={(page) => replaceQueryState({ page: page > 1 ? page : null })}
                handleCreate={async () => false}
                handleUpdate={async () => false}
                defaultFormData={{} as Record<string, never>}
                formRenderer={() => null}
                generateColumns={() => [
                    {
                        header: (
                            <Checkbox
                                checked={headerCheckedState}
                                onCheckedChange={(checked) => onToggleSelectAll(checked === true)}
                                aria-label="Select all catalog requests"
                            />
                        ),
                        id: "select",
                        className: "w-12",
                        cell: (req) => (
                            <Checkbox
                                checked={selectedIds.includes(req.id)}
                                onCheckedChange={(checked) => onToggleSelect(req.id, checked === true)}
                                aria-label={`Select request for ${req.requestedName}`}
                            />
                        ),
                    },
                    {
                         header: "Request",
                         cell: (req) => {
                             const userName = typeof req.requestedBy === 'string' ? req.requestedBy : `${req.requestedBy.firstName} ${req.requestedBy.lastName}`;
                             return (
                                 <div className="flex flex-col gap-1">
                                     <CatalogEntityCell
                                         icon={<ClipboardList size={20} />}
                                         iconClassName="bg-amber-50 text-amber-600"
                                         title={req.requestedName}
                                         subtitle={`${req.requestType} • ${userName}`}
                                     />
                                     {req.listingId && (
                                         <a
                                             href={`/listing/${req.listingId}`}
                                             target="_blank"
                                             rel="noopener noreferrer"
                                             className="inline-flex items-center gap-1 ml-10 text-tiny font-semibold text-blue-600 hover:text-blue-800 hover:underline"
                                         >
                                             <ExternalLink size={10} />
                                             View Listing
                                         </a>
                                     )}
                                 </div>
                             );
                         },
                     },
                    {
                        header: "Status",
                        cell: (req) => (
                            <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded text-tiny font-bold uppercase tracking-wider ${
                                req.status === "approved" || req.status === "resolved" ? "bg-emerald-100 text-emerald-700" :
                                req.status === "rejected" ? "bg-red-100 text-red-700" :
                                req.status === "duplicate" ? "bg-blue-100 text-blue-700" :
                                "bg-amber-100 text-amber-700"
                            }`}>
                                {req.status === "pending" ? <Clock size={10} /> : (req.status === "approved" || req.status === "resolved") ? <CheckCircle size={10} /> : <AlertCircle size={10} />}
                                {req.status}
                            </span>
                        ),
                    },
                    {
                        header: "Demand",
                        cell: (req) => {
                            const count = req.requestCount ?? 1;
                            const isHot = count >= 5;
                            return (
                                <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-tiny font-bold ${
                                    isHot
                                        ? "bg-rose-100 text-rose-700"
                                        : count >= 2
                                        ? "bg-amber-100 text-amber-700"
                                        : "bg-slate-100 text-foreground-tertiary"
                                }`}>
                                    ×{count}
                                </span>
                            );
                        },
                    },
                    {
                        header: "Actions",
                        className: "text-right",
                        cell: (req) => (
                            <CatalogActionsRow>
                                {req.status === "pending" && (
                                    <>
                                        <CatalogActionIconButton
                                            onClick={() => void handleApprove(req.id)}
                                            className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-all"
                                            title="Approve"
                                            icon={<CheckCircle size={18} />}
                                        />
                                        <CatalogActionIconButton
                                            onClick={() => {
                                                setRejectionReason("");
                                                setRejectingRequest(req);
                                            }}
                                            className="p-1.5 text-orange-600 hover:bg-orange-50 rounded-lg transition-all"
                                            title="Reject"
                                            icon={<XCircle size={18} />}
                                        />
                                    </>
                                )}
                            </CatalogActionsRow>
                        ),
                    },
                ]}
                filterLayoutClassName="md:grid-cols-2"
                filtersRenderer={
                    <>
                        <CatalogSearchInput
                            value={searchInput}
                            placeholder="Search requests..."
                            onChange={setSearchInput}
                        />
                        <CatalogSelectFilter
                            value={initialStatus}
                            onChange={(status) =>
                                replaceQueryState({
                                    status: status !== "all" ? status : null,
                                    page: null,
                                })
                            }
                            options={[
                                { value: "all", label: "All Status" },
                                { value: "pending", label: "Pending" },
                                { value: "approved", label: "Approved" },
                                { value: "resolved", label: "Resolved" },
                                { value: "rejected", label: "Rejected" },
                                { value: "duplicate", label: "Duplicate" },
                            ]}
                        />
                    </>
                }
            />

            <CatalogModal
                isOpen={!!rejectingRequest}
                onClose={() => !isRejecting && setRejectingRequest(null)}
                title="Reject Catalog Request"
            >
                <CatalogRejectSuggestionForm
                    itemName={rejectingRequest?.requestedName}
                    rejectionReason={rejectionReason}
                    onRejectionReasonChange={setRejectionReason}
                    onCancel={() => setRejectingRequest(null)}
                    onConfirm={() => void confirmReject()}
                    isSubmitting={isRejecting}
                    placeholder="e.g. Duplicate request, Already in catalog, Spam..."
                />
            </CatalogModal>

            <CatalogBulkRejectModal
                isOpen={bulkRejectOpen}
                onClose={() => setBulkRejectOpen(false)}
                selectedCount={selectedIds.length}
                rejectionReason={bulkRejectionReason}
                onRejectionReasonChange={setBulkRejectionReason}
                onConfirm={confirmBulkReject}
                isSubmitting={isBulkRejecting}
            />

            <CatalogBulkDuplicateModal
                isOpen={bulkDuplicateOpen}
                onClose={() => setBulkDuplicateOpen(false)}
                requestType={requestType}
                selectedCount={selectedIds.length}
                searchQuery={searchQuery}
                onSearchQueryChange={setSearchQuery}
                searching={searching}
                searchResults={searchResults}
                selectedTargetId={selectedTargetId}
                onSelectTarget={setSelectedTargetId}
                onConfirm={confirmBulkDuplicate}
                isSubmitting={isBulkDuplicating}
            />
        </>
    );
}

"use client";

import { useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Layers, CheckCircle, XCircle } from "@esparex/ui";
import { useAdminModels } from "@/hooks/useAdminModels";
import { useAdminBrands } from "@/hooks/useAdminBrands";
import { useAdminCategories } from "@/hooks/useAdminCategories";
import { useAssignableCategories } from "@/hooks/useAssignableCategories";
import { adminModelSchema } from "@/schemas/admin.schemas";
import { normalizeObjectIdLike } from "@/lib/utils/idUtils";
import { CatalogPageTemplate } from "@/components/catalog/CatalogPageTemplate";
import { normalizeSearchParamValue, parsePositiveIntParam } from "@/lib/urlSearchParams";
import { deriveCatalogLifecycleStatus, getEntityCategoryIds, hasCategoryOverlap, resolveModalAssignableCategoryState, toCategoryOptions, validateRequiredCategoryIds } from "@/components/catalog/catalogDomainUtils";
import { CatalogCategoryTags, CatalogEntityCell, CatalogEditDeleteActions, CatalogActiveToggleButton, CatalogActionsRow, CatalogActionIconButton, CatalogSearchInput, CatalogAsyncComboboxFilter } from "@/components/catalog/primitives";
import { Model } from "@esparex/contracts";
import type { ModelFormData } from "./types";
import { ModelsFormRenderer } from "./form";
import { CatalogDeleteModal } from "@/components/catalog/CatalogDeleteModal";
import { CatalogRejectModal } from "@/components/catalog/CatalogRejectModal";
import { useCatalogTabState } from "@/hooks/useCatalogTabState";

export default function ModelsTab() {
    const sp = useSearchParams();
    const initialSearch = normalizeSearchParamValue(sp.get("q") ?? sp.get("search"));
    const initialCategoryId = normalizeSearchParamValue(sp.get("categoryId")) || "all";
    const initialBrandId = normalizeSearchParamValue(sp.get("brandId")) || "all";
    const initialStatus = normalizeSearchParamValue(sp.get("status")) || "all";
    const initialPage = parsePositiveIntParam(sp.get("page"), 1);

    const { models, loading, error, handleDelete, handleCreate, handleUpdate, pagination, handleToggleStatus, handleApproveModel, handleRejectModel } = useAdminModels({
        initialFilters: { search: initialSearch, categoryId: initialCategoryId, brandId: initialBrandId, status: initialStatus },
        initialPagination: { page: initialPage, limit: 20 },
    });

    const {
        searchInput, setSearchInput,
        deletingItem: deletingModel, setDeletingItem: setDeletingModel,
        isDeleting, setIsDeleting, closeDelete,
        rejectingItem: rejectingModel, setRejectingItem: setRejectingModel,
        rejectionReason, setRejectionReason, isRejecting, setIsRejecting, closeReject, replaceQueryState
    } = useCatalogTabState<Model>({ 
        totalPages: pagination.totalPages, 
        loading,
        initialSearch,
        initialCategoryId,
        initialBrandId,
        initialStatus,
        initialPage
    });

    const confirmDelete = async () => { if (!deletingModel) return; setIsDeleting(true); const ok = await handleDelete(deletingModel.id); setIsDeleting(false); if (ok) setDeletingModel(null); };
    const confirmReject = async () => { if (!rejectingModel || !rejectionReason.trim()) return; setIsRejecting(true); await handleRejectModel(rejectingModel.id, rejectionReason.trim()); setIsRejecting(false); setRejectingModel(null); setRejectionReason(""); };

    const { brands } = useAdminBrands();
    const { categories } = useAdminCategories();
    const { assignableCategories, assignableCategoryIdSet } = useAssignableCategories(categories);
    const categoryOptions = toCategoryOptions(assignableCategories);
    const [archivedCategoryCount, setArchivedCategoryCount] = useState(0);

    const categoryFilterOptions = useMemo(() => categoryOptions.map((o) => ({ value: o.id, label: o.name })), [categoryOptions]);
    const brandFilterOptions = useMemo(() => brands.map((b) => ({ value: b.id, label: b.name })), [brands]);

    const filterRenderers = useMemo(() => [
        <CatalogSearchInput key="search" value={searchInput} placeholder="Search models..." onChange={setSearchInput} />,
        <CatalogAsyncComboboxFilter key="category" value={initialCategoryId} onChange={(cid) => replaceQueryState({ categoryId: cid !== "all" ? cid : null, brandId: null, page: null })} options={categoryFilterOptions} allLabel="All Categories" placeholder="Search categories..." />,
        <CatalogAsyncComboboxFilter key="brand" value={initialBrandId} onChange={(bid) => replaceQueryState({ brandId: bid !== "all" ? bid : null, page: null })} options={brandFilterOptions} allLabel="All Brands" placeholder="Search brands..." />,
        <CatalogAsyncComboboxFilter key="status" value={initialStatus} onChange={(s) => replaceQueryState({ status: s !== "all" ? s : null, page: null })} options={[{ value: "live", label: "Live Only" }, { value: "pending", label: "Pending Only" }, { value: "rejected", label: "Rejected Only" }]} allLabel="All Status" placeholder="Search status..." />,
    ], [brandFilterOptions, categoryFilterOptions, initialBrandId, initialCategoryId, initialStatus, replaceQueryState, searchInput]);

    return (
        <>
            <CatalogPageTemplate<Model, ModelFormData>
                isNested={true}
                title="Models Management"
                description="Manage device models."
                createLabel="Add Model"
                csvFileName="models.csv"
                items={models}
                loading={loading}
                error={error}
                pagination={pagination}
                setPage={(page) => replaceQueryState({ page: page > 1 ? page : null })}
                handleCreate={handleCreate}
                handleUpdate={handleUpdate}
                defaultFormData={{ name: "", brandId: "", categoryIds: [], parentModelId: null, variantOfModelId: null, isParentModel: false, isActive: true }}
                validationSchema={adminModelSchema}
                customSubmitValidation={(fd) => {
                    const ce = validateRequiredCategoryIds(fd.categoryIds); if (ce) return ce;
                    if (fd.categoryIds.length > 0) { const sb = brands.find((b) => b.id === fd.brandId); if (!hasCategoryOverlap(sb, fd.categoryIds)) return "Selected brand is not mapped to any of the selected categories"; }
                    return null;
                }}
                onModalOpen={(item, setFormData) => {
                    if (item) { const r = resolveModalAssignableCategoryState(item, assignableCategoryIdSet); setArchivedCategoryCount(r.archivedCategoryCount); setFormData({ name: item.name, brandId: normalizeObjectIdLike(item.brandId), categoryIds: r.assignableCategoryIds, parentModelId: null, variantOfModelId: null, isParentModel: false, isActive: item.isActive }); }
                    else { setArchivedCategoryCount(0); }
                }}
                generateColumns={(openEditModal) => [
                    { header: "Model", cell: (m) => <CatalogEntityCell icon={<Layers size={20} />} iconClassName="bg-blue-50 text-blue-600" title={m.name} /> },
                    { header: "Brand / Categories", cell: (m) => { const b = brands.find((br) => br.id === normalizeObjectIdLike(m.brandId)); return <div className="text-xs space-y-1.5"><div className="text-foreground font-bold">{b?.name || "Unknown Brand"}</div><CatalogCategoryTags categoryIds={getEntityCategoryIds(m)} categories={categories} /></div>; } },
                    { header: "Status", cell: (m) => <CatalogActiveToggleButton isActive={m.isActive} onClick={() => void handleToggleStatus(m.id)} /> },
                    { header: "Approval State", cell: (m) => { const ls = deriveCatalogLifecycleStatus(m); return <span className={`px-2 py-0.5 rounded text-tiny font-bold uppercase tracking-wider ${ls === 'active' ? "bg-emerald-100 text-emerald-700" : ls === 'pending' ? "bg-amber-100 text-amber-700" : ls === 'rejected' ? "bg-red-100 text-red-700" : "bg-slate-100 text-foreground-secondary"}`}>{ls}</span>; } },
                    { header: "Actions", className: "text-right", cell: (m) => { const ls = deriveCatalogLifecycleStatus(m); return <CatalogActionsRow>{ls === 'pending' && <><CatalogActionIconButton onClick={() => void handleApproveModel(m.id)} className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-all" title="Approve" icon={<CheckCircle size={18} />} /><CatalogActionIconButton onClick={() => { setRejectionReason(""); setRejectingModel(m); }} className="p-1.5 text-orange-600 hover:bg-orange-50 rounded-lg transition-all" title="Reject" icon={<XCircle size={18} />} /></>}<CatalogEditDeleteActions onEdit={() => openEditModal(m)} onDelete={() => setDeletingModel(m)} /></CatalogActionsRow>; } },
                ]}
                filterLayoutClassName="md:grid-cols-4"
                filtersRenderer={<>{filterRenderers}</>}
                formRenderer={(formData, setFormData, isEditing, editingItem) => (
                    <ModelsFormRenderer formData={formData} setFormData={setFormData} isEditing={isEditing} editingItem={editingItem ?? undefined} brands={brands} categoryOptions={categoryOptions} archivedCategoryCount={archivedCategoryCount} />
                )}
            />
            <CatalogDeleteModal
                isOpen={!!deletingModel}
                itemName={deletingModel?.name || ""}
                isDeleting={isDeleting}
                onClose={closeDelete}
                onConfirm={confirmDelete}
            />
            <CatalogRejectModal
                isOpen={!!rejectingModel}
                itemName={rejectingModel?.name || ""}
                reason={rejectionReason}
                isRejecting={isRejecting}
                onReasonChange={setRejectionReason}
                onClose={closeReject}
                onConfirm={confirmReject}
            />
        </>
    );
}

"use client";

import { Card, CardContent, type LucideIcon } from "@esparex/ui";
import Link from "next/link";

interface DashboardCardProps {
    title: string;
    value: string | number;
    icon: LucideIcon;
    description?: string;
    trend?: {
        value: number;
        isUp: boolean;
    };
    variant?: "default" | "warning" | "danger" | "success" | "info";
    className?: string;
    href?: string;
}

const variantStyles: Record<NonNullable<DashboardCardProps["variant"]>, string> = {
    default: "bg-sky-50 text-sky-700 border border-sky-100",
    info: "bg-sky-50 text-sky-700 border border-sky-100",
    warning: "bg-amber-50 text-amber-800 border border-amber-100",
    danger: "bg-rose-50 text-rose-700 border border-rose-100",
    success: "bg-emerald-50 text-emerald-700 border border-emerald-100",
};

export function DashboardCard({
    title,
    value,
    icon: Icon,
    description,
    trend,
    variant = "default",
    className = "",
    href
}: DashboardCardProps) {
    const iconStyle = variantStyles[variant] || variantStyles.default;
    const content = (
        <Card className={`bg-white px-3 py-2.5 rounded-xl border border-slate-200 shadow-xs hover:shadow-sm transition-all hover:border-slate-300 ${className}`}>
            <CardContent className="p-0 flex items-center justify-between gap-2">
                <div className="min-w-0 flex-1">
                    <p className="text-tiny font-bold text-foreground-tertiary uppercase tracking-wider truncate mb-0.5">{title}</p>
                    <div className="flex items-baseline gap-1.5">
                        <span className="text-base font-bold text-foreground tracking-tight">{value}</span>
                        {description && (
                            <span className="text-tiny text-foreground-subtle font-medium italic truncate">{description}</span>
                        )}
                    </div>
                </div>
                <div className={`p-1.5 rounded-lg shrink-0 ${iconStyle}`}>
                    <Icon size={16} />
                </div>
            </CardContent>
        </Card>
    );

    if (href) {
        return (
            <Link href={href} className="block transition-transform hover:-translate-y-0.5">
                {content}
            </Link>
        );
    }

    return content;
}

