import { useCallback, useEffect, useMemo, useState } from "react";
import {
    createArea,
    createCity,
    createLocation,
    createState,
    getDistinctStates,
    getLocations,
    toggleLocationStatus,
    deleteLocation,
    updateLocation,
} from "@/lib/api/locations";
import { Location, LocationFilters } from "@/types/location";
import { showAdminPopup } from "@/lib/popup/popupEvents";
import { parseAdminResponse } from "@/lib/api/parseAdminResponse";

type UseAdminLocationsOptions = {
    filters: LocationFilters;
    page: number;
    limit?: number;
};

type PaginationState = {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
};

type MutableLocationPayload = Partial<Location> & {
    selectedStateId?: string;
    parentId?: string;
};

const DEFAULT_LIMIT = 20;

function stripLocationFormHelpers(data: MutableLocationPayload): Partial<Location> {
    const { selectedStateId: _s, parentId: _p, ...clean } = data;
    return clean;
}

export function useAdminLocations({
    filters,
    page,
    limit = DEFAULT_LIMIT,
}: UseAdminLocationsOptions) {
    const [locations, setLocations] = useState<Location[]>([]);
    const [states, setStates] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [pagination, setPagination] = useState<PaginationState>({
        page,
        limit,
        total: 0,
        totalPages: 1,
    });

    const requestKey = useMemo(
        () => JSON.stringify({ filters, page, limit }),
        [filters, page, limit]
    );

    const fetchLocations = useCallback(async () => {
        setLoading(true);
        setError(null);

        try {
            const response = await getLocations({
                ...filters,
                page,
                limit,
            });

            if (!response.success) {
                setLocations([]);
                setError(response.message || "Failed to fetch locations");
                return;
            }

            const parsed = parseAdminResponse<Location>(response);
            const nextPagination = parsed.pagination;

            setLocations(parsed.items);
            setPagination({
                page: nextPagination?.page ?? page,
                limit: nextPagination?.limit ?? limit,
                total: nextPagination?.total ?? parsed.items.length,
                totalPages: nextPagination?.totalPages ?? nextPagination?.pages ?? 1,
            });
        } catch (err) {
            setLocations([]);
            setError(err instanceof Error ? err.message : "Failed to fetch locations");
        } finally {
            setLoading(false);
        }
    }, [filters, limit, page]);

    useEffect(() => {
        void (async () => { await fetchLocations(); })();
    }, [fetchLocations, requestKey]);

    useEffect(() => {
        let active = true;

        const loadStates = async () => {
            try {
                const nextStates = await getDistinctStates();
                if (active) {
                    setStates(nextStates);
                }
            } catch {
                if (active) {
                    setStates([]);
                }
            }
        };

        void loadStates();

        return () => {
            active = false;
        };
    }, []);

    const refresh = useCallback(async () => {
        await fetchLocations();
    }, [fetchLocations]);

    const handleToggleStatus = async (id: string) => {
        try {
            const response = await toggleLocationStatus(id);
            if (!response.success) {
                showAdminPopup({ type: "error", title: "Error", message: response.message || "Failed to update location status" });
                return;
            }

            await refresh();
            showAdminPopup({ type: "success", title: "Success", message: "Location status updated" });
        } catch (err) {
            showAdminPopup({ type: "error", title: "Error", message: err instanceof Error ? err.message : "Failed to update location status" });
        }
    };

    const handleCreate = async (data: MutableLocationPayload) => {
        try {
            const payload = stripLocationFormHelpers(data);
            let response;

            if (payload.level === "state") {
                response = await createState({ name: payload.name || "", ...payload });
            } else if (payload.level === "city") {
                if (!payload.parentId) {
                    throw new Error("State is required for city creation");
                }
                response = await createCity({
                    name: payload.name || "",
                    stateId: payload.parentId,
                    ...payload,
                });
            } else if (payload.level === "area") {
                if (!payload.parentId) {
                    throw new Error("City is required for area creation");
                }
                response = await createArea({
                    name: payload.name || "",
                    cityId: payload.parentId,
                    ...payload,
                });
            } else {
                response = await createLocation(payload);
            }

            if (!response.success) {
                showAdminPopup({ type: "error", title: "Error", message: response.message || "Failed to create location" });
                return false;
            }

            await refresh();
            showAdminPopup({ type: "success", title: "Success", message: "Location created successfully" });
            return true;
        } catch (err) {
            showAdminPopup({ type: "error", title: "Error", message: err instanceof Error ? err.message : "Failed to create location" });
            return false;
        }
    };

    const handleUpdate = async (id: string, data: MutableLocationPayload) => {
        try {
            const response = await updateLocation(id, stripLocationFormHelpers(data));
            if (!response.success) {
                showAdminPopup({ type: "error", title: "Error", message: response.message || "Failed to update location" });
                return false;
            }

            await refresh();
            showAdminPopup({ type: "success", title: "Success", message: "Location updated successfully" });
            return true;
        } catch (err) {
            showAdminPopup({ type: "error", title: "Error", message: err instanceof Error ? err.message : "Failed to update location" });
            return false;
        }
    };

    const handleDelete = async (id: string) => {
        try {
            const response = await deleteLocation(id);
            if (!response.success) {
                showAdminPopup({ type: "error", title: "Error", message: response.message || "Failed to delete location" });
                return false;
            }

            await refresh();
            showAdminPopup({ type: "success", title: "Success", message: "Location deleted successfully" });
            return true;
        } catch (err) {
            showAdminPopup({ type: "error", title: "Error", message: err instanceof Error ? err.message : "Failed to delete location" });
            return false;
        }
    };

    return {
        locations,
        states,
        loading,
        error,
        pagination,
        refresh,
        handleToggleStatus,
        handleDelete,
        handleCreate,
        handleUpdate,
    };
}

import { createModel, deleteModel, getModels, updateModel, toggleModelStatus, approveModel, rejectModel } from "@/lib/api/models";
import { useAdminCatalogCollection } from "@/hooks/useAdminCatalogCollection";
import { Model, CreateModelDTO, UpdateModelDTO } from "@esparex/contracts";
import { useCallback } from "react";


import { type AdminListPagination } from "@/hooks/useAdminCrudList";
import { useCatalogMutation } from "./useCatalogMutation";

export function useAdminModels(options?: {
    initialFilters?: Partial<{ search: string; brandId: string; categoryId: string; parentModelId: string; variantModelId: string; status: string }>;
    initialPagination?: Partial<AdminListPagination>;
}) {
    const {
        items: models,
        loading,
        error,
        pagination,
        filters,
        setFilters,
        setPage,
        refresh: fetchModels,
        handleDelete,
        handleCreate,
        handleUpdate,
        runAction,
        setItems
    } = useAdminCatalogCollection<
        Model,
        { search: string; brandId: string; categoryId: string; parentModelId: string; variantModelId: string; status: string },
        CreateModelDTO,
        UpdateModelDTO
    >({
        initialFilters: {
            search: "",
            brandId: "all",
            categoryId: "all",
            parentModelId: "all",
            variantModelId: "all",
            status: "all",
        },
        fetchList: getModels,
        listErrorMessage: "Failed to fetch models",
        createItem: createModel,
        createSuccessMessage: "Model created successfully",
        createErrorMessage: "Failed to create model",
        updateItem: updateModel,
        updateSuccessMessage: "Model updated successfully",
        updateErrorMessage: "Failed to update model",
        deleteItem: deleteModel,
        deleteSuccessMessage: "Model deleted successfully",
        deleteErrorMessage: "Failed to delete model",
    }, options);

    const { handleApprove: handleApproveModel, handleReject: handleRejectModel, handleToggleStatus } = useCatalogMutation({
        approveFn: approveModel,
        rejectFn: rejectModel,
        toggleStatusFn: toggleModelStatus,
        runAction,
        entityName: "Model",
        onApproveSuccess: (id) => {
            setItems((prev) => prev.map((m) => m.id === id ? { ...m, approvalStatus: "approved", isActive: true } : m));
        },
        onRejectSuccess: (id) => {
            setItems((prev) => prev.map((m) => m.id === id ? { ...m, approvalStatus: "rejected", isActive: false } : m));
        },
        onToggleSuccess: (id) => {
            setItems((prev) => prev.map((m) => m.id === id ? { ...m, isActive: !m.isActive } : m));
        }
    });

    return {
        models,
        loading,
        error,
        pagination,
        filters,
        setFilters,
        setPage,
        refresh: fetchModels,
        handleDelete,
        handleCreate,
        handleUpdate,
        handleToggleStatus,
        handleApproveModel,
        handleRejectModel,
    };
}

import { useCallback } from "react";
import { type AdminResponseLike } from "@/hooks/useAdminCatalogCollection";

interface CatalogMutationOptions {
    approveFn?: (id: string) => Promise<AdminResponseLike>;
    rejectFn?: (id: string, reason: string) => Promise<AdminResponseLike>;
    toggleStatusFn?: (id: string) => Promise<AdminResponseLike>;
    onApproveSuccess?: (id: string) => void | Promise<void>;
    onRejectSuccess?: (id: string) => void | Promise<void>;
    onToggleSuccess?: (id: string) => void | Promise<void>;
    fetchItems?: () => Promise<void> | void;
    runAction: (action: () => Promise<AdminResponseLike>, options: { successMessage: string; errorMessage: string; onSuccess?: () => Promise<void> | void }) => Promise<void | boolean>;
    entityName?: string;
}

export function useCatalogMutation({
    approveFn,
    rejectFn,
    toggleStatusFn,
    onApproveSuccess,
    onRejectSuccess,
    onToggleSuccess,
    fetchItems,
    runAction,
    entityName = "Item"
}: CatalogMutationOptions) {
    const handleApprove = useCallback(async (id: string) => {
        if (!approveFn) return;
        await runAction(() => approveFn(id), {
            successMessage: `${entityName} approved`,
            errorMessage: `Failed to approve ${entityName.toLowerCase()}`,
            onSuccess: () => {
                if (onApproveSuccess) onApproveSuccess(id);
                else if (fetchItems) void fetchItems();
            },
        });
    }, [approveFn, runAction, onApproveSuccess, fetchItems, entityName]);

    const handleReject = useCallback(async (id: string, reason: string) => {
        if (!rejectFn) return;
        await runAction(() => rejectFn(id, reason), {
            successMessage: `${entityName} rejected`,
            errorMessage: `Failed to reject ${entityName.toLowerCase()}`,
            onSuccess: () => {
                if (onRejectSuccess) onRejectSuccess(id);
                else if (fetchItems) void fetchItems();
            },
        });
    }, [rejectFn, runAction, onRejectSuccess, fetchItems, entityName]);

    const handleToggleStatus = useCallback(async (id: string) => {
        if (!toggleStatusFn) return;
        await runAction(() => toggleStatusFn(id), {
            successMessage: "Status updated",
            errorMessage: "Failed to toggle status",
            onSuccess: () => {
                if (onToggleSuccess) onToggleSuccess(id);
                else if (fetchItems) void fetchItems();
            },
        });
    }, [toggleStatusFn, runAction, onToggleSuccess, fetchItems, entityName]);

    return {
        handleApprove,
        handleReject,
        handleToggleStatus,
    };
}

import { useState } from "react";
import { useSearchParams } from "next/navigation";
import { useCatalogQueryStateSync } from "@/hooks/useCatalogQueryStateSync";
import { normalizeSearchParamValue, parsePositiveIntParam } from "@/lib/urlSearchParams";

interface UseCatalogTabStateOptions {
    defaultLimit?: number;
    totalPages: number;
    loading: boolean;
    initialSearch?: string;
    initialCategoryId?: string;
    initialBrandId?: string;
    initialStatus?: string;
    initialPage?: number;
}

export function useCatalogTabState<T extends { id: string }>({
    defaultLimit = 50,
    totalPages,
    loading,
    initialSearch = "",
    initialCategoryId = "all",
    initialBrandId = "all",
    initialStatus = "all",
    initialPage = 1,
}: UseCatalogTabStateOptions) {
    const [searchInput, setSearchInput] = useState(initialSearch);

    const [deletingItem, setDeletingItem] = useState<T | null>(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const [rejectingItem, setRejectingItem] = useState<T | null>(null);
    const [rejectionReason, setRejectionReason] = useState("");
    const [isRejecting, setIsRejecting] = useState(false);

    const { replaceQueryState } = useCatalogQueryStateSync({
        searchInput,
        initialSearch,
        loading,
        initialPage,
        totalPages,
    });

    const closeDelete = () => {
        if (!isDeleting) setDeletingItem(null);
    };

    const closeReject = () => {
        if (!isRejecting) setRejectingItem(null);
    };

    return {
        initialSearch,
        initialCategoryId,
        initialBrandId,
        initialStatus,
        initialPage,
        defaultLimit,

        searchInput,
        setSearchInput,

        deletingItem,
        setDeletingItem,
        isDeleting,
        setIsDeleting,
        closeDelete,

        rejectingItem,
        setRejectingItem,
        rejectionReason,
        setRejectionReason,
        isRejecting,
        setIsRejecting,
        closeReject,

        replaceQueryState
    };
}

