import React, { useState } from 'react';
import { View, TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
import { Container, Card, AppText } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import * as ImagePicker from 'expo-image-picker';
import { BusinessFormState } from '../../domain/BusinessFormState';
import { services } from '../../../../bootstrap';

interface StepDocumentsUploadProps {
  formState: BusinessFormState;
  onChange: (updates: Partial<BusinessFormState>) => void;
}

export function StepDocumentsUpload({ formState, onChange }: StepDocumentsUploadProps) {
  const [uploading, setUploading] = useState(false);

  const handlePickDocument = async (docType: 'id_proof' | 'business_proof' | 'certificate') => {
    try {
      const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!permission.granted) {
        Alert.alert('Permission Required', 'Media library access is required to attach verification documents.');
        return;
      }

      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        quality: 0.8,
      });

      if (!result.canceled && result.assets && result.assets[0]) {
        const asset = result.assets[0];
        setUploading(true);
        const fileUrl = await services.businessService.uploadDocument(asset.uri, asset.mimeType || 'image/jpeg');

        const updatedDocs = formState.documents.filter((d) => d.type !== docType);
        updatedDocs.push({
          type: docType,
          url: fileUrl,
          idProofType: docType === 'id_proof' ? 'aadhaar' : undefined,
        });

        onChange({ documents: updatedDocs });
      }
    } catch (err: any) {
      Alert.alert('Upload Failed', err?.message || 'Unable to upload document. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const isUploaded = (type: string) => formState.documents.some((d) => d.type === type);

  return (
    <Container className="p-4">
      <Card className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800">
        <AppText variant="h3" className="font-bold text-slate-900 dark:text-slate-100 mb-1">
          Verification Documents
        </AppText>
        <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-4">
          Upload your ID proof and business verification documents
        </AppText>

        {uploading && (
          <View className="flex-row items-center bg-sky-50 dark:bg-sky-950 p-2.5 rounded-lg mb-3">
            <ActivityIndicator size="small" color={base.brand[500]} />
            <AppText variant="caption" className="ml-2 text-sky-700 dark:text-sky-300">
              Uploading document to secure storage...
            </AppText>
          </View>
        )}

        <View className="flex-row items-center justify-between py-3 border-b border-slate-100 dark:border-slate-800">
          <View className="flex-1 mr-3">
            <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100 text-sm">
              Identity Proof (Aadhaar / PAN) *
            </AppText>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mt-0.5">
              Government issued photo ID proof
            </AppText>
          </View>
          <TouchableOpacity
            className={`px-3.5 py-2 rounded-lg ${
              isUploaded('id_proof')
                ? 'bg-emerald-100 dark:bg-emerald-950'
                : 'bg-brand-600 dark:bg-brand-500'
            }`}
            onPress={() => handlePickDocument('id_proof')}
            disabled={uploading}
          >
            <AppText
              variant="caption"
              className={`font-semibold ${
                isUploaded('id_proof')
                  ? 'text-emerald-700 dark:text-emerald-300'
                  : 'text-white'
              }`}
            >
              {isUploaded('id_proof') ? '✓ Attached' : 'Upload ID'}
            </AppText>
          </TouchableOpacity>
        </View>

        <View className="flex-row items-center justify-between py-3">
          <View className="flex-1 mr-3">
            <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100 text-sm">
              Business Proof (GST / Shop License)
            </AppText>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mt-0.5">
              Shop establishment certificate or GST card
            </AppText>
          </View>
          <TouchableOpacity
            className={`px-3.5 py-2 rounded-lg ${
              isUploaded('business_proof')
                ? 'bg-emerald-100 dark:bg-emerald-950'
                : 'bg-brand-600 dark:bg-brand-500'
            }`}
            onPress={() => handlePickDocument('business_proof')}
            disabled={uploading}
          >
            <AppText
              variant="caption"
              className={`font-semibold ${
                isUploaded('business_proof')
                  ? 'text-emerald-700 dark:text-emerald-300'
                  : 'text-white'
              }`}
            >
              {isUploaded('business_proof') ? '✓ Attached' : 'Upload Proof'}
            </AppText>
          </TouchableOpacity>
        </View>
      </Card>
    </Container>
  );
}

import { IListingRepository } from './IListingRepository';
import { Listing } from '../domain/Listing';
import { CreatedListing } from '../domain/CreatedListing';
import { ListingMapper } from '../infrastructure/mappers/ListingMapper';
import { CreatedListingMapper } from '../infrastructure/mappers/CreatedListingMapper';
import { apiClient } from '../../../infrastructure/api/apiClient';
import type { Ad } from '@esparex/contracts/src/v1/listings/schema/ad.schema';
import { ListingQueryParams, CreateListingRequest, Category } from '@esparex/contracts';
import { API_ROUTES } from '@esparex/shared';

interface PaginatedResponse<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
  };
}

export class ApiListingRepository implements IListingRepository {
  public async getListings(params?: ListingQueryParams): Promise<readonly Listing[]> {
    const queryParams: Record<string, any> = { ...params };
    if (queryParams.search && !queryParams.q) {
      queryParams.q = queryParams.search;
    }
    delete queryParams.search;

    const response = await apiClient.get<PaginatedResponse<Ad> | Ad[]>('/listings', { params: queryParams });
    const resData = response.data as {
      data?: Ad[] | { items?: Ad[]; ads?: Ad[] };
      items?: Ad[];
      ads?: Ad[];
    } | Ad[];

    let items: Ad[] = [];
    if (Array.isArray(resData)) {
      items = resData;
    } else if (resData && typeof resData === 'object') {
      if ('data' in resData && resData.data) {
        if (Array.isArray(resData.data)) {
          items = resData.data;
        } else if ('items' in resData.data && Array.isArray(resData.data.items)) {
          items = resData.data.items;
        } else if ('ads' in resData.data && Array.isArray(resData.data.ads)) {
          items = resData.data.ads;
        }
      } else if ('items' in resData && Array.isArray(resData.items)) {
        items = resData.items;
      } else if ('ads' in resData && Array.isArray(resData.ads)) {
        items = resData.ads;
      }
    }
    return items.map(ListingMapper.mapAdToListing);
  }

  public async getListingById(id: string): Promise<Listing> {
    const response = await apiClient.get<{ data: Ad }>(`/listings/${id}`);
    const ad = response.data?.data || response.data;
    return ListingMapper.mapAdToListing(ad);
  }

  public async getMyListings(params?: ListingQueryParams): Promise<readonly Listing[]> {
    const response = await apiClient.get<any>('/listings/mine', { params });
    const resData = response.data;
    const items = Array.isArray(resData?.data?.items)
      ? resData.data.items
      : Array.isArray(resData?.data)
      ? resData.data
      : Array.isArray(resData?.items)
      ? resData.items
      : Array.isArray(resData)
      ? resData
      : [];
    return items.map(ListingMapper.mapAdToListing);
  }

  public async getSavedListings(): Promise<readonly Listing[]> {
    const response = await apiClient.get<{ data: Ad[] }>('/users/saved-ads');
    const resData = response.data;
    const items = Array.isArray(resData?.data)
      ? resData.data
      : Array.isArray(resData)
      ? resData
      : [];
    return items.map(ListingMapper.mapAdToListing);
  }

  public async toggleSaveListing(adId: string, isSaved: boolean): Promise<void> {
    if (isSaved) {
      await apiClient.delete(`/users/saved-ads/${adId}`);
    } else {
      await apiClient.post('/users/saved-ads', { adId });
    }
  }

  public async create(request: CreateListingRequest): Promise<CreatedListing> {
    const response = await apiClient.post<{ data: Ad }>('/listings', request);
    const ad = response.data?.data || response.data;
    return CreatedListingMapper.fromDto(ad);
  }

  public async update(id: string, request: Partial<CreateListingRequest>): Promise<Listing> {
    const response = await apiClient.patch<{ data: Ad }>(`/listings/${id}/edit`, request);
    const ad = response.data?.data || response.data;
    return ListingMapper.mapAdToListing(ad);
  }

  public async getCategories(): Promise<readonly Category[]> {
    const response = await apiClient.get<Category[] | { data: Category[] }>(API_ROUTES.USER.CATEGORIES);
    const data = response.data;
    if (data && 'data' in data && Array.isArray(data.data)) {
      return data.data;
    }
    return Array.isArray(data) ? data : [];
  }

  public async reportListing(adId: string, reason: string, description?: string): Promise<void> {
    await apiClient.post('/reports', {
      targetType: 'ad',
      targetId: adId,
      reason,
      description,
    });
  }
}

