import React, { useState, useEffect, useCallback } from 'react';
import { Modal, View, TouchableOpacity, ScrollView, ActivityIndicator } from 'react-native';
import { AppText, AppInput, AppIcon } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import { LocationMeta } from '@esparex/contracts';
import { services } from '../../../../bootstrap';

interface LocationSelectorModalProps {
  visible: boolean;
  onClose: () => void;
  onSelectLocation: (location: LocationMeta | null) => void;
  selectedLocationId?: string;
}

export const LocationSelectorModal: React.FC<LocationSelectorModalProps> = ({
  visible,
  onClose,
  onSelectLocation,
  selectedLocationId,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<LocationMeta[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isDetecting, setIsDetecting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Debounced location search querying locationService
  useEffect(() => {
    const trimmed = searchQuery.trim();
    if (trimmed.length < 2) {
      setSearchResults([]);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    setErrorMessage(null);

    const handler = setTimeout(async () => {
      try {
        const results = await services.locationService.searchLocations(trimmed);
        setSearchResults(results);
      } catch {
        setErrorMessage('Failed to search locations. Please try again.');
        setSearchResults([]);
      } finally {
        setIsSearching(false);
      }
    }, 350);

    return () => clearTimeout(handler);
  }, [searchQuery]);

  // IP-based network location detection
  const handleDetectLocation = useCallback(async () => {
    setIsDetecting(true);
    setErrorMessage(null);
    try {
      const location = await services.locationService.detectLocation();
      if (location) {
        onSelectLocation(location);
        onClose();
      } else {
        setErrorMessage('Could not detect location. Please search manually.');
      }
    } catch {
      setErrorMessage('Location detection unavailable. Please search manually.');
    } finally {
      setIsDetecting(false);
    }
  }, [onSelectLocation, onClose]);

  const handleSelectAllIndia = useCallback(() => {
    onSelectLocation(null);
    onClose();
  }, [onSelectLocation, onClose]);

  const handleSelectResult = useCallback(
    (item: LocationMeta) => {
      onSelectLocation(item);
      onClose();
    },
    [onSelectLocation, onClose]
  );

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent
      onRequestClose={onClose}
      accessibilityViewIsModal={true}
    >
      <View className="flex-1 justify-end bg-black/50">
        <View className="bg-white dark:bg-slate-900 rounded-t-3xl p-6 max-h-[85%] border-t border-slate-200 dark:border-slate-800">
          {/* Header */}
          <View className="flex-row items-center justify-between pb-4 border-b border-slate-200 dark:border-slate-800">
            <AppText variant="h3" className="font-bold text-slate-900 dark:text-white">
              Select Location
            </AppText>
            <TouchableOpacity
              onPress={onClose}
              accessibilityLabel="Close location selector"
              accessibilityRole="button"
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <AppIcon name="X" size={20} color={base.slate[400]} />
            </TouchableOpacity>
          </View>

          {/* Search Input */}
          <View className="my-4">
            <AppInput
              placeholder="Search city, area or state…"
              value={searchQuery}
              onChangeText={setSearchQuery}
              autoCapitalize="none"
              autoCorrect={false}
              accessibilityLabel="Location search input"
            />
          </View>

          {errorMessage && (
            <View className="mb-3 px-3 py-2 bg-red-50 dark:bg-red-950/40 rounded-xl border border-red-200 dark:border-red-800">
              <AppText variant="caption" className="text-red-600 dark:text-red-400 font-medium">
                {errorMessage}
              </AppText>
            </View>
          )}

          <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
            {/* Action 1: All India (Default) */}
            <TouchableOpacity
              onPress={handleSelectAllIndia}
              className={`flex-row items-center p-3.5 rounded-xl mb-2 border ${
                !selectedLocationId
                  ? 'bg-brand-50 dark:bg-brand-950/40 border-brand-300 dark:border-brand-700'
                  : 'bg-slate-50 dark:bg-slate-800/60 border-slate-200 dark:border-slate-700'
              }`}
              accessibilityRole="button"
              accessibilityLabel="Select All India"
            >
              <View className="w-9 h-9 rounded-full bg-brand-100 dark:bg-brand-900/50 items-center justify-center mr-3">
                <AppIcon name="MapPin" size={18} color={base.brand[600]} />
              </View>
              <View className="flex-1">
                <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100">
                  All India
                </AppText>
                <AppText variant="caption" className="text-slate-500 dark:text-slate-400">
                  Show listings from everywhere across India
                </AppText>
              </View>
              {!selectedLocationId && (
                <AppIcon name="CheckCircle2" size={18} color={base.brand[600]} />
              )}
            </TouchableOpacity>

            {/* Action 2: Detect My Location (Network/IP) */}
            <TouchableOpacity
              onPress={handleDetectLocation}
              disabled={isDetecting}
              className="flex-row items-center p-3.5 rounded-xl mb-4 bg-slate-50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700"
              accessibilityRole="button"
              accessibilityLabel="Detect my location via network"
            >
              <View className="w-9 h-9 rounded-full bg-brand-50 dark:bg-brand-900/50 items-center justify-center mr-3">
                {isDetecting ? (
                  <ActivityIndicator size="small" color={base.brand[600]} />
                ) : (
                  <AppIcon name="Globe" size={18} color={base.brand[600]} />
                )}
              </View>
              <View className="flex-1">
                <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100">
                  Detect my location
                </AppText>
                <AppText variant="caption" className="text-slate-500 dark:text-slate-400">
                  Detects your approximate city via network IP
                </AppText>
              </View>
            </TouchableOpacity>

            {/* Search Results List */}
            {isSearching && (
              <View className="py-6 items-center justify-center">
                <ActivityIndicator size="small" color={base.brand[500]} />
                <AppText variant="caption" className="text-slate-400 mt-2">
                  Searching locations…
                </AppText>
              </View>
            )}

            {!isSearching && searchResults.length > 0 && (
              <View className="mb-4">
                <AppText
                  variant="caption"
                  className="text-slate-400 uppercase font-semibold tracking-wider mb-2 px-1"
                >
                  Search Results
                </AppText>
                {searchResults.map((item) => {
                  const itemId = item.locationId || (item as { _id?: string })._id || item.name;
                  const isSelected = selectedLocationId === itemId;
                  const label = item.display || [item.city || item.name, item.state].filter(Boolean).join(', ');

                  return (
                    <TouchableOpacity
                      key={itemId}
                      onPress={() => handleSelectResult(item)}
                      className={`flex-row items-center p-3 rounded-xl mb-1.5 border ${
                        isSelected
                          ? 'bg-brand-50 dark:bg-brand-950/40 border-brand-300 dark:border-brand-700'
                          : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'
                      }`}
                      accessibilityRole="button"
                      accessibilityLabel={`Select ${label}`}
                    >
                      <AppIcon name="MapPin" size={16} color={base.slate[400]} />
                      <AppText
                        variant="body"
                        className="font-medium text-slate-800 dark:text-slate-200 ml-2.5 flex-1"
                      >
                        {label}
                      </AppText>
                      {isSelected && (
                        <AppIcon name="CheckCircle2" size={16} color={base.brand[600]} />
                      )}
                    </TouchableOpacity>
                  );
                })}
              </View>
            )}

            {!isSearching && searchQuery.trim().length >= 2 && searchResults.length === 0 && (
              <View className="py-6 items-center">
                <AppText variant="body" className="text-slate-500 text-center">
                  No matching locations found for "{searchQuery}".
                </AppText>
              </View>
            )}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
};

import React, { useState } from 'react';
import { View, Modal, TouchableOpacity, ScrollView, TextInput, Alert } from 'react-native';
import { AppText, AppIcon, AppButton } from '@esparex/mobile-ui';
import { REPORT_REASON, ReportReasonValue } from '@esparex/contracts';
import { services } from '../../../../../bootstrap';

interface ReportAdModalProps {
  visible: boolean;
  adId: string;
  adTitle: string;
  onClose: () => void;
}

const REPORT_REASONS: Array<{ label: string; value: ReportReasonValue }> = [
  { label: 'Fraudulent or Scam', value: REPORT_REASON.SCAM },
  { label: 'Inappropriate Content', value: REPORT_REASON.OFFENSIVE_CONTENT },
  { label: 'Spam', value: REPORT_REASON.SPAM },
  { label: 'Prohibited Item', value: REPORT_REASON.PROHIBITED_ITEM },
  { label: 'Misleading Information', value: REPORT_REASON.MISLEADING_INFO },
  { label: 'Sold Item Still Listed', value: REPORT_REASON.SOLD_ELSEWHERE },
  { label: 'Other', value: REPORT_REASON.OTHER },
];

export const ReportAdModal = ({ visible, adId, adTitle, onClose }: ReportAdModalProps) => {
  const [selectedReason, setSelectedReason] = useState<ReportReasonValue | null>(null);
  const [description, setDescription] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!selectedReason) {
      Alert.alert('Required', 'Please select a reason for reporting this listing.');
      return;
    }

    setIsSubmitting(true);
    try {
      await services.listingService.reportListing(adId, selectedReason, description.trim() || undefined);
      Alert.alert('Report Submitted', 'Thank you. Our moderation team will review this listing.', [
        {
          text: 'OK',
          onPress: () => {
            setSelectedReason(null);
            setDescription('');
            onClose();
          },
        },
      ]);
    } catch (error) {
      Alert.alert('Error', 'Unable to submit report at this time. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent
      onRequestClose={onClose}
    >
      <View className="flex-1 bg-black/60 justify-end">
        <View className="bg-white dark:bg-slate-900 rounded-t-3xl p-5 max-h-[85%]">
          {/* Header */}
          <View className="flex-row items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800 mb-4">
            <View className="flex-row items-center flex-1 mr-2">
              <View className="mr-2">
                <AppIcon name="AlertTriangle" size={20} color="#ef4444" />
              </View>
              <AppText variant="h3" className="text-slate-900 dark:text-white font-bold" numberOfLines={1}>
                Report Listing
              </AppText>
            </View>
            <TouchableOpacity
              onPress={onClose}
              disabled={isSubmitting}
              className="p-1 rounded-full bg-slate-100 dark:bg-slate-800"
              accessibilityRole="button"
              accessibilityLabel="Close report dialog"
            >
              <AppIcon name="X" size={18} color="#64748b" />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-3">
              Why are you reporting &quot;{adTitle}&quot;?
            </AppText>

            {/* Reasons list */}
            <View className="gap-2 mb-4">
              {REPORT_REASONS.map((item) => {
                const isSelected = selectedReason === item.value;
                return (
                  <TouchableOpacity
                    key={item.value}
                    onPress={() => setSelectedReason(item.value)}
                    activeOpacity={0.7}
                    className={`p-3 rounded-xl border flex-row items-center justify-between mb-1.5 ${
                      isSelected
                        ? 'border-sky-600 bg-sky-50 dark:bg-sky-950/40'
                        : 'border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/60'
                    }`}
                  >
                    <AppText
                      variant="body"
                      className={`text-sm font-medium ${
                        isSelected
                          ? 'text-sky-700 dark:text-sky-300 font-semibold'
                          : 'text-slate-700 dark:text-slate-300'
                      }`}
                    >
                      {item.label}
                    </AppText>
                    <View
                      className={`w-4 h-4 rounded-full border items-center justify-center ${
                        isSelected ? 'border-sky-600 bg-sky-600' : 'border-slate-400'
                      }`}
                    >
                      {isSelected && <View className="w-1.5 h-1.5 rounded-full bg-white" />}
                    </View>
                  </TouchableOpacity>
                );
              })}
            </View>

            {/* Additional details */}
            <AppText variant="caption" className="text-slate-600 dark:text-slate-300 font-semibold mb-1.5">
              Additional Details (Optional)
            </AppText>
            <TextInput
              value={description}
              onChangeText={setDescription}
              placeholder="Provide details to help us investigate..."
              placeholderTextColor="#94a3b8"
              multiline
              numberOfLines={3}
              className="p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm min-h-[72px] text-top mb-5"
            />

            {/* Action buttons */}
            <View className="flex-row gap-3 pb-4">
              <View className="flex-1">
                <AppButton
                  variant="outline"
                  label="Cancel"
                  onPress={onClose}
                  disabled={isSubmitting}
                />
              </View>
              <View className="flex-1">
                <AppButton
                  variant="primary"
                  label={isSubmitting ? 'Submitting...' : 'Submit Report'}
                  onPress={handleSubmit}
                  disabled={isSubmitting || !selectedReason}
                />
              </View>
            </View>
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
};

import React, { useState, useCallback } from 'react';
import { View, ScrollView, ActivityIndicator, Alert, Linking, Share } from 'react-native';
import { useRoute, RouteProp } from '@react-navigation/native';
import { AppText, Center, Screen } from '@esparex/mobile-ui';
import { MainStackParamList, ROUTES } from '../../../../navigation/routes';
import { navigate } from '../../../../navigation/navigationRef';
import { useAuth, AuthStatus } from '../../../../providers/AuthProvider';
import { useListingDetails } from '../hooks/useListingDetails';
import { useToggleSaveListing } from '../hooks/useToggleSaveListing';
import { useSavedListings } from '../hooks/useSavedListings';
import { useProfile } from '../../../user/presentation/hooks/useProfile';
import { ImageCarousel } from '../components/details/ImageCarousel';
import { PriceSection } from '../components/details/PriceSection';
import { SellerSection } from '../components/details/SellerSection';
import { AvailableSparePartsSection } from '../components/details/AvailableSparePartsSection';
import { DescriptionSection } from '../components/details/DescriptionSection';
import { SafetyTipsSection } from '../components/details/SafetyTipsSection';
import { NearbyRepairServicesSection } from '../components/details/NearbyRepairServicesSection';
