import { PostAdDraft } from '../domain/PostAdDraft';
import { WizardStep } from '../domain/WizardStep';
import {
  MIN_AD_TITLE_CHARS,
  MAX_AD_TITLE_CHARS,
  MIN_AD_DESCRIPTION_CHARS,
  MAX_AD_DESCRIPTION_CHARS,
  MIN_AD_IMAGES,
  MAX_AD_IMAGES,
} from '@esparex/contracts';

export interface ValidationError {
  field: keyof PostAdDraft;
  message: string;
}

export type ValidationResult =
  | { valid: true }
  | { valid: false; errors: readonly ValidationError[] };

export class PostAdValidator {
  static validate(step: WizardStep, draft: PostAdDraft): ValidationResult {
    const errors: ValidationError[] = [];

    switch (step) {
      case WizardStep.CATEGORY:
        if (typeof draft.categoryId !== 'string' || draft.categoryId.trim().length === 0) {
          errors.push({ field: 'categoryId', message: 'Please select a category.' });
        }
        break;

      case WizardStep.DETAILS:
        if (typeof draft.title !== 'string' || draft.title.trim().length < MIN_AD_TITLE_CHARS) {
          errors.push({
            field: 'title',
            message: `Title must be at least ${MIN_AD_TITLE_CHARS} characters.`,
          });
        } else if (draft.title.trim().length > MAX_AD_TITLE_CHARS) {
          errors.push({
            field: 'title',
            message: `Title cannot exceed ${MAX_AD_TITLE_CHARS} characters.`,
          });
        }

        if (
          typeof draft.description !== 'string' ||
          draft.description.trim().length < MIN_AD_DESCRIPTION_CHARS
        ) {
          errors.push({
            field: 'description',
            message: `Description must be at least ${MIN_AD_DESCRIPTION_CHARS} characters.`,
          });
        } else if (draft.description.trim().length > MAX_AD_DESCRIPTION_CHARS) {
          errors.push({
            field: 'description',
            message: `Description cannot exceed ${MAX_AD_DESCRIPTION_CHARS} characters.`,
          });
        }

        if (!draft.isFree) {
          if (typeof draft.price !== 'number' || draft.price < 1) {
            errors.push({ field: 'price', message: 'Enter a price greater than zero or mark as Free.' });
          }
        }

        if (!draft.location?.locationId && !draft.locationId && !draft.locationDisplay) {
          errors.push({ field: 'location', message: 'Please select or auto-detect a location.' });
        }
        break;

      case WizardStep.PHOTOS:
        const imgCount = (draft.localImages || draft.pickedImages || []).length;
        if (imgCount < MIN_AD_IMAGES) {
          errors.push({ field: 'localImages', message: 'Add at least one photo.' });
        } else if (imgCount > MAX_AD_IMAGES) {
          errors.push({
            field: 'localImages',
            message: `Maximum ${MAX_AD_IMAGES} photos allowed.`,
          });
        }
        break;

      default:
        break;
    }

    return errors.length === 0 ? { valid: true } : { valid: false, errors };
  }

  static canAdvanceFrom(step: WizardStep, draft: PostAdDraft): boolean {
    return PostAdValidator.validate(step, draft).valid;
  }

  static isReadyToSubmit(draft: PostAdDraft): boolean {
    return (
      PostAdValidator.canAdvanceFrom(WizardStep.CATEGORY, draft) &&
      PostAdValidator.canAdvanceFrom(WizardStep.DETAILS, draft) &&
      PostAdValidator.canAdvanceFrom(WizardStep.PHOTOS, draft)
    );
  }
}

import { LocationMeta } from '@esparex/contracts';
import { PostAdDraft } from './PostAdDraft';
import { PickedImage } from './PickedImage';
import { PostAdState, INITIAL_POST_AD_STATE } from './PostAdState';
import { WizardStep, TOTAL_WIZARD_STEPS } from './WizardStep';

/**
 * PostAdAction — discriminated union of all state transitions.
 */
export type PostAdAction =
  | { type: 'SET_CATEGORY'; payload: { categoryId: string; categoryName: string } }
  | { type: 'SET_BRAND'; payload: { brandId?: string; brandName?: string; customBrandName?: string } }
  | { type: 'SET_MODEL'; payload: { modelId?: string; modelName?: string; customModelName?: string } }
  | { type: 'SET_DEVICE_CONDITION'; payload: 'power_on' | 'power_off' }
  | { type: 'SET_SPARE_PARTS'; payload: string[] }
  | { type: 'SET_TITLE'; payload: string }
  | { type: 'SET_DESCRIPTION'; payload: string }
  | { type: 'SET_PRICE'; payload: number }
  | { type: 'SET_IS_FREE'; payload: boolean }
  | { type: 'SET_LOCATION'; payload: LocationMeta | null }
  | { type: 'SET_PICKED_IMAGES'; payload: readonly PickedImage[] }
  | { type: 'SET_IMAGES'; payload: string[] }
  | { type: 'SET_STEP'; payload: WizardStep }
  | { type: 'NEXT_STEP' }
  | { type: 'PREVIOUS_STEP' }
  | { type: 'RESET' };

export function postAdReducer(state: PostAdState, action: PostAdAction): PostAdState {
  switch (action.type) {
    case 'SET_CATEGORY':
      return {
        ...state,
        draft: {
          ...state.draft,
          categoryId: action.payload.categoryId,
          categoryName: action.payload.categoryName,
          // Reset dependent brand/model/parts when category changes
          brandId: undefined,
          brandName: undefined,
          modelId: undefined,
          modelName: undefined,
          customBrandName: undefined,
          customModelName: undefined,
          spareParts: [],
        },
      };

    case 'SET_BRAND':
      return {
        ...state,
        draft: {
          ...state.draft,
          brandId: action.payload.brandId,
          brandName: action.payload.brandName,
          customBrandName: action.payload.customBrandName,
          modelId: undefined,
          modelName: undefined,
          customModelName: undefined,
        },
      };

    case 'SET_MODEL':
      return {
        ...state,
        draft: {
          ...state.draft,
          modelId: action.payload.modelId,
          modelName: action.payload.modelName,
          customModelName: action.payload.customModelName,
        },
      };

    case 'SET_DEVICE_CONDITION':
      return {
        ...state,
        draft: { ...state.draft, deviceCondition: action.payload },
      };

    case 'SET_SPARE_PARTS':
      return {
        ...state,
        draft: { ...state.draft, spareParts: action.payload },
      };

    case 'SET_TITLE':
      return { ...state, draft: { ...state.draft, title: action.payload } };

    case 'SET_DESCRIPTION':
      return { ...state, draft: { ...state.draft, description: action.payload } };

    case 'SET_PRICE':
      return { ...state, draft: { ...state.draft, price: action.payload, isFree: false } };

    case 'SET_IS_FREE':
      return {
        ...state,
        draft: {
          ...state.draft,
          isFree: action.payload,
          price: action.payload ? 0 : state.draft.price || 0,
        },
      };

    case 'SET_LOCATION':
      return {
        ...state,
        draft: {
          ...state.draft,
          location: action.payload,
          locationId: action.payload?.locationId,
          locationDisplay: action.payload?.display,
        },
      };

    case 'SET_PICKED_IMAGES':
      return {
        ...state,
        draft: {
          ...state.draft,
          pickedImages: action.payload,
          localImages: action.payload.map((img) => img.uri),
        },
      };

    case 'SET_IMAGES':
      return { ...state, draft: { ...state.draft, localImages: action.payload } };

    case 'SET_STEP':
      return { ...state, currentStep: action.payload };

    case 'NEXT_STEP': {
      const next = state.currentStep + 1;
      const clamped = Math.min(next, TOTAL_WIZARD_STEPS - 1) as WizardStep;
      return { ...state, currentStep: clamped };
    }

    case 'PREVIOUS_STEP': {
      const prev = state.currentStep - 1;
      const clamped = Math.max(prev, 0) as WizardStep;
      return { ...state, currentStep: clamped };
    }

    case 'RESET':
      return INITIAL_POST_AD_STATE;

    default:
      return state;
  }
}

import React, { useCallback, useEffect } from 'react';
import { View, ScrollView, Alert, KeyboardAvoidingView, Platform } from 'react-native';
import { Screen, Container, AppText, AppButton, AppIcon } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import { useAuth } from '../../../providers/AuthProvider';
import { usePostAdDraft } from '../usePostAdDraft';
import { PostAdValidator } from '../application/PostAdValidator';
import { WizardStep } from '../domain/WizardStep';
import { WizardProgress } from './components/WizardProgress';
import { WizardNavBar } from './components/WizardNavBar';
import { StepCategory } from './steps/StepCategory';
import { StepDetails } from './steps/StepDetails';
import { StepImages } from './steps/StepImages';
import { useSubmitAd } from './hooks/useSubmitAd';
import { navigationRef, navigate } from '../../../navigation/navigationRef';
import { ROUTES } from '../../../navigation/routes';

// ---------------------------------------------------------------------------
// Step router — maps WizardStep enum to the correct step component (3 Steps)
// ---------------------------------------------------------------------------

const STEP_COMPONENTS: Record<WizardStep, React.ComponentType> = {
  [WizardStep.CATEGORY]: StepCategory,
  [WizardStep.DETAILS]: StepDetails,
  [WizardStep.PHOTOS]: StepImages,
};

// ---------------------------------------------------------------------------
// Status-to-label mapping for WizardNavBar
// ---------------------------------------------------------------------------

const SUBMIT_LABELS: Record<string, string> = {
  uploading: 'Uploading photos\u2026',
  creating: 'Publishing listing\u2026',
};

// ---------------------------------------------------------------------------
// PostAdScreen — wizard orchestrator
// ---------------------------------------------------------------------------

export const PostAdScreen = () => {
  let authStatus: string = 'authenticated';
  try {
    const auth = useAuth();
    authStatus = auth.status;
  } catch {
    authStatus = 'authenticated';
  }
  const { state, nextStep, previousStep, reset } = usePostAdDraft();
  const { currentStep, draft } = state;
  const { submit, status, submitError, resetError } = useSubmitAd();

  const isLastStep = currentStep === WizardStep.PHOTOS;
  const isSubmitting = status === 'uploading' || status === 'creating';
  const canGoNext = PostAdValidator.canAdvanceFrom(currentStep, draft);
  const StepComponent = STEP_COMPONENTS[currentStep];

  // Derive a status-aware label; undefined falls back to WizardNavBar's default.
  const nextLabel: string | undefined = SUBMIT_LABELS[status];

  // On the last step, onNext triggers submission instead of step advancement.
  // PostAdScreen owns the navigate-on-success decision; useSubmitAd owns the
  // mutation state and returns a typed SubmitResult.
  const handleNext = useCallback(() => {
    if (isLastStep) {
      void submit().then((result) => {
        if (result.success) {
          navigationRef.current?.reset({
            index: 0,
            routes: [
              {
                name: ROUTES.MAIN_STACK,
                state: {
                  routes: [
                    {
                      name: ROUTES.MAIN_TABS,
                      state: { routes: [{ name: ROUTES.HOME_TAB }] },
                    },
                  ],
                },
              },
            ],
          });
        }
        // Failure is surfaced via submitError effect below
      });
    } else {
      nextStep();
    }
  }, [isLastStep, submit, nextStep]);

  // Surface submission errors as a dismissable Alert.
  // The user presses "Try again" → resetError() resets status to idle.
  useEffect(() => {
    if (submitError) {
      Alert.alert(
        'Submission failed',
        submitError.message,
        [{ text: 'Try again', onPress: resetError }],
      );
    }
  }, [submitError, resetError]);

  if (authStatus === 'anonymous') {
    return (
      <Screen edges={['top', 'left', 'right']} backgroundColor="bg-slate-50 dark:bg-slate-950">
        <Container className="flex-1 justify-center items-center px-6">
          <View className="w-16 h-16 rounded-full bg-slate-100 dark:bg-slate-800 items-center justify-center mb-4">
            <AppIcon name="PlusCircle" size={32} color={base.brand[500]} />
          </View>
          <AppText variant="h2" className="font-bold text-slate-900 dark:text-white text-center mb-2">
            Post an Ad on Esparex
          </AppText>
          <AppText variant="body" className="text-slate-600 dark:text-slate-400 text-center mb-6">
            Sign in to create your listing, upload photos, and connect with verified buyers across India.
          </AppText>
          <AppButton
            label="Sign In / Register"
            onPress={() => navigate(ROUTES.AUTH_STACK)}
            className="w-full"
            accessibilityLabel="Sign in to post an ad"
          />
        </Container>
      </Screen>
    );
  }

  return (
    <Screen edges={['top', 'left', 'right']} backgroundColor="bg-slate-50 dark:bg-slate-950">
      <KeyboardAvoidingView
        className="flex-1"
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        {/* Progress indicator */}
        <WizardProgress currentStep={currentStep} />

        {/* Active step content */}
        <ScrollView className="flex-1" keyboardShouldPersistTaps="handled">
          <View className="flex-1 min-h-80">
            <StepComponent />
          </View>
        </ScrollView>

        {/* Navigation controls */}
        <WizardNavBar
          currentStep={currentStep}
          canGoNext={canGoNext}
          isLastStep={isLastStep}
          isLoading={isSubmitting}
          nextLabel={nextLabel}
          onBack={previousStep}
          onNext={handleNext}
        />
      </KeyboardAvoidingView>
    </Screen>
  );
};

