import { useState, useEffect, useCallback } from 'react';
import { apiClient } from '../../../../infrastructure/api/apiClient';

export interface CatalogBrand {
  id: string;
  name: string;
}

export interface CatalogModel {
  id: string;
  name: string;
}

export interface CatalogSparePart {
  id: string;
  name: string;
  brand?: string;
}

export const useCategoryDependents = (categoryId?: string, brandId?: string) => {
  const [brands, setBrands] = useState<CatalogBrand[]>([]);
  const [models, setModels] = useState<CatalogModel[]>([]);
  const [spareParts, setSpareParts] = useState<CatalogSparePart[]>([]);
  const [isLoadingBrands, setIsLoadingBrands] = useState(false);
  const [isLoadingModels, setIsLoadingModels] = useState(false);
  const [isLoadingSpareParts, setIsLoadingSpareParts] = useState(false);

  // Load brands and spare parts when categoryId changes
  useEffect(() => {
    if (!categoryId) {
      setBrands([]);
      setModels([]);
      setSpareParts([]);
      return;
    }

    let isMounted = true;

    const loadCategoryData = async () => {
      setIsLoadingBrands(true);
      setIsLoadingSpareParts(true);
      try {
        const [brandsRes, partsRes] = await Promise.all([
          apiClient.get<{ data?: any[] }>(`/brands?categoryId=${categoryId}`).catch(() => ({ data: [] })),
          apiClient.get<{ data?: any[] }>(`/spare-parts?categoryId=${categoryId}`).catch(() => ({ data: [] })),
        ]);

        if (isMounted) {
          const rawBrands = Array.isArray(brandsRes.data) ? brandsRes.data : Array.isArray(brandsRes) ? brandsRes : [];
          setBrands(rawBrands.map((b: any) => ({ id: b._id || b.id || b.name, name: b.name })));

          const rawParts = Array.isArray(partsRes.data) ? partsRes.data : Array.isArray(partsRes) ? partsRes : [];
          setSpareParts(rawParts.map((p: any) => ({ id: p._id || p.id || p.name, name: p.name, brand: p.brand })));
        }
      } catch {
        if (isMounted) {
          setBrands([]);
          setSpareParts([]);
        }
      } finally {
        if (isMounted) {
          setIsLoadingBrands(false);
          setIsLoadingSpareParts(false);
        }
      }
    };

    void loadCategoryData();

    return () => {
      isMounted = false;
    };
  }, [categoryId]);

  // Load models when brandId changes
  useEffect(() => {
    if (!brandId) {
      setModels([]);
      return;
    }

    let isMounted = true;

    const loadModels = async () => {
      setIsLoadingModels(true);
      try {
        const modelsRes = await apiClient.get<{ data?: any[] }>(`/models?brandId=${brandId}`).catch(() => ({ data: [] }));
        if (isMounted) {
          const rawModels = Array.isArray(modelsRes.data) ? modelsRes.data : Array.isArray(modelsRes) ? modelsRes : [];
          setModels(rawModels.map((m: any) => ({ id: m._id || m.id || m.name, name: m.name })));
        }
      } catch {
        if (isMounted) {
          setModels([]);
        }
      } finally {
        if (isMounted) {
          setIsLoadingModels(false);
        }
      }
    };

    void loadModels();

    return () => {
      isMounted = false;
    };
  }, [brandId]);

  return {
    brands,
    models,
    spareParts,
    isLoadingBrands,
    isLoadingModels,
    isLoadingSpareParts,
  };
};

import React, { useCallback } from 'react';
import { View, ScrollView, Alert, StyleSheet } from 'react-native';
import { AppText, Center, AppIcon } from '@esparex/mobile-ui';
import { MAX_AD_IMAGES } from '@esparex/contracts';
import { usePostAdDraft } from '../../usePostAdDraft';
import { ImageGrid, AddPhotoButton } from '../components/ImagePickerComponents';
import { services } from '../../../../bootstrap';

/**
 * StepImages — Step 3 of the Post Ad wizard (Photos & Final Step).
 *
 * Responsibilities:
 * - Read current localImages/pickedImages from draft
 * - Pick photos up to MAX_AD_IMAGES (5 photos)
 * - Show Cover badge on the primary photo
 * - Remove individual images
 */
export const StepImages = () => {
  const { state, setPickedImages, setImages } = usePostAdDraft();
  const images = state.draft.localImages ?? [];
  const pickedImages = state.draft.pickedImages ?? [];
  const canAddMore = images.length < MAX_AD_IMAGES;

  const handleAdd = useCallback(async () => {
    if (!canAddMore) return;
    const result = await services.imagePicker.pick();
    if (result.success) {
      const available = MAX_AD_IMAGES - images.length;
      const newPicked = result.images.slice(0, available);
      const combinedPicked = [...pickedImages, ...newPicked];
      setPickedImages(combinedPicked);
      setImages(combinedPicked.map((img) => img.uri));
    } else if (result.reason === 'permission-denied') {
      Alert.alert(
        'Permission Required',
        'Photo gallery access is required to add photos to your listing.'
      );
    } else if (result.reason === 'error') {
      Alert.alert('Image Selection Failed', result.message || 'Could not select photo.');
    }
  }, [images.length, pickedImages, canAddMore, setPickedImages, setImages]);

  const handleRemove = useCallback(
    (index: number) => {
      Alert.alert('Remove photo', 'Remove this photo from your listing?', [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Remove',
          style: 'destructive',
          onPress: () => {
            const updatedPicked = pickedImages.filter((_, i) => i !== index);
            setPickedImages(updatedPicked);
            setImages(updatedPicked.map((img) => img.uri));
          },
        },
      ]);
    },
    [pickedImages, setPickedImages, setImages]
  );

  return (
    <ScrollView
      className="flex-1"
      contentContainerStyle={styles.scrollContent}
      showsVerticalScrollIndicator={false}
    >
      <AppText variant="h3" className="text-slate-900 dark:text-white font-bold mb-1">
        Add Photos
      </AppText>
      <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-5">
        Listings with clear photos get up to 5x more responses. Add up to {MAX_AD_IMAGES} photos.
      </AppText>

      {/* Thumbnail grid + add button */}
      <View className="flex-row flex-wrap gap-2 mb-4">
        <ImageGrid images={[...images]} onRemove={handleRemove} />
        {canAddMore && <AddPhotoButton onPress={handleAdd} />}
      </View>

      {/* Guidance when no images added yet */}
      {images.length === 0 && (
        <Center className="py-8 bg-slate-50 dark:bg-slate-900/60 rounded-2xl border border-dashed border-slate-300 dark:border-slate-700 my-4">
          <AppIcon name="ImagePlus" size={40} color="#64748b" />
          <AppText variant="body" className="text-slate-600 dark:text-slate-300 font-semibold mt-3 text-center">
            Upload at least 1 photo
          </AppText>
          <AppText variant="caption" className="text-slate-400 text-center mt-1 px-6">
            The first photo will be shown as the primary cover photo for your ad.
          </AppText>
        </Center>
      )}

      {/* Count indicator */}
      {images.length > 0 && (
        <AppText variant="caption" className="text-slate-400 dark:text-slate-500 text-center font-medium mt-2">
          {images.length} of {MAX_AD_IMAGES} photos added (First image is Cover)
        </AppText>
      )}
    </ScrollView>
  );
};

