import { Request, Response, NextFunction } from 'express';
import mongoose from 'mongoose';
import logger from '@esparex/core/utils/logger';
import { env } from '@esparex/core/config/env';
import { emitReliabilityAlert } from '@esparex/core/utils/reliabilityAlerts';
import { recordApiRequestSample } from '@esparex/core/utils/sloMonitor';
import {
    recordApiUsageSignal,
    recordRepeatedFailureSignal
} from '@esparex/core/utils/securityMonitoring';

import {
    dbQueryDuration,
    httpErrorRate,
    httpErrorsTotal,
    httpRequestDuration,
    reliabilityAlertsTotal
} from '@esparex/core/utils/metrics';

const ERROR_RATE_WINDOW_MS = 60_000;
const ERROR_RATE_THRESHOLD = env.RELIABILITY_HIGH_ERROR_RATE_THRESHOLD ?? 0.15;
const ERROR_RATE_MIN_REQUESTS = env.RELIABILITY_ERROR_RATE_MIN_REQUESTS ?? 100;

let errorWindowStartedAt = Date.now();
let errorWindowTotalRequests = 0;
let errorWindowErrorRequests = 0;
let lastErrorRateSnapshot = {
    windowStartAt: new Date().toISOString(),
    windowEndAt: new Date().toISOString(),
    totalRequests: 0,
    errorRequests: 0,
    errorRate: 0,
};

const resolveUserId = (req: any): string | undefined => {
    const raw = req.user?._id;
    if (typeof raw === 'string') return raw;
    if (raw && typeof raw.toString === 'function') return raw.toString();
    return undefined;
};

const normalizeMetricRoute = (requestUrl: string): string => {
    return requestUrl
        .split('?')[0]
        .replace(/[0-9a-f]{24}/gi, ':id')
        .replace(/[0-9a-f]{8}-[0-9a-f-]{27}/gi, ':uuid')
        .replace(/\/\d+/g, '/:num');
};

const evaluateErrorRateWindow = () => {
    const now = Date.now();
    if (now - errorWindowStartedAt < ERROR_RATE_WINDOW_MS) return;

    const total = errorWindowTotalRequests;
    const errors = errorWindowErrorRequests;
    const ratio = total > 0 ? errors / total : 0;
    lastErrorRateSnapshot = {
        windowStartAt: new Date(errorWindowStartedAt).toISOString(),
        windowEndAt: new Date(now).toISOString(),
        totalRequests: total,
        errorRequests: errors,
        errorRate: ratio,
    };

    httpErrorRate.set(ratio);

    if (total >= ERROR_RATE_MIN_REQUESTS && ratio >= ERROR_RATE_THRESHOLD) {
        reliabilityAlertsTotal.labels('HIGH_ERROR_RATE', 'critical').inc();
        void emitReliabilityAlert({
            type: 'HIGH_ERROR_RATE',
            title: 'High API error rate detected',
            severity: 'critical',
            summary: 'HTTP error ratio exceeded threshold',
            dedupeKey: 'high_error_rate',
            metadata: {
                windowMs: ERROR_RATE_WINDOW_MS,
                threshold: ERROR_RATE_THRESHOLD,
                minRequests: ERROR_RATE_MIN_REQUESTS,
                totalRequests: total,
                errorRequests: errors,
                errorRate: ratio,
            },
        });
    }

    errorWindowStartedAt = now;
    errorWindowTotalRequests = 0;
    errorWindowErrorRequests = 0;
};

export const apiLatencyMiddleware = (req: any, res: Response, next: NextFunction) => {
    const start = Date.now();

    res.on('finish', () => {
        const durationMs = Date.now() - start;
        const durationSec = durationMs / 1000;
        const requestUrl = req.originalUrl || req.url;
        const route = req.route?.path || normalizeMetricRoute(requestUrl);
        const userId = resolveUserId(req);
        const ip = req.ip || req.socket?.remoteAddress || 'unknown';

        // 1. Record Prometheus Metric
        httpRequestDuration.labels(
            req.method,
            route || 'unknown',
            res.statusCode.toString()
        ).observe(durationSec);

        errorWindowTotalRequests += 1;
        if (res.statusCode >= 500) {
            errorWindowErrorRequests += 1;
        }
        if (res.statusCode >= 400) {
            httpErrorsTotal.labels(req.method, route || 'unknown', res.statusCode.toString()).inc();
        }
        evaluateErrorRateWindow();
        recordApiRequestSample(durationMs, res.statusCode);
        recordApiUsageSignal({
            method: req.method,
            route: route || 'unknown',
            ip,
            userId,
        });
        recordRepeatedFailureSignal({
            path: requestUrl,
            ip,
            statusCode: res.statusCode,
            userId,
        });

        // 2. Existing Structured Logging
        const msg = `${req.method} ${requestUrl} ${res.statusCode} - ${durationMs}ms`;
        const isAdminLocationRoute = requestUrl.startsWith('/api/v1/admin/locations');
        const warnThresholdMs = isAdminLocationRoute ? 800 : 500;
        const errorThresholdMs = isAdminLocationRoute ? 2500 : 2000;

        if (durationMs > errorThresholdMs) {
            logger.error(`[SLOW_API] ${msg}`, { duration: durationMs, method: req.method, url: requestUrl, status: res.statusCode });
        } else if (durationMs > warnThresholdMs) {
            logger.warn(`[SLOW_API] ${msg}`, { duration: durationMs, method: req.method, url: requestUrl, status: res.statusCode });
        }
    });

    next();
};

export const getApiReliabilitySummary = (): {
    thresholds: {
        errorRateThreshold: number;
        minRequests: number;
        evaluationWindowMs: number;
    };
    lastWindow: {
        windowStartAt: string;
        windowEndAt: string;
        totalRequests: number;
        errorRequests: number;
        errorRate: number;
    };
} => ({
    thresholds: {
        errorRateThreshold: ERROR_RATE_THRESHOLD,
        minRequests: ERROR_RATE_MIN_REQUESTS,
        evaluationWindowMs: ERROR_RATE_WINDOW_MS,
    },
    lastWindow: { ...lastErrorRateSnapshot },
});

export const memoryUsageMiddleware = (req: Request, res: Response, next: NextFunction) => {
    // Note: Logging memory on every request is noisy. 
    // Usually handled by a setInterval, but middleware was requested.
    // We log periodically (e.g., 1 in 100 requests) or if memory is very high.
    const memoryUsage = process.memoryUsage();
    const heapUsedMB = Math.round(memoryUsage.heapUsed / 1024 / 1024);

    if (heapUsedMB > 1500) { // 1.5 GB threshold
        logger.error(`[HIGH_MEMORY] Heap used: ${heapUsedMB} MB`);
    }

    next();
};

export const initializeDatabaseMonitoring = () => {
    const slowQueryThresholdMs = 200; // 200ms
    type QueryContext = { _startTime?: number; mongooseCollection?: { name?: string }; op?: string; _conditions?: unknown };
    type AggregateContext = { _startTime?: number; _model?: { collection?: { name?: string } }; pipeline?: () => unknown[] };
    type MonitoringSchema = mongoose.Schema & {
        pre: (method: string, fn: (this: MongoosePreHookContext, next: () => void) => void) => void;
        post: (method: string, fn: (this: MongoosePreHookContext, docs: unknown, next: () => void) => void) => void;
    };

    type MongoosePreHookContext = { _startTime?: number };
    function markStartTime(this: MongoosePreHookContext, next?: () => void) {
        this._startTime = Date.now();

        if (typeof next === "function") {
            next();
        }
    }

    const logSlowOperation = function (this: unknown, _docs: unknown, next: () => void) {
        const ctx = this as QueryContext & AggregateContext;
        if (ctx._startTime) {
            const durationMs = Date.now() - ctx._startTime;
            const durationSec = durationMs / 1000;
            const collectionName = ctx.mongooseCollection?.name ?? ctx._model?.collection?.name ?? 'unknown_collection';
            const operation = ctx.op || 'aggregate';

            // 1. Record Prometheus Metric (Always record, not just slow ones)
            dbQueryDuration.labels(collectionName, operation).observe(durationSec);

            // 2. Existing Slow Query Logging
            if (durationMs > slowQueryThresholdMs) {
                logger.warn(`[SLOW_DB_QUERY] ${collectionName}.${operation} took ${durationMs}ms`, {
                    collection: collectionName,
                    operation,
                    duration: durationMs,
                    query: typeof ctx.pipeline === 'function' ? ctx.pipeline() : ctx._conditions || 'unknown_conditions'
                });
            }
        }
        if (typeof next === 'function') next();
    };

    mongoose.plugin((schema) => {
        const monitoringSchema = schema as MonitoringSchema;

        (['find', 'findOne', 'findOneAndUpdate'] as const).forEach((operation) => {
            monitoringSchema.pre(operation, markStartTime);
            monitoringSchema.post(operation, logSlowOperation);
        });

        monitoringSchema.pre('aggregate', markStartTime);
        monitoringSchema.post('aggregate', logSlowOperation);
    });
};

import rateLimit, { type Store } from 'express-rate-limit';
import RedisStore, { type RedisReply } from 'rate-limit-redis';
import redisClient from '@esparex/core/config/redis';
import { Request, Response } from 'express';
import logger from '@esparex/core/utils/logger';
import { env } from '@esparex/core/config/env';
import { recordOtpAbuseSignal, recordRateLimitSignal } from '@esparex/core/utils/securityMonitoring';
import { sendErrorResponse } from '../../utils/errorResponse';

const isJestRuntime = typeof process.env.JEST_WORKER_ID !== 'undefined';
const shouldDisableRedisStore = (env.NODE_ENV === 'test' || isJestRuntime || !env.ALLOW_REDIS);

type RedisCallable = { call: (...args: string[]) => Promise<RedisReply> };
type RedisStoreWithPendingScripts = RedisStore & { incrementScriptSha?: Promise<string>; getScriptSha?: Promise<string> };
type RateLimitRequest = Request & { rateLimit?: { resetTime?: Date } };

const MAX_SPIKE_CACHE_SIZE = 2000;
const spikeCache = new Map<string, { count: number; resetAt: number }>();
const REDIS_READY_WAIT_MS = env.RELIABILITY_STARTUP_READINESS_TIMEOUT_MS ?? 12_000;
let redisReadyWaitInFlight: Promise<boolean> | null = null;

export const resolveRequestIp = (req: Request): string => req.ip || req.socket?.remoteAddress || 'unknown';

export const resolveUserOrMobile = (req: any): string | undefined => {
    const userId = req.user?._id ? String(req.user._id) : undefined;
    if (userId) return userId;
    const body = req.body as { mobile?: unknown; email?: unknown } | undefined;
    if (body && typeof body.mobile === 'string') { const m = body.mobile.trim().replace(/\D/g, '').slice(-10); if (m) return m; }
    if (body && typeof body.email === 'string') { const e = body.email.trim().toLowerCase(); if (e) return e; }
    return undefined;
};

export const buildHybridRateLimitKey = (req: any, actor?: string): string => {
    const ip = resolveRequestIp(req);
    return `${actor || resolveUserOrMobile(req) || 'anonymous'}:${ip}`;
};

export const resolveRetryAfterSeconds = (req: Request, fallbackSeconds: number): number => {
    const resetTime = (req as RateLimitRequest).rateLimit?.resetTime;
    if (resetTime instanceof Date) { const r = Math.ceil((resetTime.getTime() - Date.now()) / 1000); if (Number.isFinite(r) && r > 0) return r; }
    return fallbackSeconds;
};

const isRedisNotReadyError = (error: unknown): boolean => {
    if (!(error instanceof Error)) return false;
    const n = error.message.toLowerCase();
    return n.includes("stream isn't writeable") || n.includes('enableofflinequeue');
};

const waitForRedisReady = async (timeoutMs: number): Promise<boolean> => {
    const status = (redisClient as { status?: string }).status;
    if (status === 'ready') return true;
    if (redisReadyWaitInFlight) return redisReadyWaitInFlight;
    redisReadyWaitInFlight = new Promise<boolean>((resolve) => {
        const timer = setTimeout(() => { cleanup(false); }, timeoutMs);
        timer.unref?.();
        let settled = false;
        const cleanup = (result: boolean) => { if (settled) return; settled = true; clearTimeout(timer); redisClient.off('ready', onReady); redisClient.off('error', onError); redisClient.off('end', onEnd); redisReadyWaitInFlight = null; resolve(result); };
        const onReady = () => cleanup(true);
        const onError = () => undefined;
        const onEnd = () => cleanup(false);
        redisClient.on('ready', onReady); redisClient.on('error', onError); redisClient.on('end', onEnd);
        if ((redisClient as { status?: string }).status === 'ready') cleanup(true);
    });
    return redisReadyWaitInFlight;
};

const sendRedisCommandWithReadyRetry = async (...args: string[]): Promise<RedisReply> => {
    try { return await (redisClient as RedisCallable).call(...args); }
    catch (error) { if (!isRedisNotReadyError(error)) throw error; const r = await waitForRedisReady(REDIS_READY_WAIT_MS); if (!r) throw error; return (redisClient as RedisCallable).call(...args); }
};

const formatCountdown = (seconds: number): string => {
    const mins = Math.floor(seconds / 60); const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
};

export const respondRateLimited = (req: any, res: Response, error: string, bucket: string, options: { code?: string; retryAfterSeconds?: number } = {}) => {
    const key = `spike:${req.ip}:${req.originalUrl}`; const now = Date.now();
    let record = spikeCache.get(key);
    if (!record || now > record.resetAt) {
        if (!record && spikeCache.size >= MAX_SPIKE_CACHE_SIZE) { const oldestKey = spikeCache.keys().next().value; if (oldestKey !== undefined) spikeCache.delete(oldestKey); }
        record = { count: 0, resetAt: now + 60000 };
    }
    record.count += 1; spikeCache.set(key, record);
    const userIdRaw = req.user?._id;
    const userId = typeof userIdRaw === 'string' ? userIdRaw : userIdRaw && typeof userIdRaw.toString === 'function' ? userIdRaw.toString() : undefined;
    recordRateLimitSignal({ path: req.originalUrl || req.url, ip: req.ip || req.socket?.remoteAddress || 'unknown', bucket, code: options.code, userId });
    if (bucket.startsWith('otp')) { const actor = resolveUserOrMobile(req) || 'unknown'; recordOtpAbuseSignal({ mobileSuffix: actor.slice(-4).padStart(4, '*'), reason: 'rate_limited', userId }); }
    if (record.count >= 50 && Math.random() < 0.1) logger.warn(`UI RUNAWAY LOOP DETECTED: 429 spike on ${req.originalUrl} from ${req.ip}`, { ip: req.ip, url: req.originalUrl, error, count: record.count });
    if (typeof options.retryAfterSeconds === 'number') res.set('Retry-After', String(options.retryAfterSeconds));
    let errorMessage = error;
    if (typeof options.retryAfterSeconds === 'number') errorMessage = `Too many requests. Please try again in ${formatCountdown(options.retryAfterSeconds)}.`;
    return sendErrorResponse(req, res, 429, errorMessage, {
        code: options.code || 'RATE_LIMITED',
        bucket,
        path: req.originalUrl || req.path || 'unknown',
        ...(options.retryAfterSeconds !== undefined ? { retryAfterSeconds: options.retryAfterSeconds, retryAfter: options.retryAfterSeconds } : {})
    });
};

const createEphemeralTestStore = (prefix: string, windowMs: number): Store => {
    const hits = new Map<string, { totalHits: number; resetTime: Date }>();
    return {
        localKeys: true, prefix: `test:${prefix}`,
        increment: (key: string) => { const now = Date.now(); const c = hits.get(key); if (!c || c.resetTime.getTime() <= now) { const n = { totalHits: 1, resetTime: new Date(now + windowMs) }; hits.set(key, n); return n; } const n = { totalHits: c.totalHits + 1, resetTime: c.resetTime }; hits.set(key, n); return n; },
        decrement: (key: string) => { const c = hits.get(key); if (!c) return; if (c.totalHits <= 1) { hits.delete(key); return; } hits.set(key, { totalHits: c.totalHits - 1, resetTime: c.resetTime }); },
        resetKey: (key: string) => { hits.delete(key); },
        resetAll: () => { hits.clear(); },
        shutdown: () => { hits.clear(); },
    };
};

export function createRedisStore(prefix: string, windowMs: number) {
    if (env.NODE_ENV === 'production' && shouldDisableRedisStore) throw new Error('FATAL: Redis store is required in production.');
    if (shouldDisableRedisStore) return createEphemeralTestStore(prefix, windowMs);
    const rs = new RedisStore({ sendCommand: (...args: string[]) => sendRedisCommandWithReadyRetry(...args), prefix: `rl:${prefix}` }) as RedisStoreWithPendingScripts;
    void rs.incrementScriptSha?.catch((error: unknown) => { logger.warn('[RATE_LIMITER] Redis increment script load deferred', { error: error instanceof Error ? error.message : String(error), prefix: `rl:${prefix}` }); });
    void rs.getScriptSha?.catch((error: unknown) => { logger.warn('[RATE_LIMITER] Redis get script load deferred', { error: error instanceof Error ? error.message : String(error), prefix: `rl:${prefix}` }); });
    return rs;
}

export function createLimiter({ windowMs, max, keyPrefix, keyGenerator, errorCode }: {
    windowMs: number; max: number; keyPrefix: string; keyGenerator?: (req: Request, res: Response) => string | Promise<string>; errorCode?: string;
}) {
    const code = errorCode ?? 'RATE_LIMITED';
    return rateLimit({
        windowMs, max, standardHeaders: true, legacyHeaders: false,
        store: createRedisStore(keyPrefix, windowMs),
        ...(keyGenerator ? { keyGenerator } : {}),
        validate: keyGenerator ? false : { ip: false },
        handler: (req: Request, res: Response) => {
            const retryAfterSeconds = resolveRetryAfterSeconds(req, Math.ceil(windowMs / 1000));
            respondRateLimited(req, res, 'Too many requests. Please try again later.', keyPrefix.replace(':', ''), { retryAfterSeconds, code });
        }
    });
}

import { Request, Response, NextFunction } from 'express';
import mongoose from 'mongoose';
import { sendErrorResponse } from "../utils/errorResponse";
import { isValidGeoPoint, DANGEROUS_HTML_PATTERNS, SQL_INJECTION_PATTERNS } from "@esparex/shared";
import { stripMongoOperators } from '@esparex/core/utils/mongoQueryValidator';
import { z } from 'zod';

/**
 * CONTACT US FORM VALIDATOR
 * 
 * Validates all fields for the contact submission endpoint.
 * Prevents spam, injection attacks, and invalid data.
 */
export const validateContactSubmission = (req: Request, res: Response, next: NextFunction) => {
    const { name, email, mobile, phone, subject, category, message } = req.body as {
        name?: string; email?: string; mobile?: string; phone?: string;
        subject?: string; category?: string; message?: string;
    };

    // Name validation
    if (!name || typeof name !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Name is required',
            status: 400
        });
        return;
    }

    const trimmedName = name.trim();
    if (trimmedName.length < 2 || trimmedName.length > 100) {
        res.status(400).json({
            success: false,
            error: 'Name must be between 2 and 100 characters',
            status: 400
        });
        return;
    }

    // Email validation — uses z.string().email() to align with commonSchemas.email behavior
    if (!email || typeof email !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Email is required',
            status: 400
        });
        return;
    }

    const emailParseResult = z.string().email('Invalid email format').safeParse(email.trim());
    if (!emailParseResult.success) {
        res.status(400).json({
            success: false,
            error: 'Invalid email format',
            status: 400
        });
        return;
    }

    if (phone !== undefined) {
        res.status(400).json({
            success: false,
            error: '`phone` is no longer accepted in contact submissions. Use `mobile` instead.',
            status: 400
        });
        return;
    }

    // Mobile validation (optional, but must be valid if provided)
    if (mobile) {
        if (typeof mobile !== 'string') {
            res.status(400).json({
                success: false,
                error: 'Mobile must be a string',
                status: 400
            });
            return;
        }

        const mobileDigits = mobile.replace(/\D/g, '');
        if (mobileDigits.length !== 10) {
            res.status(400).json({
                success: false,
                error: 'Mobile must be exactly 10 digits',
                status: 400
            });
            return;
        }
    }

    // Subject validation (optional)
    if (subject) {
        if (typeof subject !== 'string') {
            res.status(400).json({
                success: false,
                error: 'Subject must be a string',
                status: 400
            });
            return;
        }

        if (subject.trim().length > 200) {
            res.status(400).json({
                success: false,
                error: 'Subject must not exceed 200 characters',
                status: 400
            });
            return;
        }
    }

    // Category validation (optional, but must be valid enum if provided)
    const validCategories = ['general', 'support', 'business', 'technical', 'billing', 'report', 'feedback', 'other'];
    if (category) {
        if (typeof category !== 'string' || !validCategories.includes(category.toLowerCase())) {
            res.status(400).json({
                success: false,
                error: `Category must be one of: ${validCategories.join(', ')}`,
                status: 400
            });
            return;
        }
    }

    // Message validation
    if (!message || typeof message !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Message is required',
            status: 400
        });
        return;
    }

    const trimmedMessage = message.trim();
    if (trimmedMessage.length < 20 || trimmedMessage.length > 1000) {
        res.status(400).json({
            success: false,
            error: 'Message must be between 20 and 1000 characters',
            status: 400
        });
        return;
    }

    const fieldsToCheck = [trimmedName, email, subject || '', trimmedMessage];

    for (const field of fieldsToCheck) {
        if (DANGEROUS_HTML_PATTERNS.test(field)) {
            res.status(400).json({
                success: false,
                error: 'Invalid characters detected. HTML and scripts are not allowed.',
                status: 400
            });
            return;
        }
    }

    // Security: Check for SQL injection patterns
    for (const field of fieldsToCheck) {
        if (SQL_INJECTION_PATTERNS.test(field)) {
            res.status(400).json({
                success: false,
                error: 'Invalid content detected',
                status: 400
            });
            return;
        }
    }

    // Sanitize and trim all fields
    const sanitized = req.body as Record<string, unknown>;
    sanitized.name = trimmedName;
    sanitized.email = email.trim().toLowerCase();
    sanitized.mobile = mobile ? mobile.replace(/\D/g, '') : undefined;
    delete sanitized.phone;
    sanitized.subject = subject ? subject.trim() : undefined;
    sanitized.category = category ? category.toLowerCase() : undefined;
    sanitized.message = trimmedMessage;

    next();
};

/**
 * SMART ALERT VALIDATOR
 * 
 * Validates smart alert creation fields.
 * Enforces data types, ranges, and business rules.
 */
export const validateSmartAlert = (req: Request, res: Response, next: NextFunction) => {
    const { alertName, name, criteria, frequency } = req.body as {
        alertName?: string; name?: string;
        criteria?: Record<string, unknown>; frequency?: unknown;
    };

    const incomingName = typeof name === 'string'
        ? name
        : (typeof alertName === 'string' ? alertName : undefined);

    // Alert name validation
    if (!incomingName) {
        res.status(400).json({
            success: false,
            error: 'Alert name is required',
            status: 400
        });
        return;
    }

    const trimmedName = incomingName.trim();
    if (trimmedName.length < 3 || trimmedName.length > 50) {
        res.status(400).json({
            success: false,
            error: 'Alert name must be between 3 and 50 characters',
            status: 400
        });
        return;
    }

    // Criteria validation
    if (!criteria || typeof criteria !== 'object') {
        res.status(400).json({
            success: false,
            error: 'Alert criteria is required',
            status: 400
        });
        return;
    }

    // Category validation (optional)
    if (criteria.categoryId && !mongoose.Types.ObjectId.isValid(criteria.categoryId as string)) {
        res.status(400).json({
            success: false,
            error: 'Invalid category ID',
            status: 400
        });
        return;
    }

    if (criteria.category && typeof criteria.category !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Category must be a string',
            status: 400
        });
        return;
    }

    // Brand validation (optional)
    if (criteria.brandId && !mongoose.Types.ObjectId.isValid(criteria.brandId as string)) {
        res.status(400).json({
            success: false,
            error: 'Invalid brand ID',
            status: 400
        });
        return;
    }

    if (criteria.brand && typeof criteria.brand !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Brand must be a string',
            status: 400
        });
        return;
    }

    // Model validation (optional)
    if (criteria.modelId && !mongoose.Types.ObjectId.isValid(criteria.modelId as string)) {
        res.status(400).json({
            success: false,
            error: 'Invalid model ID',
            status: 400
        });
        return;
    }

    if (criteria.model && typeof criteria.model !== 'string') {
        res.status(400).json({
            success: false,
            error: 'Model must be a string',
            status: 400
        });
        return;
    }

    // Price validation
    if (criteria.minPrice !== undefined) {
        const minPrice = Number(criteria.minPrice);
        if (isNaN(minPrice) || minPrice < 0) {
            res.status(400).json({
                success: false,
                error: 'Minimum price must be a non-negative number',
                status: 400
            });
            return;
        }
        criteria.minPrice = minPrice;
    }

    if (criteria.maxPrice !== undefined) {
        const maxPrice = Number(criteria.maxPrice);
        if (isNaN(maxPrice) || maxPrice < 0) {
            res.status(400).json({
                success: false,
                error: 'Maximum price must be a non-negative number',
                status: 400
            });
            return;
        }

        if (criteria.minPrice !== undefined && maxPrice < (criteria.minPrice as number)) {
            res.status(400).json({
                success: false,
                error: 'Maximum price must be greater than minimum price',
                status: 400
            });
            return;
        }
        criteria.maxPrice = maxPrice;
    }

    if (frequency !== undefined) {
        const normalized = String(frequency).toLowerCase();
        if (!['daily', 'instant'].includes(normalized)) {
            res.status(400).json({
                success: false,
                error: 'Frequency must be daily or instant',
                status: 400
            });
            return;
        }
        (req.body as Record<string, unknown>).frequency = normalized;
    }

    // Radius validation (Max 500km to match geoNear index bounds)
    const reqBody = req.body as Record<string, unknown>;
    const { radiusKm } = reqBody;
    if (radiusKm !== undefined) {
        const r = Number(radiusKm);
        if (isNaN(r) || r < 1 || r > 500) {
            res.status(400).json({
                success: false,
                error: 'Radius must be between 1 and 500 kilometers',
                status: 400
            });
            return;
        }
        reqBody.radiusKm = r;
    }

    // Coordinates strict bounds validation — uses isValidGeoPoint() from shared/utils/geoUtils
    // Checks: GeoJSON Point structure, lng[-180..180], lat[-90..90], null-island [0,0] rejection
    const { coordinates } = reqBody;
    if (coordinates !== undefined) {
        if (!isValidGeoPoint(coordinates)) {
            res.status(400).json({
                success: false,
                error: 'Coordinates must be a valid GeoJSON Point with longitude [-180, 180] and latitude [-90, 90]. Coordinates [0,0] are not allowed.',
                status: 400
            });
            return;
        }
    }

    // Normalize name field for controller
    (req.body as Record<string, unknown>).name = trimmedName;
    (req.body as Record<string, unknown>).alertName = trimmedName;

    next();
};

/**
 * SEARCH PARAMS VALIDATOR
 * 
 * Validates and sanitizes search/filter parameters.
 * Prevents invalid queries from reaching the database.
 */
export const validateSearchParams = (req: Request, res: Response, next: NextFunction) => {
    req.query = stripMongoOperators(req.query) as Record<string, any>;
    const { q, search, category, categoryId, minPrice, maxPrice, sort, location, locationId, level } = req.query;
    const reject = (message: string) => sendErrorResponse(req, res, 400, message);

    if (search !== undefined) {
        return reject('`search` is no longer accepted. Use `q` instead.');
    }

    if (category !== undefined) {
        return reject('`category` is no longer accepted. Use `categoryId` instead.');
    }

    if (location !== undefined) {
        return reject('`location` is no longer accepted. Use `locationId` or lat/lng/radiusKm instead.');
    }

    // Search query validation
    if (q) {
        if (typeof q !== 'string') {
            return reject('Search query must be a string');
        }

        if (q.length > 100) {
            return reject('Search query must not exceed 100 characters');
        }

        // Sanitize search query
        req.query.q = q.trim();
    }

    if (categoryId !== undefined) {
        if (typeof categoryId !== 'string') {
            return reject('categoryId must be a string');
        }
        const normalizedCategoryId = categoryId.trim();
        if (!mongoose.Types.ObjectId.isValid(normalizedCategoryId)) {
            return reject('categoryId must be a valid ObjectId');
        }
        req.query.categoryId = normalizedCategoryId;
    }

    if (locationId !== undefined) {
        if (typeof locationId !== 'string') {
            return reject('locationId must be a string');
        }
        const normalizedLocationId = locationId.trim();
        if (!mongoose.Types.ObjectId.isValid(normalizedLocationId)) {
            return reject('locationId must be a valid ObjectId');
        }
        req.query.locationId = normalizedLocationId;
    }

    // Price range validation
    if (minPrice) {
        const min = Number(minPrice);
        if (isNaN(min) || min < 0) {
            return reject('Minimum price must be a non-negative number');
        }
    }

    if (maxPrice) {
        const max = Number(maxPrice);
        if (isNaN(max) || max < 0) {
            return reject('Maximum price must be a non-negative number');
        }

        if (minPrice && max < Number(minPrice)) {
            return reject('Maximum price must be greater than minimum price');
        }
    }

    // Sort validation
    if (sort) {
        const validSorts = ['newest', 'oldest', 'price-low', 'price-high', 'relevance'];
        if (!validSorts.includes(sort as string)) {
            return reject(`Sort must be one of: ${validSorts.join(', ')}`);
        }
    }

    if (level !== undefined) {
        if (typeof level !== 'string') {
            return reject('Level must be a string');
        }
        const normalizedLevel = level.trim().toLowerCase();
        const validLevels = ['country', 'state', 'district', 'city', 'area', 'village'];
        if (!validLevels.includes(normalizedLevel)) {
            return reject(`Level must be one of: ${validLevels.join(', ')}`);
        }
        req.query.level = normalizedLevel;
    }

    // Geo validation
    const { lat, lng, radiusKm } = req.query;
    if (lat) {
        const latitude = Number(lat);
        if (isNaN(latitude) || latitude < -90 || latitude > 90) {
            return reject('Invalid latitude. Must be between -90 and 90.');
        }
    }

    if (lng) {
        const longitude = Number(lng);
        if (isNaN(longitude) || longitude < -180 || longitude > 180) {
            return reject('Invalid longitude. Must be between -180 and 180.');
        }
    }

    if (radiusKm) {
        const radius = Number(radiusKm);
        if (isNaN(radius) || radius < 0 || radius > 500) {
            return reject('Invalid radius. Must be between 0 and 500 kilometers.');
        }
    }

    next();
};

