 * Ensures the admin user has the required scope for the action.
 * Supports wildcard (*) for full access.
 */
export const getActorId = (req: any): string =>
    (req.user as AuthUser)?._id?.toString() ?? (req.user as AuthUser)?.id ?? '';

export const getActorRole = (req: any): string =>
    ((req.user as AuthUser)?.role) ?? '';

export const getIp = (req: any): string =>
    (((req.headers['x-forwarded-for'] as string) || req.socket?.remoteAddress || '').split(',')[0] ?? '').trim();

export const getUserAgent = (req: any): string =>
    (req.headers['user-agent'] as string) || '';

export const buildLogFn = (req: any): AdminLogFn =>
    (action, targetType, targetId, metadata) =>
        logAdminActionDirect(
            getActorId(req),
            action,
            targetType,
            targetId,
            metadata,
            getIp(req),
            getUserAgent(req)
        );
import { Role } from '@esparex/contracts';
import { normalizeRole } from '@esparex/core/utils/roleNormalization';

export const checkPermission = (user: AuthUser | undefined, module: string, action: string): boolean => {
    if (!user) return false;
    const role = normalizeRole(user.role);
    if (role === Role.SUPER_ADMIN) return true;
    if (user.permissions?.includes('*') || user.permissions?.includes('all')) return true;

    // Check specific permission
    // Format expected: "module:action" or just "module"
    // But previously it expected nested map. 
    // The middleware uses: permissions.includes(permission)
    // So we should expect 'module:action' string to be passed.

    // If exact match
    if (user.permissions?.includes(action)) return true; // Assuming action is full permission string like 'users:write'

    // If module wildcard
    if (user.permissions?.includes(`${module}:*`)) return true;

    return false;
};

export const getPaginationParams = (req: any) => {
    const rawPage = Array.isArray(req.query.page) ? req.query.page[0] : req.query.page;
    const rawLimit = Array.isArray(req.query.limit) ? req.query.limit[0] : req.query.limit;

    let page = parseInt(String(rawPage)) || 1;
    let limit = parseInt(String(rawLimit)) || 10;

    if (page < 1) page = 1;
    if (limit > 100) limit = 100;

    const skip = (page - 1) * limit;
    return { page, limit, skip };
};

