            Report.countDocuments({ status: { $in: [REPORT_STATUS.OPEN, REPORT_STATUS.PENDING] }, isDeleted: { $ne: true } }),
            Business.countDocuments({ isDeleted: { $ne: true } }),
            RevenueAnalytics.aggregate<RevenueTotalAggItem>([{ $group: { _id: null, total: { $sum: '$totalRevenue' } } }]),
            this.getCatalogHealthMetrics()
        ]);
        return { totalUsers, adStats: adStats as [DashboardCardAdStatsFacet], totalReports, totalBusinesses, totalRevenueAgg, catalogHealth };
    }

    public async getRecentAdminLogs(limit: number): Promise<AdminLogSummary[]> {
        return (await AdminLog.find().sort({ createdAt: -1 }).limit(limit).populate('adminId', 'firstName lastName email').lean<AdminLogSummary[]>()) || [];
    }

    public async getContactSubmissionsPaginated(query: Record<string, unknown>, skip: number, limit: number): Promise<[ContactSubmissionDocument[], number]> {
        return Promise.all([
            ContactSubmission.find(query).skip(skip).limit(limit).sort({ createdAt: -1 }).lean<ContactSubmissionDocument[]>(),
            ContactSubmission.countDocuments(query),
        ]);
    }

    public async updateContactSubmissionById(id: string, status: string): Promise<ContactSubmissionDocument | null> {
        const safeId = typeof id === 'string' ? id : String(id);
        // eslint-disable-next-line esparex/no-status-mutation-outside-status-mutation-service
        return await ContactSubmission.findByIdAndUpdate(safeId, { $set: { status: typeof status === 'string' ? status : String(status) } }, { new: true }).lean<ContactSubmissionDocument | null>();
    }

    public async getLocationAnalyticsRawData(params: LocationAnalyticsParams): Promise<LocationAnalyticsRawData> {
        const { sixMonthsAgo, buildScopedLocationQuery, buildScopedAdQuery, buildScopedUserQuery, hotZoneQuery } = params;
        const [totalLocations, totalAds, totalUsers, adsByLocationAgg, monthlyAds, monthlyUsers, monthlyLocs, topHotZonesRaw] = await Promise.all([
            Location.countDocuments(buildScopedLocationQuery()),
            Ad.countDocuments(buildScopedAdQuery({ status: LISTING_STATUS.LIVE })),
            User.countDocuments(buildScopedUserQuery({ status: USER_STATUS.LIVE })),
            Ad.aggregate<{ _id: unknown; adsCount: number }>([
                { $match: { ...buildScopedAdQuery({ status: LISTING_STATUS.LIVE }), 'location.locationId': { $exists: true, $ne: null } } },
                { $group: { _id: '$location.locationId', adsCount: { $sum: 1 } } },
                { $sort: { adsCount: -1 } },
                { $limit: 250 }
            ]),
            Ad.aggregate<{ _id: { month: number; year: number }; count: number }>([
                { $match: buildScopedAdQuery({ createdAt: { $gte: sixMonthsAgo } }) },
                { $group: { _id: { month: { $month: '$createdAt' }, year: { $year: '$createdAt' } }, count: { $sum: 1 } } }
            ]),
            User.aggregate<{ _id: { month: number; year: number }; count: number }>([
                { $match: buildScopedUserQuery({ createdAt: { $gte: sixMonthsAgo } }) },
                { $group: { _id: { month: { $month: '$createdAt' }, year: { $year: '$createdAt' } }, count: { $sum: 1 } } }
            ]),
            Location.aggregate<{ _id: { month: number; year: number }; count: number }>([
                { $match: buildScopedLocationQuery({ createdAt: { $gte: sixMonthsAgo } }) },
                { $group: { _id: { month: { $month: '$createdAt' }, year: { $year: '$createdAt' } }, count: { $sum: 1 } } }
            ]),
            LocationAnalytics.find(hotZoneQuery).select('locationId popularityScore searchCount adsCount').sort({ popularityScore: -1, searchCount: -1 }).limit(10).lean<{ locationId: string; popularityScore: number; searchCount: number; adsCount: number }[]>()
        ]);
        return {
            totalLocations,
            totalAds,
            totalUsers,
            adsByLocationAgg: adsByLocationAgg || [],
            monthlyAds: monthlyAds || [],
            monthlyUsers: monthlyUsers || [],
            monthlyLocs: monthlyLocs || [],
            topHotZonesRaw: topHotZonesRaw || []
        };
    }

    public async getHotZoneLocations(locationIds: string[]): Promise<AdminLocationSummary[]> {
        if (locationIds.length === 0) return [];
        return (await Location.find({ _id: { $in: locationIds } }).select('_id name country level parentId path').lean<AdminLocationSummary[]>()) || [];
    }

    public async getAnalyticsLocations(locationIds: string[]): Promise<AdminLocationSummary[]> {
        if (locationIds.length === 0) return [];
        return (await Location.find({ _id: { $in: locationIds } }).select('_id name country level parentId path').lean<AdminLocationSummary[]>()) || [];
    }

    public async getCatalogEntityCounts(): Promise<Record<string, number>> {
        const nonDeletedFilter = { isDeleted: { $ne: true } };

        const countCollection = async (model: any, name: string): Promise<number> => {
            try {
                return await model.countDocuments(nonDeletedFilter).hint({ isDeleted: 1 }).exec();
            } catch (error) {
                logger.warn(`Failed to count ${name} using hint`, { error });
                return await model.countDocuments(nonDeletedFilter).exec();
            }
        };

        const [categories, brands, models, spareParts, serviceTypes, screenSizes] = await Promise.all([
            countCollection(Category, 'Category'),
            countCollection(Brand, 'Brand'),
            countCollection(CatalogModel, 'Model'),
            countCollection(SparePart, 'SparePart'),
            countCollection(ServiceType, 'ServiceType'),
            countCollection(ScreenSize, 'ScreenSize')
        ]);

        return { categories, brands, models, spareParts, serviceTypes, screenSizes };
    }
}

import mongoose, { type ClientSession } from 'mongoose';
import AdModel from '../../../../models/Ad';
import { LISTING_STATUS, LISTING_TYPE, SERVICE_STATUS, INVENTORY_STATUS } from '@esparex/contracts';

import {
    type ActiveListingCountFilter,
    type Listing,
    type ListingFilter,
    type ListingUpdate,
    ListingRepositoryPort,
} from '../../../../domains/listings';

// ─── Domain mapper ──────────────────────────────────────────────────────────

type DbListing = {
    _id: unknown;
    title: string;
    description: string;
    price: number;
    listingType: string;
    sellerId: unknown;
    status: string;
    categoryId: unknown;
    brandId?: unknown;
    modelId?: unknown;
    locationPath?: unknown[];
    images?: string[];
    seoSlug?: string;
    location?: {
        city?: string;
        state?: string;
        country?: string;
        display?: string;
        coordinates?: { coordinates?: [number, number] };
        locationId?: unknown;
    };
    isDeleted?: boolean;
    isSold?: boolean;
    moderationStatus?: string;
    fraudScore?: number;
    sellerTrustSnapshot?: number;
    sellerPriorityScore?: number;
    isSpotlight?: boolean;
    // IAd fields: present in Mongoose schema, added for DTO parity with browse pipeline
    sellerType?: 'user' | 'business';
    businessId?: unknown;
    deviceCondition?: 'power_on' | 'power_off';

    spotlightExpiresAt?: Date;
    expiresAt?: Date;
    views?: {
        total?: number;
        unique?: number;
        favorites?: number;
        lastViewedAt?: Date;
    };
    createdAt: Date;
    updatedAt: Date;
};

const PUBLIC_LISTING_PROJECTION = {
    _id: 1, id: 1, title: 1, price: 1, description: 1, images: 1, listingType: 1,
    attributes: 1, category: 1, seoSlug: 1, categoryId: 1, categoryName: 1,
    brandId: 1, brandName: 1, modelId: 1, modelName: 1, screenSize: 1,
    location: 1, sellerId: 1, status: 1, sellerType: 1, createdAt: 1,
    updatedAt: 1, views: 1, isFeatured: 1, isSpotlight: 1, isBoosted: 1,
    isBusiness: 1, verified: 1, businessName: 1, businessId: 1, sellerName: 1, expiresAt: 1
};

function toDomain(doc: DbListing): Listing {
    return {
        id: String(doc._id),
        title: doc.title,
        description: doc.description,
        price: doc.price,
        listingType: doc.listingType as Listing['listingType'],
        sellerId: String(doc.sellerId),
        status: doc.status as Listing['status'],
        categoryId: String(doc.categoryId),
        brandId: doc.brandId ? String(doc.brandId) : undefined,
        modelId: doc.modelId ? String(doc.modelId) : undefined,
        locationPath: Array.isArray(doc.locationPath) ? doc.locationPath.map((id) => String(id)) : undefined,
        images: doc.images ?? [],
        seoSlug: doc.seoSlug,
        location: {
            coordinates: doc.location?.coordinates?.coordinates ?? [0, 0],
            city: doc.location?.city,
            state: doc.location?.state,
            country: doc.location?.country,
            display: doc.location?.display,
            locationId: doc.location?.locationId ? String(doc.location.locationId) : undefined,
        },
        isDeleted: doc.isDeleted ?? false,
        isSold: doc.isSold ?? false,
        moderationStatus: doc.moderationStatus,
        fraudScore: doc.fraudScore,
        sellerTrustSnapshot: doc.sellerTrustSnapshot,
        sellerPriorityScore: doc.sellerPriorityScore,

        isSpotlight: doc.isSpotlight,
        spotlightExpiresAt: doc.spotlightExpiresAt,
        expiresAt: doc.expiresAt,
        views: doc.views ? {
            total: doc.views.total,
            unique: doc.views.unique,
            favorites: doc.views.favorites,
            lastViewedAt: doc.views.lastViewedAt,
        } : undefined,
        // DTO parity: map IAd fields present in Mongoose schema but previously
        // omitted here. Enables normalizeListing() to derive isBusiness correctly
        // and surfaces deviceCondition for the condition badge on all repository paths.
        sellerType: doc.sellerType,
        businessId: doc.businessId ? String(doc.businessId) : undefined,
        deviceCondition: doc.deviceCondition,
        createdAt: doc.createdAt,
        updatedAt: doc.updatedAt,
    };
}

// ─── Filter builder ─────────────────────────────────────────────────────────

function toMongoId(id: unknown): unknown {
    if (typeof id === 'string' && mongoose.Types.ObjectId.isValid(id)) {
        return new mongoose.Types.ObjectId(id);
    }
    if (typeof id === 'string' || typeof id === 'number') {
        return id;
    }
    return String(id ?? '');
}

function buildMongoFilter(filter: ListingFilter): Record<string, unknown> {
    const mongoFilter: Record<string, unknown> = {};

    if (filter._id !== undefined) {
        mongoFilter._id = typeof filter._id === 'object' && filter._id !== null ? filter._id : toMongoId(filter._id);
    }
    if (filter.minPrice !== undefined || filter.maxPrice !== undefined) {
        const priceClause: Record<string, number> = {};
        if (filter.minPrice !== undefined) priceClause.$gte = filter.minPrice;
        if (filter.maxPrice !== undefined) priceClause.$lte = filter.maxPrice;
        mongoFilter.price = priceClause;
    } else if (filter.price !== undefined) {
        mongoFilter.price = filter.price;
    }
    if (filter.titleQuery) {
        mongoFilter.title = { $regex: new RegExp(filter.titleQuery.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i') };
    }
    if (filter.imageHashes !== undefined) {
        mongoFilter.imageHashes = filter.imageHashes;
    }
    if (filter.allowedStatuses && filter.allowedStatuses.length > 0) {
        mongoFilter.status = { $in: filter.allowedStatuses };
    } else if (filter.status) {
        mongoFilter.status = Array.isArray(filter.status) ? { $in: filter.status } : filter.status;
    }
    if (filter.listingType) mongoFilter.listingType = filter.listingType;
    if (filter.excludeSellerId) {
        mongoFilter.sellerId = { ...(mongoFilter.sellerId as Record<string, unknown> || {}), $ne: toMongoId(filter.excludeSellerId) };
    } else if (filter.sellerId) {
        mongoFilter.sellerId = typeof filter.sellerId === 'object' ? filter.sellerId : toMongoId(filter.sellerId);
    }
    if (filter.categoryId) mongoFilter.categoryId = typeof filter.categoryId === 'object' ? filter.categoryId : toMongoId(filter.categoryId);
    if (filter.brandId) mongoFilter.brandId = typeof filter.brandId === 'object' ? filter.brandId : toMongoId(filter.brandId);
    if (filter.modelId) mongoFilter.modelId = typeof filter.modelId === 'object' ? filter.modelId : toMongoId(filter.modelId);
    if (filter.duplicateFingerprint) {
        mongoFilter.duplicateFingerprint = filter.duplicateFingerprint;
    }
    if (filter.isDeleted !== undefined) {
        if (typeof filter.isDeleted === 'object' && filter.isDeleted !== null) {
            mongoFilter.isDeleted = filter.isDeleted;
        } else {
            mongoFilter.isDeleted = filter.isDeleted;
        }
    }
    if (filter.isSold !== undefined) mongoFilter.isSold = filter.isSold;
    if (filter.ids && filter.ids.length > 0) {
        mongoFilter._id = { $in: filter.ids.map(id => toMongoId(id)) };
    }
    if (filter.idsNotIn && filter.idsNotIn.length > 0) {
        mongoFilter._id = { ...(mongoFilter._id as Record<string, unknown> || {}), $nin: filter.idsNotIn.map(id => toMongoId(id)) };
    }
    if (filter.excludeStatus && filter.excludeStatus.length > 0) {
        mongoFilter.status = { ...(mongoFilter.status as Record<string, unknown> || {}), $nin: filter.excludeStatus };
    }
    const locationIdValue = filter.locationId || (filter['location.locationId'] as string);
    if (locationIdValue) {
        mongoFilter['location.locationId'] = toMongoId(locationIdValue);
    }
    if (filter.locationCity) {
        mongoFilter['location.city'] = filter.locationCity;
    }
    if (filter.locationState) {
        mongoFilter['location.state'] = filter.locationState;
    }
    if (filter.locationPath) {
        mongoFilter.locationPath = toMongoId(filter.locationPath);
    }
    if (filter.spotlightActiveOnly) {
        mongoFilter.isSpotlight = true;
        mongoFilter.spotlightExpiresAt = { $gt: new Date() };
    } else if (filter.isSpotlight !== undefined) {
        mongoFilter.isSpotlight = filter.isSpotlight;
    }
    if (filter.spotlightExpiredBefore) {
        mongoFilter.spotlightExpiresAt = { $lte: filter.spotlightExpiredBefore };
    } else if (filter.spotlightExpiresAt) {
        mongoFilter.spotlightExpiresAt = filter.spotlightExpiresAt;
    }
    if (filter.expiredBefore) {
        mongoFilter.expiresAt = { $lte: filter.expiredBefore };
    } else if (filter.expiresAt) {
        mongoFilter.expiresAt = filter.expiresAt;
    }
    if (filter.sparePartIds) {
        mongoFilter.sparePartIds = toMongoId(filter.sparePartIds);
    }
    if (filter.favoritesGreaterThan !== undefined) {
        mongoFilter['views.favorites'] = { $gt: filter.favoritesGreaterThan };
    }
    if (filter.allowedModerationStatuses && filter.allowedModerationStatuses.length > 0) {
        mongoFilter.moderationStatus = { ...(mongoFilter.moderationStatus as Record<string, unknown> || {}), $in: filter.allowedModerationStatuses };
    } else if (filter.excludeModerationStatuses && filter.excludeModerationStatuses.length > 0) {
        mongoFilter.moderationStatus = { ...(mongoFilter.moderationStatus as Record<string, unknown> || {}), $nin: filter.excludeModerationStatuses };
    } else if (filter.moderationStatus) {
        mongoFilter.moderationStatus = filter.moderationStatus;
    }

    // Cursor pagination mapping
    if (filter.cursorCreatedAt) {
        if (filter.cursorId) {
            mongoFilter.$or = [
                ...(mongoFilter.$or as Record<string, unknown>[] || []),
                { createdAt: { $lt: filter.cursorCreatedAt } },
                {
                    createdAt: filter.cursorCreatedAt,
                    _id: { $lt: toMongoId(filter.cursorId) }
                }
            ];
        } else {
            mongoFilter.createdAt = { $lt: filter.cursorCreatedAt };
        }
    }

    if (filter.$or && !filter.cursorCreatedAt) {
        mongoFilter.$or = filter.$or;
    } else if (filter.$or && filter.cursorCreatedAt) {
        // If we already set $or from cursor, merge any existing $or using $and
        const existingOr = mongoFilter.$or as Record<string, unknown>[];
        delete mongoFilter.$or;
        mongoFilter.$and = [
            { $or: filter.$or },
            { $or: existingOr }
        ];
    }

    return mongoFilter;
}

async function resolveMongoQuery<T>(q: unknown): Promise<T> {
    let curr: any = q;
    if (curr && typeof curr.select === 'function') curr = curr.select();
    if (curr && typeof curr.lean === 'function') curr = curr.lean();
    if (curr && typeof curr.exec === 'function') curr = await curr.exec();
    else curr = await curr;
    return curr as T;
}

// ─── Adapter implementation ─────────────────────────────────────────────────

export class MongoListingRepositoryAdapter implements ListingRepositoryPort {
    async countActiveBySeller(filter: ActiveListingCountFilter): Promise<number> {
        const { sellerId, listingType, session } = filter;

        if (listingType === LISTING_TYPE.SERVICE) {
            let query = AdModel.countDocuments({
                sellerId,
                listingType: LISTING_TYPE.SERVICE,
                status: { $in: [SERVICE_STATUS.LIVE, SERVICE_STATUS.PENDING] },
                isDeleted: { $ne: true },
            });
            if (session) query = query.session(session as Parameters<typeof query.session>[0]);
            return query;
        }

        if (listingType === LISTING_TYPE.SPARE_PART) {
            let query = AdModel.countDocuments({
                sellerId,
                listingType: LISTING_TYPE.SPARE_PART,
                status: { $in: [INVENTORY_STATUS.LIVE, INVENTORY_STATUS.PENDING] },
                isDeleted: { $ne: true },
            });
            if (session) query = query.session(session as Parameters<typeof query.session>[0]);
            return query;
        }

        let query = AdModel.countDocuments({
            sellerId,
            listingType: LISTING_TYPE.AD,
            status: { $in: [LISTING_STATUS.LIVE, LISTING_STATUS.PENDING] },
            isDeleted: { $ne: true },
        });
        if (session) query = query.session(session as Parameters<typeof query.session>[0]);
        return query;
    }

    async count(filter: ListingFilter): Promise<number> {
        return AdModel.countDocuments(buildMongoFilter(filter));
    }

    async findWithinRadius(
        lng: number,
        lat: number,
        radiusKm: number,
        filter: ListingFilter,
        sort?: Record<string, 1 | -1>,
        limit?: number,
        skip?: number
    ): Promise<Listing[]> {
        const mongoFilter = buildMongoFilter(filter);

        mongoFilter['location.coordinates'] = {
            $near: {
                $geometry: {
                    type: 'Point',
                    coordinates: [lng, lat]
                },
                $maxDistance: radiusKm * 1000
            }
        };

        let q = AdModel.find(mongoFilter).select(PUBLIC_LISTING_PROJECTION);
        if (sort) {
            q = q.sort(sort);
        }
        if (skip !== undefined) q = q.skip(skip);
        if (limit !== undefined) q = q.limit(limit);
        if (filter.session) q = q.session(filter.session as ClientSession);

        const docs = await q.lean<DbListing[]>();
        return (docs || []).map(toDomain);
    }

    async findById(id: string): Promise<Listing | null> {
        const safeId = typeof id === 'string' && mongoose.Types.ObjectId.isValid(id) ? new mongoose.Types.ObjectId(id) : String(id);
        const doc = await resolveMongoQuery<DbListing | null>(AdModel.findById(safeId));
        return doc ? toDomain(doc) : null;
    }

    async find(filter: ListingFilter): Promise<readonly Listing[]> {
        const rawDocs = await resolveMongoQuery<DbListing[]>(AdModel.find(buildMongoFilter(filter)).select(PUBLIC_LISTING_PROJECTION));
        const docs = Array.isArray(rawDocs) ? rawDocs : [];
        return docs.map(toDomain);
    }

    async findWithLimit(filter: ListingFilter, sort?: Record<string, 1 | -1>, limit?: number, skip?: number): Promise<readonly Listing[]> {
        let q = AdModel.find(buildMongoFilter(filter)).select(PUBLIC_LISTING_PROJECTION);
        if (sort) q = q.sort(sort);
        if (skip !== undefined) q = q.skip(skip);
        if (limit !== undefined) q = q.limit(limit);
        const rawDocs = await resolveMongoQuery<DbListing[]>(q);
        const docs = Array.isArray(rawDocs) ? rawDocs : [];
        return docs.map(toDomain);
    }

    async findOne(filter: ListingFilter): Promise<Listing | null> {
        const doc = await resolveMongoQuery<DbListing | null>(AdModel.findOne(buildMongoFilter(filter)));
        return doc ? toDomain(doc) : null;
    }

    async insert(listing: ListingUpdate, session?: unknown): Promise<Listing> {
        const docs = await AdModel.create([listing as Record<string, unknown>], { session: session as ClientSession });
        const rawDoc: unknown = docs[0];
        return toDomain(rawDoc as DbListing);
    }

    async updateOne(id: string, update: ListingUpdate, session?: unknown): Promise<Listing | null> {
        const safeId = typeof id === 'string' && mongoose.Types.ObjectId.isValid(id) ? new mongoose.Types.ObjectId(id) : String(id);
        const updateDoc = Object.keys(update).some(k => k.startsWith('$')) ? update : { $set: update };
        const query = AdModel.findByIdAndUpdate(safeId, updateDoc, { new: true, runValidators: true, session: session as ClientSession });
        const doc = await resolveMongoQuery<DbListing | null>(query);
        return doc ? toDomain(doc) : null;
    }

    async updateOneByFilter(filter: ListingFilter, update: ListingUpdate, session?: unknown): Promise<Listing | null> {
        const updateDoc = Object.keys(update).some(k => k.startsWith('$')) ? update : { $set: update };
        const filterDoc = buildMongoFilter(filter);
        const targetId = (filterDoc._id as { $in?: unknown[] } | undefined)?.$in?.[0] ?? filterDoc._id;
        const query = AdModel.findOneAndUpdate(
            filterDoc._id ? { ...filterDoc, _id: targetId } : filterDoc,
            updateDoc,
            { new: true, runValidators: true, session: session as ClientSession }
        );
        const doc = await resolveMongoQuery<DbListing | null>(query);
        return doc ? toDomain(doc) : null;
    }

    async updateMany(filter: ListingFilter, update: ListingUpdate, session?: unknown): Promise<number> {
        const updateDoc = Object.keys(update).some(k => k.startsWith('$')) ? update : { $set: update };
        const filterDoc = buildMongoFilter(filter);
        if (typeof AdModel.updateMany === 'function') {
            const result = await resolveMongoQuery<{ modifiedCount?: number } | null>(
                AdModel.updateMany(filterDoc, updateDoc).session(session as ClientSession)
            );
            return result?.modifiedCount ?? 0;
        }
        if (typeof AdModel.findOneAndUpdate === 'function') {
            const targetId = (filterDoc._id as { $in?: unknown[] } | undefined)?.$in?.[0] ?? filterDoc._id;
            await resolveMongoQuery(
                AdModel.findOneAndUpdate(
                    filterDoc._id ? { ...filterDoc, _id: targetId } : filterDoc,
                    updateDoc,
                    { runValidators: true, session: session as ClientSession }
                )
            );
            return 1;
        }
        return 0;
    }
}

import mongoose from 'mongoose';
import logger from '../utils/logger';

interface MongooseHookContext {
    model?: { 
        modelName: string;
        db?: { models?: Record<string, unknown> };
    };
    _model?: { modelName: string };
    _startTime?: number;
    op?: string;
}

const ADMIN_OWNED_REF_MODEL_BY_PATH: Record<string, 'Category' | 'Brand' | 'Model' | 'SparePart' | 'ServiceType'> = {
    categoryId: 'Category',
    categoryIds: 'Category',
    'criteria.categoryId': 'Category',
    brandId: 'Brand',
    'criteria.brandId': 'Brand',
    modelId: 'Model',
    'criteria.modelId': 'Model',
    sparePartId: 'SparePart',
    sparePartIds: 'SparePart',
    serviceTypeIds: 'ServiceType',
};

const toPopulateSpecs = (args: unknown[]): Array<{ path: string; hasExplicitModel: boolean }> => {
    const first = args[0];
    const third = args[2];
    const specs: Array<{ path: string; hasExplicitModel: boolean }> = [];

    const addPathSpecs = (rawPath: unknown, hasExplicitModel: boolean) => {
        if (typeof rawPath !== 'string') return;
        rawPath
            .split(/\s+/)
            .map((part) => part.trim())
            .filter(Boolean)
            .forEach((path) => specs.push({ path, hasExplicitModel }));
    };

    if (typeof first === 'string') {
        addPathSpecs(first, Boolean(third));
        return specs;
    }

    const parsePopulateObject = (value: unknown) => {
        if (!value || typeof value !== 'object') return;
        const node = value as { path?: unknown; model?: unknown };
        if (typeof node.path === 'string') {
            addPathSpecs(node.path, Boolean(node.model));
            return;
        }
        Object.keys(value).forEach((key) => {
            addPathSpecs(key, false);
        });
    };

    if (Array.isArray(first)) {
        first.forEach(parsePopulateObject);
        return specs;
    }

    parsePopulateObject(first);
    return specs;
};

const installPopulateGovernanceGuard = () => {
    const mongooseWithGuard = mongoose as typeof mongoose & { __esparexPopulateGuardInstalled?: boolean };
    if (mongooseWithGuard.__esparexPopulateGuardInstalled) {
        return;
    }

    const queryProto = mongoose.Query.prototype as {
        populate: (...args: unknown[]) => unknown;
    };
    const originalPopulate = queryProto.populate;

    queryProto.populate = function patchedPopulate(this: MongooseHookContext, ...args: unknown[]) {
        const modelName = this?.model?.modelName;
        const connectionModels = (this?.model?.db?.models ?? {});

        const populateSpecs = toPopulateSpecs(args);
        for (const spec of populateSpecs) {
            const expectedModel = ADMIN_OWNED_REF_MODEL_BY_PATH[spec.path];
            if (!expectedModel || spec.hasExplicitModel) continue;
            if (connectionModels[expectedModel]) continue;

            throw new Error(
                `[PopulateGovernance] Unsafe populate("${spec.path}") on model "${modelName ?? 'unknown'}". ` +
                `Model "${expectedModel}" is not registered on this connection. Use explicit model mapping.`
            );
        }

        return originalPopulate.apply(this, args);
    };

    mongooseWithGuard.__esparexPopulateGuardInstalled = true;
};

installPopulateGovernanceGuard();

// Apply global mongoose plugin to track query execution time
mongoose.plugin((schema) => {
    schema.pre(/^find|count|updateOne|updateMany|deleteOne|deleteMany|findOneAndUpdate/, function (this: MongooseHookContext) {
        this._startTime = Date.now();
    });

    schema.post(/^find|count|updateOne|updateMany|deleteOne|deleteMany|findOneAndUpdate/, function (this: MongooseHookContext) {
        if (this._startTime) {
            const time = Date.now() - this._startTime;
            const modelName = this.model?.modelName || 'Unknown';
            const isLocationModel = modelName === 'Location';
            const warnThresholdMs = isLocationModel ? 800 : 300;
            const errorThresholdMs = isLocationModel ? 2000 : 1000;

            if (time > errorThresholdMs) {
                logger.error(`[SLOW_QUERY] ${modelName}.${this.op} took ${time}ms`, { time, method: this.op, model: modelName });
            } else if (time > warnThresholdMs) {
                logger.warn(`[SLOW_QUERY] ${modelName}.${this.op} took ${time}ms`, { time, method: this.op, model: modelName });
            }
        }
    });

    // Aggregations
    schema.pre('aggregate', function () {
        const rawCtx: unknown = this;
        const ctx = rawCtx as MongooseHookContext;
        ctx._startTime = Date.now();
    });

    schema.post('aggregate', function () {
        const rawCtx: unknown = this;
        const ctx = rawCtx as MongooseHookContext;
        if (ctx._startTime) {
            const time = Date.now() - ctx._startTime;
            const modelName = ctx._model?.modelName || 'Unknown';
            const isLocationModel = modelName === 'Location';
            const warnThresholdMs = isLocationModel ? 800 : 300;
            const errorThresholdMs = isLocationModel ? 2000 : 1000;

            if (time > errorThresholdMs) {
                logger.error(`[SLOW_QUERY] ${modelName}.aggregate took ${time}ms`, { time, model: modelName });
            } else if (time > warnThresholdMs) {
                logger.warn(`[SLOW_QUERY] ${modelName}.aggregate took ${time}ms`, { time, model: modelName });
            }
        }
    });
});

/**
 * Sentry Error Tracking Configuration
 * 
 * Initializes Sentry for error tracking and performance monitoring.
 * Automatically captures errors, unhandled rejections, and performance metrics.
 * 
 * @module config/sentry
 */

import * as Sentry from '@sentry/node';
import { env, isProduction, isDevelopment } from './env';
import logger from '../utils/logger';

let nodeProfilingIntegration: any = null;
try {
    nodeProfilingIntegration = require('@sentry/profiling-node').nodeProfilingIntegration;
} catch (error) {
    logger.warn('Failed to load @sentry/profiling-node native binary. Sentry profiling is disabled.', {
        error: error instanceof Error ? error.message : String(error),
    });
}

/**
 * Initialize Sentry error tracking
 * 
 * Only initializes if SENTRY_DSN is configured.
 * Includes performance monitoring and profiling in production.
 */
export function initSentry() {
    // Skip if Sentry is not configured
    if (!env.SENTRY_DSN) {
        if (isProduction) {
            logger.warn('Sentry DSN not configured. Error tracking disabled in production!');
        } else {
            logger.debug('Sentry DSN not configured. Error tracking disabled.');
        }
        return;
    }

    try {
        Sentry.init({
            dsn: env.SENTRY_DSN,
            environment: env.SENTRY_ENVIRONMENT || env.NODE_ENV,

            // Performance Monitoring
            tracesSampleRate: isProduction ? 0.1 : 1.0, // 10% in prod, 100% in dev

            // Profiling
            profilesSampleRate: isProduction ? 0.1 : 1.0,
            integrations: nodeProfilingIntegration ? [nodeProfilingIntegration()] : [],

            // Release tracking
            release: process.env.npm_package_version,

            // Error filtering
            beforeSend(event, hint) {
                // Don't send errors in development unless explicitly enabled
                if (isDevelopment && !env.SENTRY_ENABLE_DEV) {
                    return null;
                }

                // Filter out known non-critical errors
                const error = hint.originalException;

                if (error instanceof Error) {
                    // Ignore MongoDB connection errors during shutdown
                    if (error.message.includes('topology was destroyed')) {
                        return null;
                    }

                    // Ignore rate limit errors (expected behavior)
                    if (error.message.includes('Too many requests')) {
                        return null;
                    }

                    // Ignore validation errors (user input errors)
                    if (error.message.includes('Validation failed')) {
                        return null;
                    }
                }

                return event;
            },

            // Breadcrumbs configuration
            maxBreadcrumbs: 50,

            // Attach stack traces to all messages
            attachStacktrace: true,
        });

        logger.info('Sentry initialized successfully', {
            environment: env.SENTRY_ENVIRONMENT || env.NODE_ENV,
            tracesSampleRate: isProduction ? 0.1 : 1.0,
        });
    } catch (error) {
        logger.error('Failed to initialize Sentry', {
            error: error instanceof Error ? error.message : String(error),
        });
    }
}

/**
 * Capture an exception in Sentry
 * 
 * @param error - Error to capture
 * @param context - Additional context
 */
export function captureException(error: Error, context?: Record<string, unknown>) {
    if (!env.SENTRY_DSN) {
        logger.error('Error occurred (Sentry not configured)', {
            error: error.message,
            stack: error.stack,
            ...context,
        });
        return;
    }

    Sentry.captureException(error, {
        extra: context,
    });
}

/**
 * Capture a message in Sentry
 * 
 * @param message - Message to capture
 * @param level - Severity level
 * @param context - Additional context
 */
export function captureMessage(
    message: string,
    level: 'fatal' | 'error' | 'warning' | 'info' | 'debug' = 'info',
    context?: Record<string, unknown>
) {
    if (!env.SENTRY_DSN) {
        logger.log(level === 'fatal' ? 'error' : level, message, context);
        return;
    }

    Sentry.captureMessage(message, {
        level,
        extra: context,
    });
}

/**
 * Set user context for error tracking
 * 
 * @param user - User information
 */
export function setUser(user: { id: string; email?: string; username?: string }) {
    if (!env.SENTRY_DSN) return;

    Sentry.setUser({
        id: user.id,
        email: user.email,
        username: user.username,
    });
}

/**
 * Clear user context
 */
export function clearUser() {
    if (!env.SENTRY_DSN) return;
    Sentry.setUser(null);
}

/**
 * Add breadcrumb for debugging
 * 
 * @param message - Breadcrumb message
 * @param category - Category (e.g., 'auth', 'db', 'api')
 * @param data - Additional data
 */
export function addBreadcrumb(
    message: string,
    category: string,
    data?: Record<string, unknown>
) {
    if (!env.SENTRY_DSN) return;

    Sentry.addBreadcrumb({
        message,
        category,
        data,
        level: 'info',
    });
}

/**
 * Note: Transaction API has been deprecated in Sentry v8+
 * Use Sentry.startSpan() instead for performance monitoring
 * This function is kept for backward compatibility but does nothing
 */
export function startTransaction(name: string, op: string) {
    void name;
    void op;
    if (!env.SENTRY_DSN) {
        return {
            finish: () => { },
            setStatus: () => { },
            setData: () => { },
        };
    }

    // Return a no-op object for backward compatibility
    return {
        finish: () => { },
        setStatus: () => { },
        setData: () => { },
    };
}

/**
 * Flush Sentry events (useful before shutdown)
 * 
 * @param timeout - Timeout in milliseconds
 */
export async function flushSentry(timeout = 2000): Promise<boolean> {
    if (!env.SENTRY_DSN) return true;

    try {
        return await Sentry.close(timeout);
    } catch (error) {
        logger.error('Failed to flush Sentry', {
            error: error instanceof Error ? error.message : String(error),
        });
        return false;
    }
}

export default Sentry;

import { CATALOG_APPROVAL_STATUS } from '@esparex/contracts';
import { CATALOG_STATUS } from '@esparex/contracts';
import { scoreModeratorTrust } from '../services/CatalogSearchGovernanceService';

export const setEntityField = (entity: unknown, field: string, value: unknown): void => {
    const maybeDocument = entity as Record<string, unknown> & { set?: (path: string, val: unknown) => void };
    if (typeof maybeDocument.set === 'function') { maybeDocument.set(field, value); return; }
    Reflect.set(entity as object, field, value);
};

export const ensureCatalogActivationFlags = (entity: {
    approvalStatus?: string; isActive?: boolean; status?: string;
    rejectionReason?: string | null; needsReview?: boolean;
}): boolean => {
    let changed = false;
    if (entity.approvalStatus !== CATALOG_APPROVAL_STATUS.APPROVED) { setEntityField(entity, 'approvalStatus', CATALOG_APPROVAL_STATUS.APPROVED); changed = true; }
    if (entity.isActive !== true) { setEntityField(entity, 'isActive', true); changed = true; }
    if (entity.status !== CATALOG_STATUS.ACTIVE) { setEntityField(entity, 'status', CATALOG_STATUS.ACTIVE); changed = true; }
    if (entity.rejectionReason) { setEntityField(entity, 'rejectionReason', undefined); changed = true; }
    if (typeof entity.needsReview === 'boolean' && entity.needsReview) { setEntityField(entity, 'needsReview', false); changed = true; }
    return changed;
};

export const buildApprovalTrustMetadata = (params: { requestCount?: number; createdCanonicalEntity?: boolean; duplicateResolution?: boolean }): Record<string, unknown> => {
    const requestCount = Math.max(1, Number(params.requestCount ?? 1));
    const moderatorTrustScore = scoreModeratorTrust({
        approvedActions: requestCount,
        duplicateApprovals: params.duplicateResolution ? requestCount : 0,
        aliasApprovals: params.createdCanonicalEntity ? 1 : 0,
    });
    const duplicateConfidenceScore = params.duplicateResolution ? 0.92 : Math.max(0.18, 0.52 - Math.min(0.22, requestCount / 200));
    const canonicalCertaintyScore = params.duplicateResolution ? 0.88 : Math.min(0.94, 0.72 + Math.min(0.16, requestCount / 100));
    return {
        catalogTrustScore: Math.min(0.95, (moderatorTrustScore * 0.45) + (canonicalCertaintyScore * 0.45) + 0.08),
        variantTrustScore: 0.68,
        aliasTrustScore: params.createdCanonicalEntity ? 0.58 : 0.64,
        synonymTrustScore: params.createdCanonicalEntity ? 0.54 : 0.6,
        transliterationTrustScore: 0.64,
        moderatorTrustScore,
        moderationReliabilityScore: moderatorTrustScore,
        aliasApprovalConfidence: params.createdCanonicalEntity ? 0.56 : 0.66,
        synonymApprovalConfidence: params.createdCanonicalEntity ? 0.52 : 0.62,
        popularityConfidenceScore: 0.58,
        canonicalCertaintyScore,
        duplicateConfidenceScore,
        seoQualityScore: params.createdCanonicalEntity ? 0.58 : 0.64,
        crawlDepthLimit: 4, indexable: true, lastAuditAt: new Date(),
    };
};

export const applyMarketplaceTrustMetadata = (entity: Record<string, unknown>, metadata: Record<string, unknown>): void => {
    setEntityField(entity, 'marketplaceTrust', {
        ...(entity.marketplaceTrust && typeof entity.marketplaceTrust === 'object' ? entity.marketplaceTrust : {}),
        ...metadata,
    });
};

export const ensureEntityActiveAndTrusted = async (
    entity: { categoryIds?: unknown[]; save: (...args: any[]) => Promise<any>; approvalStatus?: string; isActive?: boolean; status?: string; rejectionReason?: string | null; needsReview?: boolean },
    request: { requestCount?: number; categoryId: unknown },
    session: unknown,
    trustParams: { createdCanonicalEntity?: boolean; duplicateResolution?: boolean }
): Promise<void> => {
    let needsSave = ensureCatalogActivationFlags(entity);
    if (!hasObjectId(entity.categoryIds, request.categoryId)) { entity.categoryIds = [...(entity.categoryIds ?? []), request.categoryId]; needsSave = true; }
    applyMarketplaceTrustMetadata(entity, buildApprovalTrustMetadata({ requestCount: request.requestCount, ...trustParams }));
    needsSave = true;
    if (needsSave) await entity.save({ session });
};

const hasObjectId = (items: unknown, target: unknown): boolean => {
    if (!Array.isArray(items)) return false;
    const targetValue = String(target);
    return items.some((item) => String(item) === targetValue);
};

import { type ClientSession, type Types } from 'mongoose';
import { CATALOG_APPROVAL_STATUS } from '@esparex/contracts';
import { CATALOG_STATUS } from '@esparex/contracts';
import Brand from '../../../../models/Brand';
import CatalogModel from '../../../../models/Model';
import type { ICatalogRequest } from '../../../../models/CatalogRequest';
import { AppError } from '../../../../utils/AppError';
import { buildCatalogSlug, resolveRequestCanonicalName, NON_DELETED_QUERY } from './validation';
import { buildApprovalTrustMetadata, ensureEntityActiveAndTrusted } from './entity';

export const resolveOrCreateBrand = async (request: ICatalogRequest, session: ClientSession): Promise<{ entityId: Types.ObjectId; createdCanonicalEntity: boolean }> => {
    const requestCanonicalName = resolveRequestCanonicalName(request);
    let existingBrand = await Brand.findOne({
        canonicalName: requestCanonicalName, ...NON_DELETED_QUERY,
        approvalStatus: { $in: [CATALOG_APPROVAL_STATUS.APPROVED, CATALOG_APPROVAL_STATUS.PENDING] },
    }).session(session);
    if (existingBrand) {
        await ensureEntityActiveAndTrusted(existingBrand, request, session, { createdCanonicalEntity: false });
        return { entityId: existingBrand._id as Types.ObjectId, createdCanonicalEntity: false };
    }
    try {
        const created = await Brand.create([{
            name: request.requestedName, displayName: request.requestedName, canonicalName: requestCanonicalName,
            slug: buildCatalogSlug(request.requestedName, 'brand'), categoryIds: [request.categoryId],
            isActive: true, approvalStatus: CATALOG_APPROVAL_STATUS.APPROVED, status: CATALOG_STATUS.ACTIVE,
            suggestedBy: request.requestedBy,
            marketplaceTrust: buildApprovalTrustMetadata({ requestCount: request.requestCount, createdCanonicalEntity: true }),
        }], { session });
        return { entityId: created[0]._id as Types.ObjectId, createdCanonicalEntity: true };
    } catch (error: any) {
        if (error.code !== 11000) throw error;
        existingBrand = await Brand.findOne({ canonicalName: requestCanonicalName, ...NON_DELETED_QUERY, approvalStatus: { $in: [CATALOG_APPROVAL_STATUS.APPROVED, CATALOG_APPROVAL_STATUS.PENDING] } }).session(session);
        if (!existingBrand) throw error;
        await ensureEntityActiveAndTrusted(existingBrand, request, session, { createdCanonicalEntity: false });
        return { entityId: existingBrand._id as Types.ObjectId, createdCanonicalEntity: false };
    }
};

export const resolveOrCreateModel = async (request: ICatalogRequest, session: ClientSession): Promise<{ entityId: Types.ObjectId; createdCanonicalEntity: boolean }> => {
    if (!request.parentBrandId) throw new AppError('Model requests require a parentBrandId.', 400, 'CATALOG_REQUEST_PARENT_BRAND_REQUIRED');
    const requestCanonicalName = resolveRequestCanonicalName(request);
    let existingModel = await CatalogModel.findOne({
        brandId: request.parentBrandId, canonicalName: requestCanonicalName, ...NON_DELETED_QUERY,
        approvalStatus: { $in: [CATALOG_APPROVAL_STATUS.APPROVED, CATALOG_APPROVAL_STATUS.PENDING] },
    }).session(session);
    if (existingModel) {
        await ensureEntityActiveAndTrusted(existingModel, request, session, { createdCanonicalEntity: false });
        return { entityId: existingModel._id as Types.ObjectId, createdCanonicalEntity: false };
    }
    try {
        const created = await CatalogModel.create([{
            name: request.requestedName, displayName: request.requestedName, canonicalName: requestCanonicalName,
            slug: buildCatalogSlug(request.requestedName, 'model'), brandId: request.parentBrandId,
            categoryIds: [request.categoryId], isActive: true, approvalStatus: CATALOG_APPROVAL_STATUS.APPROVED,
            status: CATALOG_STATUS.ACTIVE, suggestedBy: request.requestedBy,
            marketplaceTrust: buildApprovalTrustMetadata({ requestCount: request.requestCount, createdCanonicalEntity: true }),
        }], { session });
        return { entityId: created[0]._id as Types.ObjectId, createdCanonicalEntity: true };
    } catch (error: any) {
        if (error.code !== 11000) throw error;
        existingModel = await CatalogModel.findOne({ brandId: request.parentBrandId, canonicalName: requestCanonicalName, ...NON_DELETED_QUERY, approvalStatus: { $in: [CATALOG_APPROVAL_STATUS.APPROVED, CATALOG_APPROVAL_STATUS.PENDING] } }).session(session);
        if (!existingModel) throw error;
        await ensureEntityActiveAndTrusted(existingModel, request, session, { createdCanonicalEntity: false });
        return { entityId: existingModel._id as Types.ObjectId, createdCanonicalEntity: false };
    }
};

export const resolveDuplicateEntity = async (request: ICatalogRequest, duplicateOfEntityId: Types.ObjectId, session: ClientSession): Promise<Types.ObjectId> => {
    if (request.requestType === 'brand') {
        const brand = await Brand.findOne({ _id: duplicateOfEntityId, ...NON_DELETED_QUERY }).session(session);
        if (!brand) throw new AppError('Duplicate target brand was not found.', 404, 'DUPLICATE_ENTITY_NOT_FOUND');
        await ensureEntityActiveAndTrusted(brand, request, session, { duplicateResolution: true });
        return brand._id as Types.ObjectId;
    }
    const model = await CatalogModel.findOne({ _id: duplicateOfEntityId, ...NON_DELETED_QUERY }).session(session);
    if (!model) throw new AppError('Duplicate target model was not found.', 404, 'DUPLICATE_ENTITY_NOT_FOUND');
    if (request.parentBrandId && String(model.brandId) !== String(request.parentBrandId)) throw new AppError('Duplicate model must belong to the requested parent brand.', 400, 'DUPLICATE_ENTITY_BRAND_MISMATCH');
    await ensureEntityActiveAndTrusted(model, request, session, { duplicateResolution: true });
    return model._id as Types.ObjectId;
};

import type { Model } from 'mongoose';
import logger from '../../../../utils/logger';
import { escapeRegExp } from '../../../../utils/stringUtils';
import type { AtlasCatalogSearchResult, SeoCrawlDecision } from './types';
import {
    normalizeCatalogSearchText,
    compact,
} from './transliteration';
import { telemetry } from './telemetry';
import { getTrustSignals } from './scoring';

const MAX_SEARCH_VARIANTS = 5;
const MAX_ATLAS_SHOULD_CLAUSES = 36;
const MIN_SEO_INDEX_QUALITY = 0.52;
const MAX_SEO_CRAWL_DEPTH = 4;

export function buildSearchVariants(search: string): string[] {
    const normalized = normalizeCatalogSearchText(search);
    const collapsed = compact(normalized);
    const variants: string[] = [];
    const pushVariant = (value: string) => {
        const normalizedValue = normalizeCatalogSearchText(value);
        if (normalizedValue.length < 2) return;
        if (!variants.includes(normalizedValue)) variants.push(normalizedValue);
    };

    pushVariant(search.trim());
    if (normalized) pushVariant(normalized);
    if (collapsed && collapsed !== normalized && collapsed.length >= 4) pushVariant(collapsed);

    if (normalized.length >= 4) {
        pushVariant(normalized.replace(/\biphne\b/g, 'iphone'));
        pushVariant(normalized.replace(/\bsamung\b/g, 'samsung'));
    }
    if (normalized.length >= 6) {
        pushVariant(normalized.replace(/dh/g, 'd'));
        pushVariant(normalized.replace(/dy/g, 'di'));
    }

    return variants.slice(0, MAX_SEARCH_VARIANTS);
}

export function buildRegexSearchClauses(search: string, searchFields: string[]): Record<string, unknown>[] {
    const variants = buildSearchVariants(search);
    const clauses: Record<string, unknown>[] = [];
    for (const variant of variants) {
        const safeSearch = escapeRegExp(variant);
        for (const field of searchFields) {
            clauses.push({ [field]: { $regex: safeSearch, $options: 'i' } });
        }
    }
    return clauses;
}

export async function tryAtlasCatalogSearch(params: {
    model: Model<any>;
    query: Record<string, unknown>;
    search: string;
    searchFields: string[];
    skip: number;
    limit: number;
    indexName?: string;
}): Promise<AtlasCatalogSearchResult | null> {
    const variants = buildSearchVariants(params.search);
    if (variants.length === 0) return null;
    const queryCost = variants.length * params.searchFields.length;
    telemetry.queryCostUnits += queryCost;
    if (queryCost > MAX_ATLAS_SHOULD_CLAUSES) { telemetry.atlasFallbacks++; return null; }
    telemetry.atlasAttempts++;

    try {
        const should = variants.flatMap((query) => params.searchFields.map((path) => ({
            text: {
                query,
                path,
                fuzzy: { maxEdits: query.length > 7 ? 2 : 1, prefixLength: Math.min(3, Math.max(1, query.length - 2)) },
                score: { boost: { value: path === 'canonicalName' ? 12 : path === 'slug' ? 10 : path === 'displayName' || path === 'name' ? 7 : 3 } },
            },
        }))).slice(0, MAX_ATLAS_SHOULD_CLAUSES);

        const filterClauses: Record<string, any>[] = [];
        const mustNotClauses: Record<string, any>[] = [];
        const MAPPED_ATLAS_FIELDS = new Set(['isActive', 'isDeleted', 'approvalStatus', 'categoryIds', 'brandId', 'parentModelId', 'variantOfModelId', 'type']);

        for (const [key, rawVal] of Object.entries(params.query)) {
            let targetPath = key;
            if (key === 'categoryId') targetPath = 'categoryIds';
            if (key === 'variantModelId') targetPath = 'variantOfModelId';
            if (!MAPPED_ATLAS_FIELDS.has(targetPath)) continue;

            if (rawVal && typeof rawVal === 'object' && !Array.isArray(rawVal) && !(rawVal instanceof Date)) {
                const keys = Object.keys(rawVal);
                if (keys.length === 1) {
                    const op = keys[0];
                    const opVal = (rawVal as Record<string, any>)[op];
                    if (op === '$ne') {
                        mustNotClauses.push({ equals: { path: targetPath, value: typeof opVal === 'object' && opVal ? String(opVal) : opVal } });
                    } else if (op === '$in' && Array.isArray(opVal)) {
                        filterClauses.push({ in: { path: targetPath, value: opVal.map((v: any) => typeof v === 'object' && v ? String(v) : v) } });
                    } else if (op === '$nin' && Array.isArray(opVal)) {
                        mustNotClauses.push({ in: { path: targetPath, value: opVal.map((v: any) => typeof v === 'object' && v ? String(v) : v) } });
                    }
                }
            } else if (Array.isArray(rawVal)) {
                filterClauses.push({ in: { path: targetPath, value: rawVal.map((v: any) => typeof v === 'object' && v ? String(v) : v) } });
            } else {
                filterClauses.push({ equals: { path: targetPath, value: typeof rawVal === 'object' && rawVal ? String(rawVal) : rawVal } });
            }
        }

        const compound: Record<string, any> = { should, minimumShouldMatch: 1 };
        if (filterClauses.length > 0) compound.filter = filterClauses;
        if (mustNotClauses.length > 0) compound.mustNot = mustNotClauses;

        const atlasStartedAt = Date.now();
        const rows = await params.model.aggregate([
            { $search: { index: params.indexName || process.env.ATLAS_CATALOG_SEARCH_INDEX || 'catalog_search', compound } },
            { $match: params.query },
            { $skip: params.skip },
            { $limit: params.limit },
            { $project: { _id: 1, score: { $meta: 'searchScore' } } },
        ]).option({ maxTimeMS: Number(process.env.ATLAS_CATALOG_SEARCH_TIMEOUT_MS || 1200) });
        telemetry.atlasLatencyMs += Date.now() - atlasStartedAt;

        const scores = new Map<string, number>();
        const ids = rows.map((row) => { const id = String(row._id); scores.set(id, Number(row.score ?? 0)); return id; });
        return { ids, scores };
    } catch (error) {
        telemetry.atlasFallbacks++;
        logger.warn('[CatalogSearch] Atlas Search unavailable; using governed regex fallback', {
            modelName: params.model.modelName,
            error: error instanceof Error ? error.message : String(error),
        });
        return null;
    }
}

export function buildSeoCanonicalPath(item: Record<string, unknown>): string | null {
    const segments = [item.categorySlug, item.brandSlug, item.parentSlug, item.slug]
        .map((segment) => normalizeCatalogSearchText(segment as string | undefined).replace(/\s+/g, '-'))
        .filter(Boolean);
    if (segments.length === 0) return null;
    return `/${segments.join('/')}`;
}

export function evaluateSeoCrawlDecision(item: Record<string, unknown>): SeoCrawlDecision {
    const canonicalPath = buildSeoCanonicalPath(item);
    const trust = getTrustSignals(item);
    const segments = canonicalPath ? canonicalPath.split('/').filter(Boolean) : [];
    const crawlDepth = segments.length;
    const reasons: string[] = [];
    const canonicalName = normalizeCatalogSearchText(item.canonicalName as string | undefined);
    const displayName = normalizeCatalogSearchText((item.displayName ?? item.name) as string | undefined);
    const descriptionLength = String(item.description ?? '').trim().length;
    const hasLineage = Boolean(item.categorySlug || item.brandSlug || item.parentSlug || item.modelId || item.brandId);
    const duplicateConfidence = trust.duplicateConfidenceScore ?? 0.5;
    let qualityScore = clamp01(trust.seoQualityScore, 0.6);

    if (!canonicalPath) { reasons.push('missing_canonical_path'); qualityScore -= 0.3; }
    if (crawlDepth > Math.min(MAX_SEO_CRAWL_DEPTH, trust.crawlDepthLimit ?? MAX_SEO_CRAWL_DEPTH)) { reasons.push('crawl_depth_exceeded'); telemetry.crawlBudgetSuppressions++; qualityScore -= 0.25; }
    if (!canonicalName || canonicalName === displayName && descriptionLength < 80) { reasons.push('thin_content'); telemetry.seoThinPageSuppressions++; qualityScore -= 0.2; }
    if (!hasLineage) { reasons.push('weak_lineage'); qualityScore -= 0.15; }
    if (duplicateConfidence > 0.72) { reasons.push('duplicate_seo_risk'); qualityScore -= 0.25; }
    if (trust.indexable === false) { reasons.push('explicit_noindex'); qualityScore = 0; }

    const finalQuality = clamp01(qualityScore, 0.6);
    telemetry.crawlQualityTotal += finalQuality;
    return {
        indexable: finalQuality >= MIN_SEO_INDEX_QUALITY && !reasons.includes('crawl_depth_exceeded') && !reasons.includes('explicit_noindex'),
        canonicalPath, qualityScore: finalQuality, crawlDepth, reasons,
    };
}

const clamp01 = (value: unknown, fallback = 0.5): number => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return fallback;
    return Math.min(1, Math.max(0, numeric));
};

