export const adminGetLocationAnalyticsData = async (reqQuery: Record<string, unknown>) => {
    const sixMonthsAgo = new Date();
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

    const cityFilter = typeof reqQuery.city === 'string' ? reqQuery.city.trim() : '';
    const districtFilter = typeof reqQuery.district === 'string' ? reqQuery.district.trim() : '';
    const stateFilter = typeof reqQuery.state === 'string' ? reqQuery.state.trim() : '';
    const countryFilter = typeof reqQuery.country === 'string' ? reqQuery.country.trim() : '';

    const scope = await resolveLocationScope({
        city: cityFilter || undefined,
        district: districtFilter || undefined,
        state: stateFilter && stateFilter !== 'all' ? stateFilter : undefined,
        country: countryFilter && countryFilter !== 'all' ? countryFilter : undefined,
    });
    const locationScopeIds = scope.locationIds;

    const buildScopedLocationQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return { isActive: true, ...extra };
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }
        return {
            isActive: true,
            ...extra,
            $or: [
                { _id: { $in: locationScopeIds } },
                { path: { $in: locationScopeIds } },
            ],
        };
    };

    const buildScopedAdQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return extra;
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }
        return {
            ...extra,
            $or: [
                { 'location.locationId': { $in: locationScopeIds } },
                { locationPath: { $in: locationScopeIds } },
            ],
        };
    };

    const buildScopedUserQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return extra;
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }

        const orQuery: Array<Record<string, unknown>> = [
            { locationId: { $in: locationScopeIds } },
            { 'location.locationId': { $in: locationScopeIds } },
        ];

        if (cityFilter) {
            orQuery.push({ 'location.city': new RegExp(`^${escapeRegExp(cityFilter)}$`, 'i') });
        }
        if (stateFilter && stateFilter !== 'all') {
            orQuery.push({ 'location.state': new RegExp(`^${escapeRegExp(stateFilter)}$`, 'i') });
        }

        return {
            ...extra,
            $or: orQuery,
        };
    };

    if (Array.isArray(locationScopeIds) && locationScopeIds.length === 0) {
        return {
            totalLocations: 0,
            totalAds: 0,
            totalUsers: 0,
            topCities: [],
            adsByState: [],
            hotZones: [],
            monthlyTrends: [],
        };
    }

    const hotZoneQuery: Record<string, unknown> = {
        isHotZone: true,
        ...(Array.isArray(locationScopeIds) ? { locationId: { $in: locationScopeIds } } : {}),
    };

    const {
        totalLocations,
        totalAds,
        totalUsers,
        adsByLocationAgg,
        monthlyAds,
        monthlyUsers,
        monthlyLocs,
        topHotZonesRaw,
    } = await getLocationAnalyticsRawData({
        sixMonthsAgo,
        buildScopedLocationQuery,
        buildScopedAdQuery,
        buildScopedUserQuery,
        hotZoneQuery,
    });

    const hotZoneLocationIds = topHotZonesRaw.map((zone: any) => zone.locationId);
    const hotZoneLocations = await getHotZoneLocations(hotZoneLocationIds.map(String));
    const hotZoneHierarchyMap = await loadHierarchyMapForLocations(hotZoneLocations);
    const hotZoneLocationMap = new Map(
        hotZoneLocations.map((location: any) => [String(location._id), location])
    );
    const hotZones = topHotZonesRaw.map((zone: any) => {
        const location = hotZoneLocationMap.get(String(zone.locationId));
        const summary = location ? buildLocationSummary(location, hotZoneHierarchyMap) : undefined;
        return {
            _id: String(zone._id),
            city: summary?.city ?? '',
            state: summary?.state ?? '',
            popularityScore: zone.popularityScore ?? 0,
            isHotZone: true,
        };
    });

    // Format Monthly Trends
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const trends = [];
    for (let i = 0; i < 6; i++) {
        const d = new Date();
        d.setMonth(d.getMonth() - (5 - i));
        const m = d.getMonth() + 1;
        const y = d.getFullYear();

        const ads = monthlyAds.find((a: any) => a._id.month === m && a._id.year === y)?.count || 0;
        const users = monthlyUsers.find((u: any) => u._id.month === m && u._id.year === y)?.count || 0;
        const locs = monthlyLocs.find((l: any) => l._id.month === m && l._id.year === y)?.count || 0;

        trends.push({
            month: monthNames[m - 1],
            adsPosted: ads,
            activeUsers: users,
            newLocations: locs
        });
    }

    const adsByLocationIds = adsByLocationAgg
        .map((entry: any) => entry?._id as string | undefined)
        .filter((value: string | undefined): value is string => Boolean(value))
        .map((value: string) => String(value));
    const analyticsLocations = await getAnalyticsLocations(adsByLocationIds);
    const analyticsHierarchyMap = await loadHierarchyMapForLocations(analyticsLocations);
    const analyticsLocationMap = new Map(
        analyticsLocations.map((location: any) => [String(location._id), location])
    );

    const topCityMap = new Map<string, { _id: string; city: string; state: string; adsCount: number }>();
    const adsByStateMap = new Map<string, { _id: string; count: number }>();

    for (const entry of adsByLocationAgg as Array<{ _id: unknown; adsCount?: number }>) {
        const location = analyticsLocationMap.get(String(entry._id));
        if (!location) continue;

        const summary = buildLocationSummary(location, analyticsHierarchyMap);
        const count = typeof entry?.adsCount === 'number' ? entry.adsCount : Number(entry?.adsCount || 0);

        if (summary.city && summary.state && summary.level !== 'state' && summary.level !== 'country') {
            const cityKey = `${summary.city.toLowerCase()}::${summary.state.toLowerCase()}`;
            const existingCity = topCityMap.get(cityKey);
            if (existingCity) {
                existingCity.adsCount += count;
            } else {
                topCityMap.set(cityKey, {
                    _id: cityKey,
                    city: summary.city,
                    state: summary.state,
                    adsCount: count,
                });
            }
        }

        const stateLabel = normalizeStateLabel(summary.state);
        const stateKey = stateLabel.toLowerCase();
        const existing = adsByStateMap.get(stateKey);
        if (existing) {
            existing.count += count;
            continue;
        }
        adsByStateMap.set(stateKey, { _id: stateLabel, count });
    }
    const topCities = Array.from(topCityMap.values())
        .sort((a, b) => b.adsCount - a.adsCount)
        .slice(0, 10);
    const adsByState = Array.from(adsByStateMap.values()).sort((a, b) => b.count - a.count);

    return {
        totalLocations,
        totalAds,
        totalUsers,
        topCities,
        adsByState,
        hotZones,
        monthlyTrends: trends.map(t => ({
            month: t.month,
            ads: t.adsPosted,
            users: t.activeUsers,
        })),
    };
};

import { z } from 'zod';
import logger from '../utils/logger';
import { env } from '../config/env';
import { AIProviderFactory } from './ai/AIProviderFactory';
import { getAiConfig } from '../config/ai';
import { generateListingPromptV1, identifyDevicePromptV1 } from '../prompts/listings/v1';
import { moderateAdPromptV1 } from '../prompts/moderation/v1';
import { MAX_AD_TITLE_CHARS, MAX_AD_DESCRIPTION_CHARS } from '@esparex/contracts';
import { AiErrorCode } from '@esparex/contracts/v1/common/enums';
import { getCache, setCache } from '../utils/redisCache';
import { AIServiceFailure, buildFallbackListingContent, mapProviderError } from './ai/aiFallback';

export type { AIServiceFailure };
export { buildFallbackListingContent };

export type AIRequestType = 'identify' | 'generate' | 'moderate';

export type AIRequestBody = {
    type?: string;
    context?: Record<string, unknown>;
    image?: string;
};

export type AIServiceSuccess = {
    ok: true;
    data: Record<string, unknown>;
};

export type AIServiceResult = AIServiceSuccess | AIServiceFailure;

type ExecuteAiRequestInput = {
    type: AIRequestType;
    context: Record<string, unknown>;
    image?: string;
    contextText: string;
};

export const AI_REQUEST_TIMEOUT_MS = env.AI_REQUEST_TIMEOUT_MS ?? 6000;
export const AI_MAX_IMAGE_BYTES = env.AI_MAX_IMAGE_BYTES ?? (4 * 1024 * 1024);

const AI_QUOTA_CACHE_KEY = 'sys:ai:quota_exhausted';
const AI_QUOTA_COOLDOWN_SECONDS = 60;

export const isAIRequestType = (value: unknown): value is AIRequestType =>
    value === 'identify' || value === 'generate' || value === 'moderate';

export const getAiContext = (body: AIRequestBody): {
    context: Record<string, unknown>;
    image?: string;
    contextText: string;
} => {
    const context = body?.context && typeof body.context === 'object' ? body.context : {};
    const rootImage = typeof body?.image === 'string' ? body.image : undefined;
    const contextImage = typeof context.image === 'string' ? context.image : undefined;
    const image = rootImage || contextImage;
    const contextText = typeof context.text === 'string' ? context.text : '';

    return { context, image, contextText };
};

const toServiceFailure = (response: AIServiceFailure): AIServiceFailure => response;

const hasKeyForProvider = (providerName: string, config: { geminiApiKey?: string; openAiApiKey?: string; claudeApiKey?: string; deepseekApiKey?: string }): boolean => {
    switch (providerName.toLowerCase()) {
        case 'gemini':
            return Boolean(config.geminiApiKey);
        case 'openai':
            return Boolean(config.openAiApiKey);
        case 'claude':
        case 'anthropic':
            return Boolean(config.claudeApiKey);
        case 'deepseek':
            return Boolean(config.deepseekApiKey);
        default:
            return false;
    }
};

export const getStatus = async (): Promise<{ available: boolean; reason: string | null; retryAfter: number }> => {
    const config = await getAiConfig();
    const hasAnyKey = Boolean(config.geminiApiKey || config.openAiApiKey || config.claudeApiKey || config.deepseekApiKey);
    if (!hasAnyKey) {
        return { available: false, reason: AiErrorCode.AI_UNAVAILABLE, retryAfter: 0 };
    }

    const quotaExhausted = await getCache(AI_QUOTA_CACHE_KEY);
    if (quotaExhausted) {
        return { available: false, reason: AiErrorCode.AI_QUOTA_EXHAUSTED, retryAfter: AI_QUOTA_COOLDOWN_SECONDS };
    }

    return { available: true, reason: null, retryAfter: 0 };
};

export const executeAiRequest = async (input: ExecuteAiRequestInput): Promise<AIServiceResult> => {
    const t0 = Date.now();
    const { type, context, image, contextText } = input;

    if (type === 'generate' && !context.brand && !context.model) {
        return toServiceFailure({ ok: false, status: 400, error: 'Brand and Model context are required for generation' });
    }

    const status = await getStatus();
    if (!status.available) {
        return toServiceFailure({
            ok: false,
            status: status.reason === AiErrorCode.AI_QUOTA_EXHAUSTED ? 429 : 503,
            error: 'AI service unavailable',
            code: status.reason || AiErrorCode.AI_UNAVAILABLE
        });
    }

    const config = await getAiConfig();
    const tConfig = Date.now() - t0;

    const capabilityKeyMap: Record<AIRequestType, string> = {
        identify: 'device_identification',
        generate: 'post_ad_title',
        moderate: 'content_moderation',
    };
    const capabilityKey = capabilityKeyMap[type] || 'post_ad_title';
    const capabilityConfig = (config.capabilities as Record<string, any>)?.[capabilityKey];

    const primaryProvider = capabilityConfig?.provider || config.provider || 'gemini';
    const fallbackCandidates = ['gemini', 'openai', 'claude', 'deepseek'];
    const rawChain = [primaryProvider, ...fallbackCandidates.filter(p => p !== primaryProvider)];
    const providerChain = rawChain.filter(p => hasKeyForProvider(p, config));

    if (providerChain.length === 0) {
        return toServiceFailure({
            ok: false,
            status: 503,
            error: 'AI service unavailable: no active providers with configured API keys found.',
            code: AiErrorCode.AI_UNAVAILABLE
        });
    }

    let lastError: unknown = null;

    for (const providerName of providerChain) {
        try {
            const provider = AIProviderFactory.create(providerName);

            if (type === 'identify') {
                const rawText = typeof contextText === 'string' ? contextText : '';
                const cacheKey = `sys:ai:identify_cache:${Buffer.from(rawText.trim().toLowerCase()).toString('base64').slice(0, 48)}`;
                const cachedResult = await getCache<Record<string, unknown>>(cacheKey);
                if (cachedResult) {
                    logger.info('[AiService] identify cache hit', {
                        type,
                        contextText: rawText,
                        totalMs: Date.now() - t0,
                    });
                    return { ok: true, data: cachedResult };
                }

                const prompt = identifyDevicePromptV1(rawText);
                const schema = z.object({
                    brand: z.string(),
                    model: z.string(),
                    confidence: z.number().optional()
                });

                const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });
                const totalMs = Date.now() - t0;
                logger.info('[AiService] identify telemetry', {
                    type,
                    provider: result.provider,
                    model: result.model,
                    wasFallback: providerName !== primaryProvider,
                    llmLatencyMs: result.latency,
                    configLookupMs: tConfig,
                    totalMs,
                    usage: result.usage,
                });

                await setCache(cacheKey, JSON.stringify(result.data), 1800);

                return { ok: true, data: result.data as Record<string, unknown> };
            }

            if (type === 'generate') {
                const normalizedKey = JSON.stringify(context, Object.keys(context).sort());
                const cacheKey = `sys:ai:generate_cache:${Buffer.from(normalizedKey).toString('base64').slice(0, 64)}`;
                const cachedResult = await getCache<Record<string, unknown>>(cacheKey);
                if (cachedResult) {
                    logger.info('[AiService] generate cache hit', {
                        type,
                        totalMs: Date.now() - t0,
                    });
                    return { ok: true, data: cachedResult };
                }

                const prompt = generateListingPromptV1(context);
                const schema = z.object({
                    title: z.string().max(MAX_AD_TITLE_CHARS),
                    description: z.string().max(MAX_AD_DESCRIPTION_CHARS)
                });

                const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });
                const totalMs = Date.now() - t0;
                logger.info('[AiService] generate telemetry', {
                    type,
                    provider: result.provider,
                    model: result.model,
                    wasFallback: providerName !== primaryProvider,
                    llmLatencyMs: result.latency,
                    configLookupMs: tConfig,
                    totalMs,
                    usage: result.usage,
                });

                await setCache(cacheKey, JSON.stringify(result.data), 3600);

                return { ok: true, data: result.data as Record<string, unknown> };
            }

            if (type === 'moderate') {
                const prompt = moderateAdPromptV1(contextText);
                const schema = z.object({
                    safe: z.boolean(),
                    reason: z.string().nullable()
                });

                const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });
                const totalMs = Date.now() - t0;
                logger.info('[AiService] moderate telemetry', {
                    type,
                    provider: result.provider,
                    model: result.model,
                    wasFallback: providerName !== primaryProvider,
                    llmLatencyMs: result.latency,
                    configLookupMs: tConfig,
                    totalMs,
                    usage: result.usage,
                });

                return { ok: true, data: result.data as Record<string, unknown> };
            }
        } catch (error) {
            lastError = error;
            logger.warn(`[AiService] Provider '${providerName}' failed, trying next candidate in chain`, {
                failedProvider: providerName,
                capability: capabilityKey,
                error: error instanceof Error ? error.message : String(error),
            });
        }
    }

    logger.warn('[AiService] All providers in fallback chain failed or unavailable', { error: lastError, totalMs: Date.now() - t0 });

    if (type === 'generate') {
        const fallbackData = buildFallbackListingContent(context);
        logger.info('[AiService] Provided instant fallback listing content after provider failure', { totalMs: Date.now() - t0 });
        return { ok: true, data: fallbackData };
    }

    const serviceFailure = mapProviderError(lastError);

    if (serviceFailure.code === AiErrorCode.AI_QUOTA_EXHAUSTED) {
        await setCache(AI_QUOTA_CACHE_KEY, '1', AI_QUOTA_COOLDOWN_SECONDS);
    }

    return serviceFailure;
};

import GoogleAdPlacement from "../models/GoogleAdPlacement";
import { GOOGLE_AD_STATUS, type GoogleAdPlacementDTO } from "@esparex/contracts";
import { AppError } from "../utils/AppError";
import { getCache, setCache, delCache } from "../utils/redisCache";

const PUBLIC_ADS_CACHE_KEY = "sys:google_ads:active_placements";
const PUBLIC_ADS_CACHE_TTL = 300; // 5 minutes

export const serializeGoogleAdPlacement = (doc: any): GoogleAdPlacementDTO => {
    return {
        id: doc._id.toString(),
        placementKey: doc.placementKey,
        name: doc.name,
        adSlotId: doc.adSlotId,
        publisherClientId: doc.publisherClientId,
        location: doc.location,
        format: doc.format,
        status: doc.status,
        viewports: doc.viewports || ["desktop", "tablet", "mobile"],
        priority: doc.priority || 0,
        fallbackStrategy: doc.fallbackStrategy,
        fallbackImageUri: doc.fallbackImageUri,
        fallbackTargetUrl: doc.fallbackTargetUrl,
        startDate: doc.startDate ? new Date(doc.startDate).toISOString() : undefined,
        endDate: doc.endDate ? new Date(doc.endDate).toISOString() : undefined,
        impressionsCount: doc.impressionsCount || 0,
        clicksCount: doc.clicksCount || 0,
        isDeleted: doc.isDeleted || false,
        createdAt: doc.createdAt ? new Date(doc.createdAt).toISOString() : undefined,
        updatedAt: doc.updatedAt ? new Date(doc.updatedAt).toISOString() : undefined,
    };
};

export const getAdminGoogleAdPlacements = async (params: {
    location?: string;
    status?: string;
    search?: string;
    skip?: number;
    limit?: number;
}) => {
    const query: Record<string, unknown> = { isDeleted: { $ne: true } };

    if (params.status && params.status !== "all") {
        query.status = params.status;
    }
    if (params.location && params.location !== "all") {
        query.location = params.location;
    }
    if (params.search) {
        const regex = new RegExp(params.search.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i");
        query.$or = [{ name: regex }, { placementKey: regex }, { adSlotId: regex }];
    }

    const skip = params.skip || 0;
    const limit = params.limit || 20;

    const [items, total] = await Promise.all([
        GoogleAdPlacement.find(query).sort({ priority: -1, createdAt: -1 }).skip(skip).limit(limit),
        GoogleAdPlacement.countDocuments(query),
    ]);

    return {
        items: items.map(serializeGoogleAdPlacement),
        total,
    };
};

export const getPublicActiveGoogleAdPlacements = async () => {
    const cached = await getCache<GoogleAdPlacementDTO[]>(PUBLIC_ADS_CACHE_KEY);
    if (cached) {
        return cached;
    }

    const now = new Date();
    const query = {
        status: GOOGLE_AD_STATUS.ACTIVE,
        isDeleted: { $ne: true },
        $or: [
            { startDate: { $exists: false } },
            { startDate: null },
            { startDate: { $lte: now } },
        ],
        $and: [
            {
                $or: [
                    { endDate: { $exists: false } },
                    { endDate: null },
                    { endDate: { $gte: now } },
                ],
            },
        ],
    };

    const items = await GoogleAdPlacement.find(query).sort({ priority: -1 });
    const serialized = items.map(serializeGoogleAdPlacement);
    await setCache(PUBLIC_ADS_CACHE_KEY, JSON.stringify(serialized), PUBLIC_ADS_CACHE_TTL);
    return serialized;
};

export const createGoogleAdPlacement = async (data: Partial<GoogleAdPlacementDTO>) => {
    const existing = await GoogleAdPlacement.findOne({ placementKey: data.placementKey, isDeleted: { $ne: true } });
    if (existing) {
        throw new AppError(`Placement with key '${data.placementKey}' already exists`, 400);
    }

    const placement = new GoogleAdPlacement({
        ...data,
        isDeleted: false,
    });

    await placement.save();
    await delCache(PUBLIC_ADS_CACHE_KEY);
    return serializeGoogleAdPlacement(placement);
};

export const updateGoogleAdPlacement = async (id: string, data: Partial<GoogleAdPlacementDTO>) => {
    const placement = await GoogleAdPlacement.findOne({ _id: id, isDeleted: { $ne: true } });
    if (!placement) {
        throw new AppError("Ad placement not found", 404);
    }

    if (data.placementKey && data.placementKey !== placement.placementKey) {
        const duplicate = await GoogleAdPlacement.findOne({
            placementKey: data.placementKey,
            _id: { $ne: id },
            isDeleted: { $ne: true },
        });
        if (duplicate) {
            throw new AppError(`Placement key '${data.placementKey}' is taken`, 400);
        }
    }

    Object.assign(placement, data);
    await placement.save();
    await delCache(PUBLIC_ADS_CACHE_KEY);
    return serializeGoogleAdPlacement(placement);
};

export const mutateGoogleAdPlacementStatus = async (id: string, status: string) => {
    const placement = await GoogleAdPlacement.findOne({ _id: id, isDeleted: { $ne: true } });
    if (!placement) {
        throw new AppError("Ad placement not found", 404);
    }

    placement.status = status;
    await placement.save();
    await delCache(PUBLIC_ADS_CACHE_KEY);
    return serializeGoogleAdPlacement(placement);
};

export const deleteGoogleAdPlacement = async (id: string) => {
    const placement = await GoogleAdPlacement.findOne({ _id: id, isDeleted: { $ne: true } });
    if (!placement) {
        throw new AppError("Ad placement not found", 404);
    }

    placement.isDeleted = true;
    await placement.save();
    await delCache(PUBLIC_ADS_CACHE_KEY);
    return true;
};

import { Types } from "mongoose";
import {
    getAdvertisementCampaignModel,
    getMonetizationConfigModel,
    IAdvertisementCampaign,
} from "../models/AdvertisementCampaign";
import type {
    AdCampaignItem,
    MonetizationSystemState,
    ResolveAdRequest,
    ResolveAdResponse,
} from "@esparex/contracts";

type QueryFilter<T = unknown> = Record<string, unknown>;

interface RawCampaignDoc extends Omit<Partial<IAdvertisementCampaign>, "_id"> {
    _id?: Types.ObjectId | string;
    id?: string;
}

const mapDocToCampaignItem = (doc: RawCampaignDoc): AdCampaignItem => ({
    id: String(doc._id || doc.id || ""),
    name: doc.name || "",
    placementId: doc.placementId || "listing_detail_sidebar_bottom",
    providerType: doc.providerType || "google_adsense",
    priority: doc.priority || 1,
    status: doc.status || "active",
    startAt: doc.startAt ? new Date(doc.startAt).toISOString() : undefined,
    endAt: doc.endAt ? new Date(doc.endAt).toISOString() : undefined,
    targeting: doc.targeting || {},
    frequency: doc.frequency,
    rendering: doc.rendering,
    providerConfig: doc.providerConfig || {},
    metrics: doc.metrics,
    createdAt: doc.createdAt ? new Date(doc.createdAt).toISOString() : new Date().toISOString(),
    updatedAt: doc.updatedAt ? new Date(doc.updatedAt).toISOString() : new Date().toISOString(),
});

export class MonetizationService {
    /**
     * Resolve the most appropriate active campaign for a given placement context
     */
    static async resolveAd(request: ResolveAdRequest): Promise<ResolveAdResponse> {
        const configModel = getMonetizationConfigModel();
        const config = await configModel.findOne().lean();

        // If advertising is globally disabled
        if (config && (!config.featureEnabled || !config.publishingEnabled)) {
            return { ad: null, fallbackAd: null, renderedProvider: "none" };
        }

        const campaignModel = getAdvertisementCampaignModel();
        const now = new Date();

        // Query active campaigns for this placement
        const query: QueryFilter<IAdvertisementCampaign> = {
            placementId: request.placementId,
            status: "active",
            $and: [
                {
                    $or: [
                        { startAt: null },
                        { startAt: { $lte: now } },
                    ],
                },
                {
                    $or: [
                        { endAt: null },
                        { endAt: { $gte: now } },
                    ],
                },
            ],
        };

        const activeCampaigns = await campaignModel
            .find(query)
            .sort({ priority: 1, createdAt: -1 })
            .lean();

        if (!activeCampaigns || activeCampaigns.length === 0) {
            return { ad: null, fallbackAd: null, renderedProvider: "none" };
        }

        // Filter by targeting criteria
        const matchingCampaigns = activeCampaigns.filter((campaign) => {
            const targeting = campaign.targeting;
            if (!targeting) return true;

            // Device targeting
            if (targeting.device && targeting.device !== "all") {
                if (request.device && request.device !== targeting.device) {
                    return false;
                }
            }

            // Location targeting (State / City)
            if (targeting.states && targeting.states.length > 0 && request.location?.state) {
                const matchState = targeting.states.some(
                    (s) => s.toLowerCase() === request.location?.state?.toLowerCase()
                );
                if (!matchState) return false;
            }

            if (targeting.cities && targeting.cities.length > 0 && request.location?.city) {
                const matchCity = targeting.cities.some(
                    (c) => c.toLowerCase() === request.location?.city?.toLowerCase()
                );
                if (!matchCity) return false;
            }

            // Category targeting
            if (targeting.categories && targeting.categories.length > 0 && request.category) {
                const matchCat = targeting.categories.some(
                    (cat) => cat.toLowerCase() === request.category?.toLowerCase()
                );
                if (!matchCat) return false;
            }

            // User type targeting
            if (targeting.userType && targeting.userType !== "all") {
                if (targeting.userType === "authenticated" && !request.isAuthenticated) return false;
                if (targeting.userType === "guest" && request.isAuthenticated) return false;
                if (targeting.userType === "business" && !request.isBusiness) return false;
            }

            return true;
        });

        if (matchingCampaigns.length === 0) {
            return { ad: null, fallbackAd: null, renderedProvider: "none" };
        }

        const primaryDoc = matchingCampaigns[0];
        const fallbackDoc = matchingCampaigns[1] || null;

        const primaryAd = mapDocToCampaignItem(primaryDoc as RawCampaignDoc);
        const fallbackAd = fallbackDoc ? mapDocToCampaignItem(fallbackDoc as RawCampaignDoc) : null;

        return {
            ad: primaryAd,
            fallbackAd,
            renderedProvider: primaryAd.providerType,
        };
    }

    /**
     * Record an ad impression
     */
    static async recordImpression(campaignId: string): Promise<void> {
        const campaignModel = getAdvertisementCampaignModel();
        await campaignModel.findByIdAndUpdate(campaignId, {
            $inc: { "metrics.impressions": 1 },
            $set: { "metrics.lastServedAt": new Date() },
        });
    }

    /**
     * Record an ad click and update CTR
     */
    static async recordClick(campaignId: string): Promise<void> {
        const campaignModel = getAdvertisementCampaignModel();
        const campaign = await campaignModel.findById(campaignId);
        if (!campaign) return;

        const impressions = Math.max(1, (campaign.metrics?.impressions || 0) + 1);
        const clicks = (campaign.metrics?.clicks || 0) + 1;
        const ctr = Number(((clicks / impressions) * 100).toFixed(2));

        await campaignModel.findByIdAndUpdate(campaignId, {
            $set: {
                "metrics.clicks": clicks,
                "metrics.ctr": ctr,
            },
        });
    }

    /**
     * Admin: Get all campaigns
     */
    static async getAdminCampaigns(): Promise<AdCampaignItem[]> {
        const campaignModel = getAdvertisementCampaignModel();
        const docs = await campaignModel.find().sort({ priority: 1, createdAt: -1 }).lean();
        return docs.map((doc) => mapDocToCampaignItem(doc as RawCampaignDoc));
    }

    /**
     * Admin: Create campaign
     */
    static async createCampaign(data: Partial<AdCampaignItem>): Promise<AdCampaignItem> {
        const campaignModel = getAdvertisementCampaignModel();
        const created = await campaignModel.create(data);
        return {
            id: String(created._id),
            name: created.name,
            placementId: created.placementId,
            providerType: created.providerType,
            priority: created.priority,
            status: created.status,
            startAt: created.startAt ? new Date(created.startAt).toISOString() : undefined,
            endAt: created.endAt ? new Date(created.endAt).toISOString() : undefined,
            targeting: created.targeting || {},
            frequency: created.frequency,
            rendering: created.rendering,
            providerConfig: created.providerConfig || {},
            metrics: created.metrics,
            createdAt: created.createdAt.toISOString(),
            updatedAt: created.updatedAt.toISOString(),
        };
    }

    /**
     * Admin: Update campaign
     */
    static async updateCampaign(id: string, data: Partial<AdCampaignItem>): Promise<AdCampaignItem | null> {
        const campaignModel = getAdvertisementCampaignModel();
        const updated = await campaignModel.findByIdAndUpdate(id, { $set: data }, { new: true });
        if (!updated) return null;
        return {
            id: String(updated._id),
            name: updated.name,
            placementId: updated.placementId,
            providerType: updated.providerType,
            priority: updated.priority,
            status: updated.status,
            startAt: updated.startAt ? new Date(updated.startAt).toISOString() : undefined,
            endAt: updated.endAt ? new Date(updated.endAt).toISOString() : undefined,
            targeting: updated.targeting || {},
            frequency: updated.frequency,
            rendering: updated.rendering,
            providerConfig: updated.providerConfig || {},
            metrics: updated.metrics,
            createdAt: updated.createdAt.toISOString(),
            updatedAt: updated.updatedAt.toISOString(),
        };
    }

    /**
     * Admin: Delete campaign
     */
    static async deleteCampaign(id: string): Promise<boolean> {
        const campaignModel = getAdvertisementCampaignModel();
        const result = await campaignModel.findByIdAndDelete(id);
        return Boolean(result);
    }

    /**
     * Admin: Get Monetization System Configuration
     */
    static async getMonetizationConfig(): Promise<MonetizationSystemState> {
        const configModel = getMonetizationConfigModel();
        let config = await configModel.findOne().lean();
        if (!config) {
            config = await configModel.create({
                featureEnabled: true,
                publishingEnabled: true,
                providers: {
                    googleAdsense: { publisherId: "", autoAdsEnabled: false },
                },
            });
        }
        return {
            featureEnabled: config.featureEnabled,
            publishingEnabled: config.publishingEnabled,
            providers: config.providers || {},
        };
    }

    /**
     * Admin: Update Monetization System Configuration
     */
    static async updateMonetizationConfig(data: Partial<MonetizationSystemState>): Promise<MonetizationSystemState> {
        const configModel = getMonetizationConfigModel();
        const updated = await configModel.findOneAndUpdate(
            {},
            { $set: data },
            { upsert: true, new: true }
        );
        return {
            featureEnabled: updated.featureEnabled,
            publishingEnabled: updated.publishingEnabled,
            providers: updated.providers || {},
        };
    }
}

import type { AdminLogFn } from '../../utils/adminLogger';
import Business from '../../models/Business';
import Ad from '../../models/Ad';
import { GOVERNANCE, MS_IN_DAY } from '../../config/constants';
import { publishedBusinessStatusQuery } from '../../utils/businessStatus';
import { BUSINESS_STATUS, LISTING_STATUS, LISTING_TYPE, ACTOR_TYPE } from '@esparex/contracts';
import type { ActorMetadata } from '@esparex/contracts';
import { mutateStatuses, mutateStatus } from '../lifecycle/StatusMutationService';
import { AppError } from '../../utils/AppError';
import * as businessLifecycleService from '../business/BusinessLifecycleService';
import logger from '../../utils/logger';

import { getAdminBusinessAccountsData, transformBusinessDocs } from './helpers';

export const getBusinessOverview = async () => {
    const now = new Date();
    const thirtyDaysFromNow = new Date(Date.now() + GOVERNANCE.BUSINESS.AUTO_EXPIRE_CHECK_DAYS * MS_IN_DAY);
    const threeDaysFromNow = new Date(Date.now() + 3 * MS_IN_DAY);
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const [facetResults, timeline, topCities] = await Promise.all([
        Business.aggregate([
            {
                $facet: {
                    total: [{ $match: { isDeleted: { $ne: true } } }, { $count: 'count' }],
                    live: [{ $match: { status: BUSINESS_STATUS.LIVE, isDeleted: { $ne: true } } }, { $count: 'count' }],
                    pending: [{ $match: { status: BUSINESS_STATUS.PENDING, isDeleted: { $ne: true } } }, { $count: 'count' }],
                    suspended: [{ $match: { status: BUSINESS_STATUS.SUSPENDED, isDeleted: { $ne: true } } }, { $count: 'count' }],
                    rejected: [{ $match: { status: BUSINESS_STATUS.REJECTED, isDeleted: { $ne: true } } }, { $count: 'count' }],
                    deleted: [{ $match: { isDeleted: true } }, { $count: 'count' }],
                    expiringSoon: [
                        {
                            $match: {
                                status: publishedBusinessStatusQuery,
                                expiresAt: { $lte: thirtyDaysFromNow, $gte: now },
                                isDeleted: { $ne: true }
                            }
                        },
                        { $count: 'count' }
                    ],
                    expiringIn3Days: [
                        {
                            $match: {
                                status: publishedBusinessStatusQuery,
                                expiresAt: { $lte: threeDaysFromNow, $gte: now },
                                isDeleted: { $ne: true }
                            }
                        },
                        { $count: 'count' }
                    ]
                }
            }
        ]),
        Business.aggregate([
            { $match: { createdAt: { $gte: sevenDaysAgo }, isDeleted: { $ne: true } } },
            { $group: { _id: { $dateToString: { format: "%Y-%m-%d", date: "$createdAt" } }, count: { $sum: 1 } } },
            { $sort: { _id: 1 } }
        ]),
        Business.aggregate([
            { $match: { isDeleted: { $ne: true }, 'location.city': { $exists: true, $ne: '' } } },
            { $group: { _id: '$location.city', count: { $sum: 1 } } },
            { $sort: { count: -1, _id: 1 } },
            { $limit: 5 },
            { $project: { _id: 0, city: '$_id', count: 1 } }
        ])
    ]);

    const res = facetResults[0] || {};
    const extractCount = (arr?: Array<{ count: number }>) => arr?.[0]?.count ?? 0;

    return {
        total: extractCount(res.total),
        pending: extractCount(res.pending),
        live: extractCount(res.live),
        suspended: extractCount(res.suspended),
        rejected: extractCount(res.rejected),
        deleted: extractCount(res.deleted),
        expiringSoon: extractCount(res.expiringSoon),
        expiringIn3Days: extractCount(res.expiringIn3Days),
        analytics: { timeline, topCities }
    };
};

export const getAdminBusinessAccounts = async (params: {
    status?: string;
    locationId?: string;
    search?: string;
    expiringIn3Days?: string;
    warningSent?: string;
    warningNotSent?: string;
    skip: number;
    limit: number;
    includeDeleted?: string;
}) => {
    const { adminQuery } = await getAdminBusinessAccountsData(params);

    if (params.search) {
        const { escapeRegExp } = require('../../utils/stringUtils');
        const safeSearch = escapeRegExp(params.search);
        adminQuery.$or = [
            { name: { $regex: safeSearch, $options: 'i' } },
            { email: { $regex: safeSearch, $options: 'i' } },
            { mobile: { $regex: safeSearch, $options: 'i' } },
            { 'location.city': { $regex: safeSearch, $options: 'i' } },
        ];
    }

    const shouldIncludeDeleted = params.status === BUSINESS_STATUS.DELETED || params.status === 'all' || params.includeDeleted === 'true';

    const [rawItems, total] = await Promise.all([
        Business.find(adminQuery)
            .skip(params.skip)
            .limit(params.limit)
            .sort({ createdAt: -1 })
            .populate('userId')
            .setOptions(shouldIncludeDeleted ? { withDeleted: true } : {}),
        Business.countDocuments(adminQuery)
            .setOptions(shouldIncludeDeleted ? { withDeleted: true } : {}),
    ]);

    const items = transformBusinessDocs(rawItems);
    return { items, total };
};

export const getAdminBusinessById = async (id: string) => Business.findOne({ _id: id }).setOptions({ withDeleted: true }).populate('userId');
export const findBusinessForAdmin = async (id: string) => Business.findById(id);

export const cascadeExpireBusinessListings = async (businessId: unknown, actor: { type?: string; id?: string }, reason: string) => {
    const nid = typeof businessId === 'string' && businessId.trim() ? businessId.trim() : businessId?.toString?.();
    if (!nid) return 0;
    const na: ActorMetadata = { type: (actor.type === ACTOR_TYPE.ADMIN || actor.type === ACTOR_TYPE.SYSTEM) ? actor.type : ACTOR_TYPE.USER, id: actor.id };
    const listings = await Ad.find({ businessId: nid, status: { $ne: LISTING_STATUS.EXPIRED } }).select('_id listingType');
    if (listings.length > 0) await mutateStatuses(listings.map((l) => ({ domain: l.listingType === LISTING_TYPE.SERVICE ? LISTING_TYPE.SERVICE : l.listingType === LISTING_TYPE.SPARE_PART ? 'spare_part_listing' : LISTING_TYPE.AD, entityId: l._id.toString(), toStatus: LISTING_STATUS.EXPIRED, actor: na, reason })));
    return listings.length;
};

export const approveAdminBusiness = async (id: string, actorId: string, logFn: AdminLogFn) => {
    const business = await businessLifecycleService.approveBusiness(id, actorId);
    if (!business) throw new AppError('Business not found', 404);
    await logFn('APPROVE_BUSINESS', 'Business', id, { expiresAt: business.expiresAt });
    const { dispatchTemplatedNotification } = await import('../../domains/notifications/application/NotificationService');
    const { recalculateTrustScore } = await import('../TrustService');
    const { assignDefaultPlan } = await import('../business/BusinessSubscriptionService');

    const userIdStr = String(business.userId ?? '');
    const businessIdStr = String(business._id ?? '');
    await dispatchTemplatedNotification(userIdStr, 'BUSINESS_STATUS', 'BUSINESS_APPROVED', { name: String(business.name ?? '') }, { businessId: businessIdStr, status: String(BUSINESS_STATUS.LIVE) });

    // Assign default business plan dynamically (wrapped so errors don't block approval)
    try {
        await assignDefaultPlan(userIdStr);
    } catch (planErr) {
        logger.error('Failed to assign default business plan on approval', {
            businessId: id,
            userId: business.userId,
            error: planErr instanceof Error ? planErr.message : String(planErr)
        });
    }

    setImmediate(() => void recalculateTrustScore(userIdStr).catch(() => {}));
    return business;
};


export const rejectAdminBusiness = async (id: string, reason: string, actorId: string, logFn: AdminLogFn) => {
    if (!reason) throw new AppError('Rejection reason is required', 400);
    const business = await businessLifecycleService.rejectBusiness(id, reason, actorId);
    if (!business) throw new AppError('Business not found', 404);
    await logFn('REJECT_BUSINESS', 'Business', id, { reason });
    const { dispatchTemplatedNotification } = await import('../../domains/notifications/application/NotificationService');
