#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'GOV-GUARDS-001', name: 'Platform Governance Guards Suite', version: '1.0.0', category: 'Governance' };

const BASELINE_PATH = path.join(ROOT, 'scripts/policy/governance-debt-baseline.json');
let baseline = { baselines: {} };
if (fs.existsSync(BASELINE_PATH)) {
  try {
    baseline = JSON.parse(fs.readFileSync(BASELINE_PATH, 'utf-8'));
  } catch {
    // ignore corrupted or missing baseline
  }
}

const GUARDS = [
  { name: 'Naming Conventions', cmd: 'node scripts/enforce-file-naming-conventions.js', baselineKey: 'namingViolations' },
  { name: 'Platform Governance', cmd: 'node scripts/guard-platform-governance.js', baselineKey: 'platformGovernanceViolations' },
  { name: 'Admin Status Literals', cmd: 'node scripts/enforce-admin-status-literals.js', baselineKey: 'adminStatusLiteralViolations' },
  { name: 'ObjectId Validation', cmd: 'node scripts/enforce-objectid-validation.js', baselineKey: 'objectIdViolations' },
  { name: 'Notification Governance', cmd: 'node scripts/enforce-notification-governance.js', baselineKey: 'notificationViolations' },
  { name: 'API Surface Guard', cmd: 'node scripts/enforce-api-surface-guard.js', baselineKey: 'apiSurfaceViolations' },
  { name: 'Component API Boundary', cmd: 'node scripts/enforce-component-api-boundary.js', baselineKey: 'componentBoundaryViolations' },
  { name: 'Compatibility Markers Baseline', cmd: 'node scripts/enforce-compatibility-markers-baseline.js', baselineKey: 'compatibilityViolations' },
  { name: 'Generated Artifacts', cmd: 'node scripts/guard-generated-artifacts.js', baselineKey: 'artifactViolations' },
  { name: 'API Contract Parity', cmd: 'node scripts/verify-api-contract.js --scope=all', baselineKey: 'apiContractViolations' },
];

function run(val) {
  let passedCount = 0;
  let newErrorsCount = 0;

  for (const g of GUARDS) {
    try {
      execSync(g.cmd, { cwd: ROOT, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
      passedCount++;
    } catch (e) {
      const output = (e.stdout || '') + (e.stderr || '');
      const itemLines = output.trim().split('\n').filter(l => {
        const trimmed = l.trim();
        return (trimmed.startsWith('-') || trimmed.startsWith('apps/') || trimmed.startsWith('packages/') || trimmed.includes('literal=')) && !trimmed.startsWith('❌') && !trimmed.startsWith('[HINT]') && !trimmed.startsWith('FAIL:');
      });

      const grandfatheredList = baseline.baselines[g.baselineKey] || [];
      let newViolationsForGuard = [];

      for (const line of itemLines) {
        const isGrandfathered = grandfatheredList.some(item => line.includes(item));
        if (isGrandfathered) {
          val.warning(`Grandfathered Debt [${g.name}]: ${line.trim()}`);
        } else {
          newViolationsForGuard.push(line.trim());
        }
      }

      if (newViolationsForGuard.length > 0) {
        newErrorsCount++;
        for (const unbaselined of newViolationsForGuard) {
          val.error(`NEW Governance Violation [${g.name}]: ${unbaselined}`);
        }
      } else if (itemLines.length > 0) {
        passedCount++;
      } else {
        newErrorsCount++;
        val.error(`NEW Governance Violation [${g.name}]: Check failed with unparseable output`);
      }
    }
  }

  if (newErrorsCount === 0) {
    val.info(`Platform Governance Guards Suite passed ratchet check (${passedCount}/${GUARDS.length} clean, baseline debt tracked)`);
  } else {
    val.error(`Platform Governance Guards Suite failed ratchet check (${newErrorsCount} new violation categories detected)`);
  }
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'ROUTE-001', name: 'Route Validation', version: '1.0.0', category: 'API' };

function run(val) {
  const changedFiles = (() => {
    try {
      const out = execSync('git diff --cached --name-only --diff-filter=ACMR', { cwd: ROOT, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
      return out.split('\n').filter(Boolean);
    } catch { return []; }
  })();

  const routeFiles = changedFiles.filter(f =>
    (f.endsWith('.ts') || f.endsWith('.js')) &&
    (f.includes('/routes/') || f.includes('/router') || f.endsWith('-routes.ts') || f.endsWith('.route.ts'))
  );

  if (routeFiles.length === 0) return;

  const routes = new Map();
  for (const file of routeFiles) {
    const fullPath = path.join(ROOT, file);
    if (!fs.existsSync(fullPath)) continue;
    const content = fs.readFileSync(fullPath, 'utf-8');
    const routeMatches = content.match(/(?:router|route)\.(?:get|post|put|patch|delete|options)\s*\(\s*['"`](\/[^'"`]*)['"`]/gi);
    if (routeMatches) {
      for (const match of routeMatches) {
        const parts = match.split(/['"`]/);
        if (parts.length >= 2) {
          const routePath = parts[1];
          if (routes.has(routePath)) {
            val.error(`Duplicate route "${routePath}" in ${file} and ${routes.get(routePath)}`);
          } else {
            routes.set(routePath, file);
          }
        }
      }
    }
  }
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'SCRIPT-001', name: 'Script & Export Parity Governance', version: '1.0.0', category: 'Governance' };

function run(val) {
  // 1. Package Export Source Parity Check
  // Ensures every exported subpath in package.json has a corresponding source file in src/
  const packageJsons = [
    path.join(ROOT, 'core/package.json'),
    path.join(ROOT, 'shared/package.json'),
    path.join(ROOT, 'packages/contracts/package.json'),
    path.join(ROOT, 'packages/design-tokens/package.json'),
    path.join(ROOT, 'packages/ui/package.json'),
    path.join(ROOT, 'packages/mobile-ui/package.json')
  ];

  let verifiedExports = 0;
  for (const pkgPath of packageJsons) {
    if (!fs.existsSync(pkgPath)) continue;
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    const pkgDir = path.dirname(pkgPath);
    if (pkg.exports && typeof pkg.exports === 'object') {
      for (const [subpath, exportTarget] of Object.entries(pkg.exports)) {
        let targetImport = typeof exportTarget === 'string' ? exportTarget : (exportTarget.import || exportTarget.default || exportTarget.require);
        if (targetImport && !targetImport.includes('*')) {
          const relDist = targetImport.replace(/^\.\/dist\//, '').replace(/\.js$/, '');
          const possibleSrc = [
            path.join(pkgDir, 'src', `${relDist}.ts`),
            path.join(pkgDir, 'src', `${relDist}.tsx`),
            path.join(pkgDir, 'src', relDist, 'index.ts'),
            path.join(pkgDir, 'src', relDist, 'index.tsx'),
            path.join(pkgDir, `${relDist}.ts`),
            path.join(pkgDir, 'dist', `${relDist}.js`),
            path.join(pkgDir, 'scripts', 'generate-css.ts'),
            path.join(pkgDir, targetImport)
          ];
          const exists = possibleSrc.some(p => fs.existsSync(p));
          if (!exists) {
            val.error(`Export parity violation in ${path.relative(ROOT, pkgPath)}: export '${subpath}' target '${targetImport}' has no source file.`);
          } else {
            verifiedExports++;
          }
        }
      }
    }
  }

  // 2. Scratch Directory Blocker
  const scratchDir = path.join(ROOT, 'scratch');
  if (fs.existsSync(scratchDir)) {
    const scratchFiles = fs.readdirSync(scratchDir).filter(f => !f.startsWith('.'));
    if (scratchFiles.length > 0) {
      val.error(`Uncommitted scratch directory detected with ${scratchFiles.length} file(s). Scratch files must not be committed.`);
    }
  }

  // 3. Automated Zero-Capacitor Script Check
  const mobileGuard = path.join(ROOT, 'scripts/enforce-mobile-architecture-guard.js');
  if (!fs.existsSync(mobileGuard)) {
    val.error('Missing mandatory mobile architecture guard: scripts/enforce-mobile-architecture-guard.js');
  }

  val.info(`Script & Export Parity Verified: ${verifiedExports} exports verified, zero scratch leaks.`);
}

module.exports = { meta: META, run };
if (require.main === module) runStandalone(META, run);

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'SSOT-001', name: 'SSOT & Canonical Ownership', version: '2.0.0', category: 'Architecture' };

function run(val) {
  // 1. Dynamic Canonical Symbol Discovery from Package Boundaries
  // Scans packages/*, shared/, core/ for exported symbols to dynamically determine canonical ownership
  const PACKAGE_DIRS = [
    { dir: 'packages/ui', name: '@esparex/ui' },
    { dir: 'packages/contracts', name: '@esparex/contracts' },
    { dir: 'shared', name: '@esparex/shared' },
    { dir: 'core', name: '@esparex/core' },
  ];

  const canonicalSymbolMap = new Map(); // symbol -> packageName

  function scanExports(dir, packageName) {
    const fullDir = path.join(ROOT, dir);
    if (!fs.existsSync(fullDir)) return;

    function getFiles(current) {
      let results = [];
      const list = fs.readdirSync(current);
      for (const item of list) {
        const p = path.join(current, item);
        const stat = fs.statSync(p);
        if (stat.isDirectory()) {
          if (item !== 'node_modules' && item !== 'dist' && !item.startsWith('.')) {
            results = results.concat(getFiles(p));
          }
        } else if (/\.(ts|tsx)$/.test(item) && !item.endsWith('.d.ts')) {
          results.push(p);
        }
      }
      return results;
    }

    const files = getFiles(fullDir);
    for (const file of files) {
      const content = fs.readFileSync(file, 'utf-8');
      const matches = content.matchAll(/^export\s+(?:const|function|class|interface|type|enum)\s+(\w+)/gm);
      for (const m of matches) {
        const symbol = m[1];
        if (!canonicalSymbolMap.has(symbol)) {
          canonicalSymbolMap.set(symbol, packageName);
        }
      }
    }
  }

  for (const pkg of PACKAGE_DIRS) {
    scanExports(pkg.dir, pkg.name);
  }

  // 2. Import & Ownership Analysis in Applications (apps/web, apps/admin)
  const appDirs = ['apps/web/src', 'apps/admin/src'];
  for (const appDir of appDirs) {
    const fullDir = path.join(ROOT, appDir);
    if (!fs.existsSync(fullDir)) continue;

    function checkAppFiles(current) {
      const list = fs.readdirSync(current);
      for (const item of list) {
        const p = path.join(current, item);
        const stat = fs.statSync(p);
        if (stat.isDirectory()) {
          if (item !== 'node_modules' && item !== '.next' && !item.startsWith('.')) {
            checkAppFiles(p);
          }
        } else if (/\.(ts|tsx)$/.test(item) && !item.endsWith('.d.ts')) {
          const content = fs.readFileSync(p, 'utf-8');
          const relPath = path.relative(ROOT, p);

          // Rule A: Verify imports — reject deep imports from dist
          const importMatches = content.matchAll(/from\s+['"](@esparex\/[^'"]+)['"]/g);
          for (const match of importMatches) {
            if (match[1].includes('/dist/')) {
              val.error(`Deep Import Violation: ${relPath} imports "${match[1]}". Import from package root instead.`);
            }
          }

          // Rule B: Dynamic Canonical Ownership & Import Resolution
          // Check if app file exports a local symbol that collides with a canonical package symbol
          const localExports = content.matchAll(/^export\s+(?:const|function|class|interface|type|enum)\s+(\w+)/gm);
          for (const exp of localExports) {
            const sym = exp[1];
            if (canonicalSymbolMap.has(sym)) {
              const canonicalOwner = canonicalSymbolMap.get(sym);
              // Allow local wrapper if file explicitly imports canonical symbol or contract/shared package, or is in page/route entry point, or if app is admin decoupled from backend core
              const importsCanonical =
                content.includes(`from "${canonicalOwner}"`) ||
                content.includes(`from '${canonicalOwner}'`) ||
                content.includes(`from "@esparex/contracts"`) ||
                content.includes(`from '@esparex/contracts'`) ||
                content.includes(`from "@esparex/shared"`) ||
                content.includes(`from '@esparex/shared'`) ||
                (relPath.startsWith('apps/admin/') && canonicalOwner === '@esparex/core');

              if (!importsCanonical && !relPath.includes('/app/') && !relPath.includes('/pages/')) {
                val.warning(`Canonical Ownership Violation: "${sym}" in ${relPath} collides with canonical symbol in ${canonicalOwner}. Import from ${canonicalOwner} instead.`);
              }
            }
          }
        }
      }
    }
    checkAppFiles(fullDir);
  }

  val.info('Dynamic canonical ownership and import resolution verified across workspace packages and applications');
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

