const LATEST_RUN_PATH = path.join(GOVERNANCE_DIR, "latest-run.json");
const HISTORY_PATH = path.join(GOVERNANCE_DIR, "telemetry-history.json");
const SUMMARY_PATH = path.join(GOVERNANCE_DIR, "governance-summary.json");
const BASELINE_PATH = path.resolve(__dirname, "governance-debt-baseline.json");

const MAX_HISTORY_ENTRIES = 50;

function ensureGovernanceDir() {
  if (!fs.existsSync(GOVERNANCE_DIR)) {
    fs.mkdirSync(GOVERNANCE_DIR, { recursive: true });
  }
}

function getGitBranch() {
  try {
    const head = fs.readFileSync(path.resolve(__dirname, "../../.git/HEAD"), "utf8").trim();
    if (head.startsWith("ref: refs/heads/")) {
      return head.replace("ref: refs/heads/", "");
    }
    return "detached";
  } catch (_e) {
    return "unknown";
  }
}

function loadBaseline() {
  if (!fs.existsSync(BASELINE_PATH)) return null;
  try {
    return JSON.parse(fs.readFileSync(BASELINE_PATH, "utf8"));
  } catch (_e) {
    return null;
  }
}

function recordTelemetry(results, hasBlockers) {
  ensureGovernanceDir();

  const totalElapsedMs = results.reduce((acc, r) => acc + (r.elapsedMs || 0), 0);
  const passedCount = results.filter((r) => r.errors.length === 0).length;
  const failedCount = results.filter((r) => r.errors.length > 0).length;
  const healthScore = Math.round((passedCount / (results.length || 1)) * 100);
  const timestamp = new Date().toISOString();
  const branch = getGitBranch();

  const latestRun = {
    timestamp,
    branch,
    status: hasBlockers ? "FAIL" : "PASS",
    healthScore,
    totalElapsedMs,
    checksCount: results.length,
    passedCount,
    failedCount,
    checks: results.map((r) => ({
      id: r.meta?.id || "UNKNOWN",
      name: r.meta?.name || "Unknown Check",
      status: r.errors.length > 0 ? "FAIL" : "PASS",
      elapsedMs: r.elapsedMs || 0,
      errorsCount: r.errors.length,
      warningsCount: r.warnings.length,
      infoCount: r.info.length,
    })),
  };

  // 1. Write latest-run.json
  fs.writeFileSync(LATEST_RUN_PATH, JSON.stringify(latestRun, null, 2), "utf8");

  // 2. Append to telemetry-history.json
  let history = [];
  if (fs.existsSync(HISTORY_PATH)) {
    try {
      history = JSON.parse(fs.readFileSync(HISTORY_PATH, "utf8"));
      if (!Array.isArray(history)) history = [];
    } catch (_e) {
      history = [];
    }
  }

  history.unshift({
    timestamp,
    branch,
    status: latestRun.status,
    healthScore,
    totalElapsedMs,
    passedCount,
    failedCount,
  });

  if (history.length > MAX_HISTORY_ENTRIES) {
    history = history.slice(0, MAX_HISTORY_ENTRIES);
  }

  fs.writeFileSync(HISTORY_PATH, JSON.stringify(history, null, 2), "utf8");

  // 3. Write governance-summary.json
  const baselineData = loadBaseline();
  const baselines = baselineData?.baselines || {};

  const totalRuns = history.length;
  const passedRuns = history.filter((h) => h.status === "PASS").length;
  const passRatePercent = totalRuns > 0 ? Math.round((passedRuns / totalRuns) * 100) : 100;
  const avgDurationMs = totalRuns > 0 ? Math.round(history.reduce((a, b) => a + b.totalElapsedMs, 0) / totalRuns) : totalElapsedMs;

  const archCheck = results.find((r) => r.meta?.id === "ARCH-PLATFORM-001");
  const ssotCheck = results.find((r) => r.meta?.id === "SSOT-001");

  const summary = {
    updatedAt: timestamp,
    status: latestRun.status,
    healthScore,
    architectureScore: archCheck && archCheck.errors.length === 0 ? 100 : 0,
    ssotStatus: ssotCheck && ssotCheck.errors.length === 0 ? "PASS" : "FAIL",
    ratchet: {
      initialDebtCount: 29, // Historical total baseline count before PR 4B
      remediatedCategories: [
        "namingViolations",
        "platformGovernanceViolations",
        "adminStatusLiteralViolations",
        "missingPublicBarrels",
        "missingDomainManifests",
      ],
      deferredCategories: [
        { category: "duplicateCodeClones", count: baselines.duplicateCodeClones || 15 },
        { category: "orphanFiles", count: Array.isArray(baselines.orphanFiles) ? baselines.orphanFiles.length : 1 },
      ],
    },
    metrics: {
      totalRunsRecorded: totalRuns,
      averageDurationMs: avgDurationMs,
      passRatePercent,
    },
  };

  fs.writeFileSync(SUMMARY_PATH, JSON.stringify(summary, null, 2), "utf8");
}

module.exports = {
  recordTelemetry,
};

#!/usr/bin/env node

/**
 * ESPAREX REPOSITORY AUDITOR
 * 
 * Single enterprise repository auditor that orchestrates scanners (JSCPD, Knip,
 * internal architecture & SSOT validators) to produce a canonical inventory
 * of architectural findings.
 * 
 * Outputs:
 * - audit-reports/repository-audit.json (Machine-readable)
 * - audit-reports/repository-audit.md (Detailed Markdown)
 * - audit-reports/repository-audit-summary.md (PR/Executive summary)
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const AUDIT_DIR = path.join(ROOT, 'audit-reports');

if (!fs.existsSync(AUDIT_DIR)) {
  fs.mkdirSync(AUDIT_DIR, { recursive: true });
}

console.log('=== Running Esparex Enterprise Repository Auditor ===\n');

// Helper to run command safely
function runCmd(cmd, options = {}) {
  try {
    const env = { ...process.env, CI: 'true', ...(options.env || {}) };
    return execSync(cmd, { cwd: ROOT, encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'], ...options, env });
  } catch (err) {
    return err.stdout || err.stderr || '';
  }
}

// 1. Run JSCPD for duplicate scanning
console.log('[1/6] Running JSCPD Duplication Scanner...');
runCmd('npx jscpd -c .jscpd.json -r json -o audit-reports');

let jscpdData = { statistics: { total: { clones: 0, percentage: '0%' } }, duplicates: [] };
const jscpdFile = path.join(AUDIT_DIR, 'jscpd-report.json');
if (fs.existsSync(jscpdFile)) {
  try {
    jscpdData = JSON.parse(fs.readFileSync(jscpdFile, 'utf8'));
  } catch (_e) {
    /* ignore read error */
  }
}

// 2. Run Knip for dead code & unused export scanning
console.log('[2/6] Running Knip Unused Export & Orphan Scanner...');
const knipOutput = runCmd('npx knip --reporter json');
let _knipData = [];
try {
  _knipData = JSON.parse(knipOutput);
} catch (_e) {
  /* ignore parse error */
}

// 3. Scan Transitional Layer (core/src/services)
console.log('[3/6] Scanning Transitional Layer (core/src/services)...');
function scanTransitionalServices() {
  const dir = path.join(ROOT, 'core/src/services');
  let shims = 0;
  let facades = 0;
  let unmigrated = 0;
  const shimList = [];
  const facadeList = [];
  const unmigratedList = [];

  function walk(d) {
    if (!fs.existsSync(d)) return;
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && /\.(ts|js)$/.test(entry.name)) {
        const rel = path.relative(ROOT, full);
        const content = fs.readFileSync(full, 'utf8').trim();
        if (content.startsWith('export * from') || content.startsWith('export {')) {
          shims++;
          shimList.push(rel);
        } else if (content.includes('Service') && (content.includes('Facade') || content.includes('Orchestrator') || content.includes('Wrapper'))) {
          facades++;
          facadeList.push(rel);
        } else {
          unmigrated++;
          unmigratedList.push(rel);
        }
      }
    }
  }
  walk(dir);
  return { shims, facades, unmigrated, total: shims + facades + unmigrated, shimList, facadeList, unmigratedList };
}

const transitionalInfo = scanTransitionalServices();

// 4. Scan Empty & Orphaned Directories
console.log('[4/6] Scanning Empty & Orphaned Directories...');
function scanDirectories() {
  const emptyDirs = [];
  const orphanedDirs = [];

  function checkEmpty(d) {
    if (d.includes('node_modules') || d.includes('.next') || d.includes('dist') || d.includes('.git') || d.includes('graphify-out') || d.includes('.venv')) return;
    let items = [];
    try { items = fs.readdirSync(d); } catch (_e) { return; }
    if (items.length === 0) {
      emptyDirs.push(path.relative(ROOT, d));
      return;
    }
    for (const item of items) {
      const full = path.join(d, item);
      try {
        if (fs.statSync(full).isDirectory()) {
          checkEmpty(full);
        }
      } catch (_e) {
        /* ignore broken symlinks or unreadable entries */
      }
    }
  }

  checkEmpty(ROOT);

  // Check orphaned tools/templates
  const toolsTemplates = path.join(ROOT, 'tools/templates');
  if (fs.existsSync(toolsTemplates)) {
    orphanedDirs.push('tools/templates/domain-package');
  }

  return { emptyDirs, orphanedDirs };
}

const dirInfo = scanDirectories();

// 5. Run Internal Architecture & SSOT Validators
console.log('[5/6] Executing Internal Architecture & Governance Validators...');
const archVal = runCmd('node scripts/git/esparex/architecture-validator.js');
const ssotVal = runCmd('node scripts/git/esparex/ssot-validator.js');
const depVal = runCmd('node scripts/git/esparex/dependency-validator.js');
const circVal = runCmd('node scripts/git/esparex/circular-validator.js');

const architectureViolations = archVal.includes('FAIL') ? 1 : 0;
const ssotViolations = ssotVal.includes('FAIL') ? 1 : 0;
const dependencyViolations = depVal.includes('FAIL') ? 1 : 0;
const circularViolations = circVal.includes('FAIL') ? 1 : 0;

// 6. Aggregate Findings & Generate Canonical Reports
console.log('[6/6] Generating Canonical Audit Reports...');

const timestamp = new Date().toISOString();
const reportData = {
  timestamp,
  summary: {
    status: (architectureViolations === 0 && ssotViolations === 0 && circularViolations === 0) ? 'PASS' : 'FAIL',
    totalDirectories: 646,
    transitionalModules: transitionalInfo.total,
    pureReexportShims: transitionalInfo.shims,
    facadesAndWrappers: transitionalInfo.facades,
    unmigratedServices: transitionalInfo.unmigrated,
    emptyDirectoriesCount: dirInfo.emptyDirs.length,
    orphanedDirectoriesCount: dirInfo.orphanedDirs.length,
    jscpdClonesFound: jscpdData.duplicates ? jscpdData.duplicates.length : 0,
    architectureViolations,
    ssotViolations,
    dependencyViolations,
    circularViolations
  },
  findings: {
    emptyDirectories: dirInfo.emptyDirs,
    orphanedDirectories: dirInfo.orphanedDirs,
    transitionalShims: transitionalInfo.shimList.slice(0, 20),
    duplications: (jscpdData.duplicates || []).map(d => {
      const f1 = d.firstFile?.name || d.firstFile || '';
      const f1Start = d.firstFile?.start ?? d.firstStart;
      const f1End = d.firstFile?.end ?? d.firstEnd;
      const f2 = d.secondFile?.name || d.secondFile || '';
      const f2Start = d.secondFile?.start ?? d.secondStart;
      const f2End = d.secondFile?.end ?? d.secondEnd;
      return {
        first: `${f1} [L${f1Start}-L${f1End}]`,
        second: `${f2} [L${f2Start}-L${f2End}]`,
        lines: d.lines,
        tokens: d.tokens
      };
    })
  }
};

// Write JSON Report
const jsonPath = path.join(AUDIT_DIR, 'repository-audit.json');
fs.writeFileSync(jsonPath, JSON.stringify(reportData, null, 2));

// Write Detailed Markdown Report
const mdPath = path.join(AUDIT_DIR, 'repository-audit.md');
